window.AULAS = window.AULAS || {};
window.AULAS["natalia-roteiro"] = {"titulo": "Roteiro de estudo", "subtitulo": "Prova 02 · Microbiologia: bactérias, com respostas guiadas pelos slides", "pdf": "pdf/natalia/roteiro/roteiro-prova-02.pdf", "abas": ["resumo", "quiz", "pdf"], "resumo": [{"titulo": "1. Morfologia, estrutura e identificação bacteriana", "pontos": [{"t": "Gram-positivas × Gram-negativas (questão 1)", "sub": ["Gram-positivas: parede espessa de peptidoglicano, sem membrana externa; retêm o cristal violeta após a descoloração. Base: Murray, cap. 12 (Fig. 12.4).", "Gram-negativas: parede fina de peptidoglicano, envolta por membrana externa com LPS, porinas e lipoproteínas. Perdem o cristal violeta e coram com a safranina. Base: Murray.", "Consequência clínica: a membrana externa dos Gram-negativos carrega endotoxina (LPS ou LOS), como em Aula 5, p. 36, e em Murray, cap. 25.", "Exceção: micobactérias têm parede rica em ácidos micólicos e não se coram bem pelo Gram. Usam Ziehl-Neelsen (Murray, cap. 22)."]}, {"t": "Staphylococcus, Streptococcus, Enterococcus e Neisseria (questão 2)", "sub": ["Morfologia: Staphylococcus em cachos; Streptococcus em cadeias; Enterococcus em pares e cadeias curtas; Neisseria em diplococos (Murray, caps. 18, 19 e 23; A5, p. 31).", "Gram: Staphylococcus, Streptococcus e Enterococcus são Gram-positivos. Neisseria é Gram-negativa (A5, p. 31).", "Bioquímica: catalase positiva no Staphylococcus e negativa no Streptococcus e no Enterococcus (A5, p. 5; Murray, caps. 18 e 19). Coagulase positiva no S. aureus (Murray, caps. 18 e 19). PYR positivo em S. pyogenes e Enterococcus. Optoquina sensível e solubilidade em bile no pneumococo (Murray, caps. 18 e 19). Enterococcus cresce em bile e em altas concentrações de NaCl (Murray, cap. 19). Neisseria é oxidase positiva (A5, p. 31).", "Hemólise: alfa (pneumococo e viridans), beta (S. pyogenes, S. aureus e S. agalactiae) e gama, sem hemólise (A5, p. 6 a 8; Murray, caps. 18 e 19).", "Doenças: S. aureus (pele, toxinas, endocardite); S. pyogenes (faringite, escarlatina, erisipela, febre reumática); S. agalactiae (sepse e meningite neonatais); S. pneumoniae (pneumonia, otite, sinusite, meningite); Enterococcus (ITU, endocardite); Neisseria meningitidis (meningite e meningococcemia) (Murray, caps. 19 e 23; A5, p. 31).", "Neisseria gonorrhoeae: diplococo Gram-negativo que cresce só em meio enriquecido, como ágar chocolate, em atmosfera úmida com CO₂ (Murray, cap. 23). Causa gonorreia, com uretrite purulenta no homem e cervicite na mulher (Murray, cap. 23)."]}, {"t": "Por que o Gram falha: Mycobacterium, Mycoplasma e Treponema (questão 3)", "sub": ["M. tuberculosis: parede rica em ácidos micólicos (Murray, cap. 22). Retém a fucsina após a lavagem com álcool-ácido. Vê-se por Ziehl-Neelsen ou auramina (Murray, cap. 22).", "Mycoplasma pneumoniae: sem parede de peptidoglicano, com membrana rica em esteróis. O Gram de rotina tem pouca utilidade (Murray, cap. 33; A5, p. 46).", "Treponema pallidum: espiroqueta fina, de 0,1 a 0,2 µm. Não cora no Gram nem no Giemsa e não cresce em meio artificial. Detecta-se por imunofluorescência direta ou campo escuro na lesão, e por sorologia (Murray, cap. 32).", "Efeito na identificação: sem parede, o Mycoplasma não tem alvo para β-lactâmicos e o Gram não o mostra (Murray, cap. 33). Sem cultivo, o Treponema depende de métodos diretos e sorológicos (Murray, cap. 32)."]}, {"t": "Cápsula, fímbrias, flagelos e endósporos (questão 4)", "sub": ["Cápsula: camada polissacarídica externa que dificulta a fagocitose e a opsonização. Exemplos: S. pneumoniae (A5, p. 14 a 16); N. meningitidis (A5, p. 34); S. pyogenes, com cápsula de ácido hialurônico (A5, p. 27); S. agalactiae, com ácido siálico (Murray, cap. 19); B. anthracis, com poli-D-glutamato (Murray, caps. 20 e 21); H. influenzae tipo b, com PRP (A5, p. 40).", "Fímbrias e pili: adesão ao epitélio. Exemplos: pili do meningococo, que fixam a bactéria em células não ciliadas (A5, p. 33); pili P da E. coli uropatogênica (Murray, cap. 25, p. 300).", "Flagelos: mobilidade para atravessar o muco. Exemplos: H. pylori (Murray, cap. 28) e Campylobacter (Murray, cap. 28).", "Endósporos: estrutura de resistência que permite sobreviver em condições adversas. Exemplos: B. anthracis e B. cereus (Murray, caps. 20 e 21).", "Vantagens: no ambiente, o endósporo garante sobrevivência; no organismo, a cápsula evita a fagocitose e as fímbrias e flagelos garantem a adesão e a mobilidade."]}]}, {"titulo": "2. Colonização, adesão e estabelecimento da infecção", "pontos": [{"t": "Colonização × contaminação × infecção (questão 5)", "sub": ["Colonização: micro-organismo presente sem manifestações clínicas. A microbiota impede a colonização por patógenos (Murray, cap. 2, p. 21–22). Ex.: E. coli no intestino (Murray, cap. 25).", "Contaminação: a amostra é coletada com outros organismos da pele e das mucosas, o que atrapalha o diagnóstico (Murray, cap. 1, p. 18).", "Infecção: a doença pode resultar de colonização, toxinas ou resposta imune e inflamatória ao micro-organismo (Murray, cap. 1, p. 18).", "Pele: S. epidermidis, Corynebacterium e C. acnes são microbiota. S. aureus pode colonizar parte da população. Um achado pode ser contaminante ou patógeno, conforme a amostra e o quadro (A4, p. 1 e 2).", "E. coli: muitas são da microbiota intestinal. Linhagens com fatores de virulência causam doença intestinal, e a E. coli da microbiota pode chegar ao trato urinário e causar ITU (A4, p. 9).", "Enterococcus faecalis: habita o intestino e pode causar infecção endógena ou por contato no hospital (Murray, cap. 19).", "Sequência resumida: microbiota, depois contaminante potencial, e só então patógeno (A4, p. 2)."]}, {"t": "Como as bactérias superam as barreiras do organismo (questão 6)", "sub": ["Fluxo urinário: a E. coli uropatogênica sobe da uretra para a bexiga e pode chegar aos rins (Murray, cap. 25, p. 300). Os pili P aderem às células da bexiga e do trato urinário superior (p. 300).", "Movimento mucociliar: S. pneumoniae, com pneumolisina, paralisa os cílios (A5, p. 20). B. pertussis adere às células ciliadas e causa lesão tecidual com citotoxina traqueal (Murray, cap. 29). M. pneumoniae causa ciliostase pela adesina P1 (Murray, cap. 33; A5, p. 49).", "Acidez gástrica: H. pylori produz urease, que gera amônia e reduz a acidez ao seu redor. Flagelos polares dão mobilidade (Murray, cap. 28).", "Integridade da pele: S. aureus usa coagulase, proteína A e adesinas que se ligam à fibronectina e ao colágeno (Murray, cap. 18). B. anthracis entra pela pele na forma cutânea (Murray, caps. 20 e 21).", "Mucosas: a IgA secretora é cortada pela IgA1 protease de S. pneumoniae, N. meningitidis e H. influenzae (A5, p. 23, 35 e 42)."]}, {"t": "Cepas comensais × patogênicas: E. coli (questão 7)", "sub": ["A diferença está nos fatores de virulência (fímbrias, toxinas, sistema de secreção), e não só na espécie (Murray, cap. 25).", "Intestinais: ETEC causa diarreia aquosa; EPEC, diarreia infantil; EAEC, diarreia persistente; STEC, colite hemorrágica e síndrome hemolítico-urêmica (Murray, cap. 25).", "Extraintestinais: a UPEC causa cistite e pielonefrite (Murray, cap. 25, p. 300), com adesinas P, AAF/I, AAF/III e Dr (p. 300). A E. coli da própria microbiota pode migrar para o trato urinário (Murray, cap. 25; A4, p. 9).", "Tratamento de Enterobacteriaceae deve seguir o antibiograma (Murray, cap. 25, p. 305). Ceftriaxona e SMX-TMP sensíveis, com ampicilina e ciprofloxacino resistentes, são do caso da aula, não do livro."]}, {"t": "Ambientes: estômago, trato urinário e tecidos com pouco oxigênio (questão 8)", "sub": ["Estômago: H. pylori sobrevive pela urease, que neutraliza a acidez, e pelos flagelos polares (Murray, cap. 28). Na vagina, os lactobacilos mantêm ambiente ácido e limitam outros micro-organismos (A4, p. 13).", "Trato urinário: Proteus mirabilis tem urease e forma cálculos de estruvita. E. coli sobe até a bexiga (Murray, cap. 25).", "Pouco oxigênio: Campylobacter cresce melhor com microaerofilia (Murray, cap. 28). Anaeróbios são abundantes no intestino, como Bacteroides (A4, p. 8).", "Clostridium: bacilos anaeróbios formadores de esporos (Murray, cap. 30). C. tetani é extremamente sensível ao oxigênio, o que dificulta a cultura (Murray, cap. 30).", "Anaeróbios não formadores de esporos, como Bacteroides, colonizam o intestino e causam infecção quando saem do sítio normal, em geral por trauma ou doença (Murray, cap. 31).", "Atenção: os anaeróbios que causam doença costumam tolerar oxigênio, graças à catalase e à superóxido dismutase (Murray, cap. 31). Anaeróbio, portanto, não quer dizer que o agente morre ao contato com o ar."]}]}, {"titulo": "3. Fatores de virulência e evasão imunológica", "pontos": [{"t": "Fator de virulência: definição, categorias e exemplos (questão 9)", "sub": ["Definição: característica do micro-organismo que aumenta sua capacidade de causar doença. Base: Murray. A aula relaciona cápsula, adesinas e toxinas à patogênese (A5, p. 2).", "Estruturas: cápsula (S. pneumoniae, A5, p. 14); pili e adesinas (N. meningitidis, A5, p. 33); proteína M (S. pyogenes, A5, p. 26).", "Enzimas: IgA1 protease (S. pneumoniae, A5, p. 23); coagulase (S. aureus, Murray, cap. 18); urease (H. pylori, Murray, cap. 28); hialuronidase (Treponema, Murray, cap. 32).", "Toxinas: pneumolisina (A5, p. 19 a 21); estreptolisinas (A5, p. 28); toxina diftérica (Murray, caps. 20 e 21); toxina colérica (Murray, cap. 26)."]}, {"t": "Opsonização, fagocitose e estratégias de escape (questão 10)", "sub": ["Opsonização: recobrimento da bactéria por anticorpos e por C3b, para que o fagócito a reconheça (A5, p. 16).", "Fagocitose: engolfamento da bactéria por neutrófilo ou macrófago.", "Cápsula do pneumococo: esconde o C3b e impede a aproximação do fagócito (A5, p. 14 a 16).", "Proteína M de S. pyogenes: bloqueia a deposição de C3b (A5, p. 26). Cápsula de ácido hialurônico: camufla a bactéria (A5, p. 27).", "Proteína A de S. aureus: liga o Fc da IgG e impede a opsonização (Murray, cap. 18).", "Pneumolisina: ativa o complemento de forma descontrolada, longe da bactéria, e atrai neutrófilos em excesso (A5, p. 21)."]}, {"t": "Vida intracelular: Listeria × Mycobacterium tuberculosis (questão 11)", "sub": ["Vantagem: nicho protegido de anticorpos e de muitos antimicrobianos, com disseminação de célula a célula (Murray, caps. 20 e 21).", "Listeria monocytogenes: internalinas favorecem a entrada. Listeriolisina O e fosfolipases rompem o vacúolo. Multiplica-se no citosol. ActA induz actina e forma cauda, que leva a bactéria a outras células (Murray, caps. 20 e 21).", "M. tuberculosis: entra pelo aerossol e fica no macrófago. Interfere na maturação do fagossomo. O fator cordônio (cord factor) impede a fusão do fagossomo com o lisossomo (Murray, cap. 22).", "Diferença-chave: a Listeria escapa do vacúolo para o citosol. O M. tuberculosis permanece no fagossomo e impede sua maturação (Murray, cap. 22; Murray, caps. 20 e 21).", "Defesa do hospedeiro: IFN-γ, de células T auxiliares tipo 1, ativa macrófagos e aumenta a destruição intracelular (Murray, cap. 22)."]}, {"t": "Enzimas bacterianas: função e uso (questão 12)", "sub": ["Catalase: decompõe H₂O₂ em água e oxigênio. Protege contra o peróxido do macrófago e serve para identificação (A5, p. 5).", "Coagulase: converte fibrinogênio em fibrina, formando barreira ao redor do abscesso (S. aureus, Murray, cap. 18).", "Urease: produz amônia e reduz a acidez ao redor. Exemplos: H. pylori (Murray, cap. 28) e Proteus (Murray, cap. 25). Serve ao teste da ureia (Murray, cap. 28).", "Hialuronidase: degrada o ácido hialurônico do tecido e facilita a disseminação (Murray, cap. 32).", "IgA1 protease: corta a IgA humana na mucosa, reduz a defesa local e permite persistência (A5, p. 23, 35 e 42)."]}]}, {"titulo": "4. Toxinas bacterianas e manifestações clínicas", "pontos": [{"t": "Exotoxinas × endotoxinas (questão 13)", "sub": ["Exotoxina: proteína secretada pela bactéria viva, geralmente muito tóxica e específica. Ex.: toxina diftérica, do tipo A-B, em que a porção A inativa o EF-2 (Murray, caps. 20 e 21). Toxina colérica, que aumenta o AMPc e causa diarreia aquosa (Murray, cap. 26). Superantígenos de S. pyogenes (A5, p. 29).", "Endotoxina: componente da membrana externa dos Gram-negativos (LPS ou LOS). É liberada na lise ou na multiplicação e ativa macrófagos. Ex.: LOS do meningococo (A5, p. 36); LPS da E. coli, cujo lipídio A tem atividade endotóxica (Murray, cap. 25).", "Composição: exotoxina é proteína; endotoxina é lipopolissacarídeo (base: Murray).", "Exemplos de produtores: exotoxinas em C. diphtheriae, V. cholerae e S. pyogenes; endotoxinas em N. meningitidis, E. coli e H. influenzae (A5, p. 36 e 42; Murray, caps. 20 e 21; Murray, cap. 26)."]}, {"t": "Mediadores inflamatórios: febre, hipotensão, vasos e coagulação (questão 14)", "sub": ["Componentes bacterianos (LOS, LPS) ativam a imunidade inata e liberam mediadores, como TNF e IL-1. O resultado é febre e hipotensão (A5, p. 36; complemento: Murray).", "LOS do meningococo ativa o endotélio e a coagulação. Nos casos graves, o endotélio lesado leva a CIVD, com microtrombos e consumo de plaquetas (A4, p. 25; A5, p. 36).", "Superantígenos (SPE de S. pyogenes e TSST-1 de S. aureus) causam tempestade de citocinas, com choque tóxico e queda da pressão (A5, p. 29; Murray, caps. 18 e 19).", "Toxina edematosa de B. anthracis: o fator de edema eleva o AMPc e causa edema e disfunção celular (Murray, caps. 20 e 21).", "Em casos graves, a própria resposta inflamatória causa dano, além da toxina (A5, p. 9)."]}, {"t": "Clostridium tetani, C. botulinum e C. perfringens (questão 15)", "sub": ["Base: Murray, cap. 30 (C. tetani, C. botulinum e C. perfringens).", "C. tetani: a tetanospasmina, toxina A-B, bloqueia a liberação de glicina e GABA, neurotransmissores inibitórios da medula. Causa paralisia espástica, com trismo, risus sardonicus e opistótono (Murray, cap. 30). Não causa paralisia flácida. Entra por ferimento contaminado; no tétano neonatal, pelo coto umbilical.", "C. botulinum: a toxina botulínica bloqueia a liberação de acetilcolina nas sinapses colinérgicas periféricas. Causa paralisia flácida descendente, com visão borrada, boca seca e constipação no botulismo alimentar (Murray, cap. 30). Vias: alimento (enlatados caseiros, tipos A e B), mel e solo no botulismo infantil, ferimento e inalação.", "C. perfringens: a alfa-toxina é lecitinase (fosfolipase C); lisa hemácias, plaquetas, leucócitos e endotélio, causando mionecrose com formação de gás (Murray, cap. 30). A beta-toxina causa enterite necrosante. A enterotoxina, sobretudo do tipo A, causa intoxicação alimentar ao agir no íleo (Murray, cap. 30).", "Por que o mesmo gênero dá quadros diferentes: cada espécie produz toxinas diferentes, com mecanismos de ação diferentes."]}, {"t": "Manifestações clínicas e mecanismo de patogenicidade (questão 16)", "sub": ["Formação de abscessos e secreção purulenta: S. aureus. A coagulase forma barreira de fibrina, e a leucocidina PVL lisa leucócitos (Murray, cap. 18).", "Lesão e inflamação da mucosa gástrica: H. pylori. Urease, CagA e VacA alteram a célula e geram inflamação persistente (Murray, cap. 28).", "Petéquias e púrpura: N. meningitidis. O LOS causa lesão endotelial e CIVD, com hemorragia da pele (Murray, cap. 23; A4, p. 25; A5, p. 36). Na forma grave, a síndrome de Waterhouse-Friderichsen une CIVD, choque e destruição bilateral das adrenais (Murray, cap. 23).", "Rigidez e espasmos musculares: C. tetani, pela tetanospasmina, que bloqueia a liberação de glicina e GABA (item 15; Murray, cap. 30).", "Necrose tecidual: S. pyogenes, com fasceíte necrosante (Murray, cap. 19). V. vulnificus, com bolhas hemorrágicas, necrose e sepse (Murray, cap. 26).", "Infecção do sistema nervoso central: S. pneumoniae (A5, p. 13), N. meningitidis (A5, p. 31), L. monocytogenes (Murray, caps. 20 e 21), H. influenzae tipo b (A5, p. 40) e S. agalactiae (Murray, cap. 19)."]}]}, {"titulo": "5. Diagnóstico microbiológico e tratamento", "pontos": [{"t": "Amostra e método por condição clínica (questão 17)", "sub": ["Pneumonia bacteriana: escarro (Gram e cultura). Antígeno urinário para S. pneumoniae e PCR em secreção (Murray, cap. 19).", "Meningite bacteriana: LCR, com aspecto, celularidade, glicose, proteína, Gram, cultura e métodos moleculares quando indicados. Hemocultura também (A4, p. 22). Antígeno urinário e PCR no LCR para o pneumococo (Murray, cap. 19).", "Tuberculose pulmonar: escarro para TRM-TB, que detecta o complexo e a resistência à rifampicina. Baciloscopia e cultura (Murray, cap. 22).", "Infecção urinária: triagem de urina por testes bioquímicos e microscopia (Murray, cap. 16, p. 191). Coleta de jato médio, descartando o primeiro jato, em recipiente estéril (Murray, cap. 16, p. 190). O número de organismos na urina é quantificado e ajuda a avaliar o significado do isolado; poucos organismos com piúria podem ser relevantes (Murray, cap. 16, p. 191).", "Sífilis: na lesão, imunofluorescência direta ou campo escuro. No sangue, sorologia não treponêmica (VDRL ou RPR) e treponêmica (FTA-ABS) (Murray, cap. 32).", "Infecção cutânea com abscesso: pus da base da lesão, com Gram e cultura (Murray, cap. 18).", "Helicobacter pylori: teste respiratório da ureia, antígeno fecal ou biópsia na endoscopia (Murray, cap. 28).", "Ao coletar, lembrar que a microbiota contamina: a amostra deve ser do sítio certo (A4, p. 1)."]}, {"t": "Diagnóstico direto × indireto (questão 18)", "sub": ["Direto: detecta o agente ou seus componentes. Exemplos: cultura, bacterioscopia (Gram), PCR, pesquisa de antígeno e imunofluorescência direta (Murray, cap. 32; Murray, cap. 22; Murray, cap. 19).", "Indireto: detecta a resposta do hospedeiro, como anticorpos. Exemplos: MAT na leptospirose (Murray, cap. 32), VDRL e FTA-ABS na sífilis (Murray, cap. 32), ASLO (A5, p. 11 e 12) e anti-DNase B (Murray, cap. 19).", "Escolha do método: bactérias que não crescem em meio, como Treponema, Chlamydia e Mycoplasma, exigem métodos diretos, moleculares ou sorológicos (Murray, caps. 32, 33 e 35).", "Janela imunológica: a sorologia é pouco sensível na fase aguda; no eritema migrante, IgM aparece 2 a 4 semanas após o início (Murray, cap. 32). Métodos diretos são mais úteis nessa fase (Murray, caps. 32 e 34).", "Gram de sangue ou urina pouco ajuda para espiroquetas e riquétsias, que são finas ou intracelulares (Murray, caps. 32 e 34)."]}, {"t": "β-lactâmicos e resistência: intrínseca × adquirida (questão 19)", "sub": ["Mecanismo: β-lactâmicos se ligam às PBPs e bloqueiam a formação do peptidoglicano da parede (base: Murray; Murray, cap. 18 cita as PBPs como alvo).", "Resistência intrínseca: ausência de alvo. Mycoplasma não tem parede (Murray, cap. 33). Listeria é intrinsecamente resistente a cefalosporinas (Murray, caps. 20 e 21). Enterococcus não responde a cefalosporinas (Murray, cap. 19). Erysipelothrix é resistente à vancomicina (Murray, caps. 20 e 21).", "Resistência adquirida: S. aureus com penicilinase, em mais de 90% dos casos. MRSA pelo gene mecA, que gera PBP2a (Murray, cap. 18). Pneumococo com resistência crescente à penicilina, sem mecanismo detalhado no capítulo (Murray, cap. 19). Enterococcus resistente à vancomicina (VRE) (Murray, cap. 19).", "Por que a estrutura importa: sem parede, o β-lactâmico não tem onde agir. A amoxicilina não atuou no Mycoplasma por isso (Murray, cap. 33).", "Micobactérias: a resistência à rifampicina é pesquisada pelo TRM-TB (Murray, cap. 22)."]}]}, {"titulo": "6. Síndromes clínicas e comparação de agentes", "pontos": [{"t": "Mesma síndrome, agentes diferentes (questão 20)", "sub": ["S. pneumoniae: diplococo Gram-positivo, alfa-hemolítico, catalase negativo e encapsulado. Fatores: cápsula, pneumolisina, adesinas e IgA1 protease. Diagnóstico: escarro, sangue e LCR (Gram e cultura), antígeno urinário e PCR (A5, p. 13 a 23; Murray, cap. 19).", "M. pneumoniae: sem parede, pleomórfico. Fatores: adesina P1 na organela terminal, que causa ciliostase. Diagnóstico: PCR respiratório, crioglutininas (pouco específicas) e cultura lenta, com tempo de geração de 6 horas (Murray, cap. 33; A5, p. 46 a 50).", "H. influenzae: cocobacilo Gram-negativo exigente, que precisa de fatores X e V e cresce em ágar chocolate (Murray, cap. 24). Fatores: cápsula PRP, sobretudo no tipo b; IgA1 protease; LOS; captação de ferro por TbpA e TbpB (A5, p. 39 a 44). Diagnóstico: Gram do LCR, que é sensível (cerca de 10⁷ bactérias/mL no LCR sem tratamento); cultura em ágar chocolate; antígeno específico para o tipo b (Murray, cap. 24).", "M. tuberculosis: bacilo álcool-ácido resistente, com ácidos micólicos. Fatores: fator cordônio e interferência na fusão do fagossomo com o lisossomo (Murray, cap. 22). Diagnóstico: baciloscopia, TRM-TB e cultura (Murray, cap. 22).", "N. meningitidis: diplococo Gram-negativo, oxidase positivo e encapsulado. Fatores: pili, cápsula, LOS (endotoxina, ligada ao dano vascular), IgA1 protease e proteína Opa (Murray, cap. 23; A5, p. 31 a 37). Diagnóstico: Gram do LCR, que mostra o diplococo bem se não houve antibiótico prévio; cultura em meio enriquecido; métodos moleculares (Murray, cap. 23; A4, p. 17 a 25).", "L. monocytogenes: bacilo Gram-positivo pequeno, catalase positivo, sem endósporo, com motilidade e beta-hemólise fraca (Murray, cap. 21). Fatores: internalinas, listeriolisina O e ActA. Diagnóstico: hemocultura, LCR e cultura (Murray, caps. 20 e 21).", "Pistas de síndrome: pneumonia e meningite pneumocócicas (A5, p. 13). Meningite meningocócica com petéquias (A4, p. 20 e 21)."]}]}, {"titulo": "Observações sobre o roteiro e as fontes", "pontos": [{"t": "O que não está coberto pelos arquivos", "sub": ["O cabeçalho do roteiro cita Micologia Médica, mas todas as 20 questões são de bacteriologia. Por isso, as aulas 2 e 3 (fungos) não entram nas respostas.", "Os itens 2, 8, 15, 16 e 20 foram conferidos no livro Murray, 9ª ed., caps. 12, 23, 24, 30 e 31. As demais citações de capítulo (caps. 18 a 22, 25 a 29 e 32 a 35) seguem o cronograma da disciplina e ainda não foram conferidas uma a uma.", "O livro Murray foi enviado e é a base das citações conferidas acima. Antes de usar as demais citações como gabarito, conferir no livro.", "Estas respostas são guia de estudo, não gabarito oficial. Conferir sempre com as aulas e com o livro."]}]}], "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Homem de 68 anos, alcoolista, com febre de 40 °C, escarro ferrugíneo e consolidação lobar à radiografia. O Gram mostra diplococos Gram-positivos lanceolados; a colônia é α-hemolítica e catalase negativa. Qual achado confirma o agente e qual fator explica a resistência à fagocitose?", "alternativas": ["Coagulase positiva e sensibilidade à bacitracina; a cápsula bloqueia a ligação da IgA secretora ao epitélio respiratório alveolar", "Oxidase positiva e fermentação de maltose; a cápsula inibe a apresentação antigênica por células dendríticas no linfonodo regional", "Crescimento em NaCl 6,5% e bile-esculina positiva; a cápsula ativa diretamente o complemento pela via clássica nos alvéolos", "PYR positivo e sensibilidade à novobiocina; a cápsula de ácido hialurônico impede a opsonização pelo C3b no interstício pulmonar", "Solubilidade em bile e sensibilidade à optoquina; a cápsula impede a fagocitose"], "gabarito": "E", "justificativa": "S. pneumoniae é α-hemolítico, catalase negativo, sensível à optoquina e solúvel em bile. A cápsula polissacarídica é o principal fator antifagocitário (resumo: Cocos de importância médica; Mesma síndrome, agentes distintos).", "tecnica": "Pneumococo", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Adolescente de 16 anos com febre, cefaleia intensa, petéquias confluentes no tronco e hipotensão. O líquor mostra diplococos Gram-negativos intracelulares em neutrófilos. Qual é o componente que causa o dano vascular e qual é a conduta empírica inicial?", "alternativas": ["LOS, endotoxina da membrana externa que causa CIVD; ceftriaxona ou cefotaxima, com quimioprofilaxia dos contatos", "Cápsula polissacarídica, que lesa diretamente o endotélio; penicilina G em dose alta, com profilaxia apenas do paciente internado", "Proteína M, que causa mimetismo molecular com o endotélio; vancomicina isolada, com vacinação dos contatos após 72 horas", "IgE contra o endotélio, que degranula mastócitos; metronidazol e isolamento respiratório por 24 horas somente no hospital", "Toxina tetânica, que bloqueia a glicina no endotélio; aciclovir em dose alta e corticoide para reduzir o edema cerebral"], "gabarito": "A", "justificativa": "O LOS (lipooligossacarídeo) da membrana externa de N. meningitidis causa lesão endotelial e CIVD. Empiricamente usa-se ceftriaxona ou cefotaxima, e os contatos recebem quimioprofilaxia (resumo: Neisseria, meningococcemia; Toxinas, da bactéria à sepse).", "tecnica": "Meningococo", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Mulher de 45 anos com dispepsia crônica e úlcera duodenal. O teste da urease é positivo e a biópsia mostra bacilos curvos. Qual combinação de fatores explica a lesão da mucosa e a sobrevivência do agente no estômago?", "alternativas": ["Catalase destrói o ácido clorídrico; a fímbria tipo 1 se liga à mucosa e lesa as células parietais", "Cápsula K1 impede a difusão do ácido; a toxina Shiga destrói o revestimento gástrico por inibição proteica", "Esporo resiste ao ácido gástrico; a toxina tetânica bloqueia a secreção de muco e a renovação do epitélio", "Urease alcaliniza o microambiente; CagA e VacA lesam a célula epitelial e geram inflamação persistente", "Hemolisina lisa as células ácidas; a intimina forma microvilosidades que protegem o agente da secreção gástrica"], "gabarito": "D", "justificativa": "H. pylori produz urease, que gera amônia e alcaliniza o microambiente. CagA e VacA alteram a célula epitelial e geram inflamação crônica, que pode levar a úlcera, adenocarcinoma e linfoma MALT (resumo: Clostridium e manifestações; Mecanismo de patogenicidade).", "tecnica": "H. pylori", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Trabalhador rural com ferimento por espinho há 10 dias. Apresenta trismo, riso sardônico e opistótono, sem febre. Qual é o mecanismo do quadro e a conduta além do antibiótico?", "alternativas": ["Toxina botulínica bloqueia acetilcolina na placa motora; antitoxina trivalente e suporte ventilatório imediato", "Toxina alfa lisa membranas do músculo; desbridamento urgente e oxigenoterapia hiperbárica em todos os casos", "Toxina A de C. difficile atrai neutrófilos ao cólon; vancomicina oral e reposição hidroeletrolítica por via venosa", "Toxina Shiga inibe a síntese proteica; corticoide em dose alta e antibiótico, sem necessidade de soro", "Tetanospasmina bloqueia GABA e glicina nos interneurônios; soro antitetânico, desbridamento e vacinação"], "gabarito": "E", "justificativa": "C. tetani produz tetanospasmina, que bloqueia a liberação de GABA e glicina e causa paralisia espástica. Além do antibiótico, o tratamento inclui soro antitetânico, desbridamento e vacinação (resumo: Clostridium, tétano).", "tecnica": "Tétano", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Uma família apresenta paralisia flácida descendente, midríase e boca seca após consumo de conserva caseira. Qual é a toxina e qual é o tratamento específico?", "alternativas": ["Tetanospasmina bloqueia glicina e GABA; soro antitetânico e desbridamento de ferida", "Toxina alfa, lecitinase que destrói membranas; antibiótico de amplo espectro e drenagem cirúrgica", "Toxina A enterotóxica; vancomicina oral e hidratação venosa com correção de eletrólitos", "Toxina Shiga, que inibe a síntese proteica; corticoide e antibiótico sem soro específico", "Toxina botulínica bloqueia acetilcolina; antitoxina trivalente e suporte ventilatório"], "gabarito": "E", "justificativa": "Paralisia flácida descendente com sinais anticolinérgicos após conserva caseira indica botulismo. A toxina botulínica bloqueia a liberação de acetilcolina, e o tratamento inclui antitoxina trivalente e suporte ventilatório (resumo: Clostridium, botulismo).", "tecnica": "Botulismo", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Agricultor com ferimento profundo e tecido desvitalizado. Há crepitação, bolhas de gás e dor desproporcional. Qual é a toxina responsável pela lise e pela necrose tecidual?", "alternativas": ["Tetanospasmina, uma metaloprotease que bloqueia a liberação de GABA nos interneurônios medulares", "Toxina alfa, uma lecitinase com atividade de fosfolipase C que lisa membranas celulares", "Toxina botulínica, uma protease que cliva SNARE e impede a exocitose de acetilcolina na placa", "Toxina B de C. difficile, que despolimeriza a actina e destrói o citoesqueleto do enterócito", "Toxina Shiga, que inibe a síntese proteica e lesa o endotélio dos pequenos vasos da musculatura"], "gabarito": "B", "justificativa": "A toxina alfa do C. perfringens é uma lecitinase com atividade de fosfolipase C. Degrada fosfolipídeos de membrana e causa mionecrose com gás (gangrena gasosa) (resumo: Clostridium, C. perfringens).", "tecnica": "Gangrena gasosa", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Idoso internado após clindamicina para pneumonia apresenta diarreia profusa, febre e colite com pseudomembranas. Qual é a dupla de toxinas do agente e o tratamento de primeira escolha?", "alternativas": ["Toxina alfa e enterotoxina termolábil; metronidazol intravenoso e drenagem colônica", "Toxina botulínica e tetanospasmina; antitoxina equina e ventilação mecânica prolongada", "Toxina Shiga e toxina LT; ciprofloxacino intravenoso e antitoxina específica para STEC", "Toxina A enterotóxica e toxina B citotóxica; vancomicina oral ou fidaxomicina", "Toxina A de Shigella e toxina B de Salmonella; sulfametoxazol-trimetoprima e hidratação"], "gabarito": "D", "justificativa": "C. difficile produz toxina A (enterotóxica, quimiotática para neutrófilos) e toxina B (citotóxica). Após antibiótico, o tratamento de primeira escolha é vancomicina oral ou fidaxomicina (resumo: Clostridium, C. difficile).", "tecnica": "C. difficile", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Gestante de 30 semanas com febre e mialgia. O líquido amniótico tem odor fétido e o recém-nascido desenvolve sepse e granulomatose infantisséptica. Qual característica explica a infecção fetal e qual antibiótico é indicado?", "alternativas": ["Cresce apenas em anaerobiose e não atravessa a placenta; metronidazol isolado, sem beta-lactâmico", "Forma endósporo que resiste ao útero; vancomicina intravenosa e isolamento do recém-nascido", "Possui cápsula K1 que mimetiza o antígeno fetal; ceftriaxona em dose alta, sem ampicilina", "Cresce a 4 °C e atravessa a placenta; ampicilina, e não cefalosporina, por resistência intrínseca", "Produz toxina tetânica no líquido amniótico; antitoxina equina e soro antitetânico ao recém-nascido"], "gabarito": "D", "justificativa": "Listeria monocytogenes cresce a 4 °C, atravessa a placenta e causa sepse neonatal e granulomatose infantisséptica. A escolha é ampicilina, pois a bactéria é intrinsecamente resistente a cefalosporinas (resumo: Mesma síndrome, agentes distintos; Listeria).", "tecnica": "Listeria", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Jovem com tosse seca prolongada, crioaglutininas positivas e infiltrado intersticial. O Gram do escarro não mostra bactérias e a amoxicilina não tem efeito. Qual é a explicação e o melhor teste diagnóstico?", "alternativas": ["Presença de β-lactamase periplasmática que destrói a amoxicilina; diagnóstico por cultura em ágar sangue", "Ausência de parede, logo sem alvo para β-lactâmicos; diagnóstico por PCR respiratório", "Presença de membrana externa impermeável que impede o fármaco; diagnóstico por hemocultura em 24 horas", "Presença de cápsula que bloqueia o fármaco; diagnóstico por antígeno urinário de pneumococo", "Presença de endósporo resistente à amoxicilina; diagnóstico por bacterioscopia do escarro corado a Gram"], "gabarito": "B", "justificativa": "M. pneumoniae não tem parede celular, portanto não tem alvo para β-lactâmicos. Não cora pelo Gram; o diagnóstico é feito por sorologia ou PCR respiratório, e as crioaglutininas são marcador inespecífico (resumo: Mycoplasma pneumoniae; β-lactâmicos e resistência).", "tecnica": "Mycoplasma", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Homem com úlcera indolor no pênis e linfadenopatia inguinal. O VDRL está positivo com titulação de 1:64 e o FTA-ABS é positivo. Qual é o agente e por que o VDRL é usado no acompanhamento?", "alternativas": ["Haemophilus ducreyi; o VDRL é específico para cancro mole e não varia com o tratamento", "Chlamydia trachomatis; o VDRL detecta antígeno de inclusão e permanece positivo por toda a vida", "Treponema pallidum; o VDRL titula e cai após o tratamento, permitindo seguir a resposta", "Neisseria gonorrhoeae; o VDRL é treponêmico e confirma a infecção com o antígeno de superfície", "Mycoplasma genitalium; o VDRL é não treponêmico e não responde ao tratamento com azitromicina"], "gabarito": "C", "justificativa": "Treponema pallidum causa sífilis. O VDRL é não treponêmico, titula e cai após o tratamento, por isso serve ao acompanhamento. O FTA-ABS é treponêmico e permanece positivo (resumo: Sífilis, diagnóstico microbiológico).", "tecnica": "Sífilis", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Imigrante com escarro BAAR positivo e perda de peso. O teste molecular rápido detecta resistência à rifampicina. Qual é a interpretação e a conduta?", "alternativas": ["Resistência à rifampicina dispensa cultura, porque o teste molecular define o esquema sem outros exames", "Resistência à rifampicina indica infecção latente, e o paciente deve receber apenas isoniazida por seis meses", "Resistência à rifampicina exige esquema com outros fármacos, cultura e antibiograma completo", "Resistência à rifampicina indica infecção por Nocardia, e o tratamento é sulfametoxazol-trimetoprima", "Resistência à rifampicina indica infecção por micobactéria não tuberculosa, sem necessidade de tratamento"], "gabarito": "C", "justificativa": "Resistência à rifampicina (detectada pelo teste molecular) exige esquema com outros fármacos. Cultura e antibiograma completo são necessários para ajustar o tratamento (resumo: Diagnóstico microbiológico; Mycobacterium tuberculosis).", "tecnica": "Tuberculose resistente", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Criança de 4 anos, não vacinada, com febre alta, estridor, sialorreia e posição de tripé. Qual é a conduta inicial correta?", "alternativas": ["Examinar a orofaringe com abaixador para confirmar a infecção; swab de garganta e alta com antibiótico oral", "Colher swab da orofaringe posterior e tratar com antitussígeno; repouso domiciliar por 48 horas", "Garantir via aérea sem examinar a orofaringe com abaixador; hemocultura e antibiótico parenteral", "Administrar corticoide inalatório e observar em casa; cultura de escarro após 72 horas", "Realizar punção lombar imediata antes de qualquer conduta na via aérea; antibiótico após o resultado"], "gabarito": "C", "justificativa": "Epiglotite por H. influenzae tipo b é emergência: deve-se garantir a via aérea e não examinar a orofaringe com abaixador, pelo risco de obstrução. Hemocultura e antibiótico parenteral fazem parte da conduta (resumo: Haemophilus influenzae; Mesma síndrome).", "tecnica": "Epiglotite", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Homem com uretrite purulenta. O Gram mostra diplococos Gram-negativos intracelulares em neutrófilos. Qual é o tratamento atual recomendado e por que a penicilina foi abandonada?", "alternativas": ["Ceftriaxona com azitromicina; a penicilina perdeu eficácia por resistência crescente", "Penicilina G benzatina em dose única; a resistência é rara e não se espalha entre as cepas", "Tetraciclina por sete dias; a penicilina foi abandonada por causar hepatite tóxica em adultos", "Sulfametoxazol-trimetoprima; a penicilina foi abandonada por ser inativa contra cocos Gram-negativos", "Metronidazol isolado; a penicilina foi abandonada porque não atinge o interior dos neutrófilos"], "gabarito": "A", "justificativa": "Gonorreia é tratada com ceftriaxona associada à azitromicina, por dupla terapia. A penicilina foi abandonada porque a concentração necessária para matar cepas sensíveis aumentou e a resistência tornou-se comum (resumo: Neisseria gonorrhoeae).", "tecnica": "Gonorreia", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Idoso com endocardite por Enterococcus faecalis, com cultura resistente a cefalosporinas. Qual é a explicação e a combinação de tratamento mais coerente?", "alternativas": ["Resistência adquirida por mutação em PBP2a; vancomicina isolada por quatro semanas", "Resistência intrínseca a cefalosporinas; ampicilina com aminoglicosídeo", "Resistência por bomba de efluxo em Gram-positivo; daptomicina e cefepima em altas doses", "Resistência por β-lactamase periplasmática; amoxicilina com clavulanato e rifampicina", "Resistência pela membrana externa impermeável; ciprofloxacino com metronidazol por seis semanas"], "gabarito": "B", "justificativa": "Enterococcus é intrinsecamente resistente a cefalosporinas. A combinação clássica para endocardite é ampicilina com aminoglicosídeo, que tem efeito sinérgico (resumo: Enterococcus; β-lactâmicos e resistência).", "tecnica": "Enterococcus", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Mulher com cálculo coraliforme, urina alcalina e urocultura com Proteus. Qual é o mecanismo do cálculo e o que o explica?", "alternativas": ["Urease converte ureia em amônia, alcaliniza a urina e precipita estruvita e apatita", "Catalase converte peróxido em oxigênio, o que oxida o ácido úrico e precipita cistina", "Coagulase converte fibrinogênio em fibrina, que se deposita no túbulo e forma o cálculo", "Hialuronidase degrada o ácido hialurônico do rim, liberando cálcio que se cristaliza no ureter", "Hemolisina lisa hemácias e libera ferro, que precipita como hematita no sistema coletor renal"], "gabarito": "A", "justificativa": "A urease do Proteus converte ureia em amônia e CO₂, alcalinizando a urina. Nesse meio, magnésio e cálcio precipitam como estruvita e apatita, formando cálculos (resumo: Microbiota, nichos ambientais; Enterobacteriaceae).", "tecnica": "Proteus e cálculo", "slide": null}, {"id": 16, "nivel": "muito_dificil", "enunciado": "Abscesso intra-abdominal após perfuração de cólon. Há bacilos Gram-negativos anaeróbios e pouco corados. Qual é o fator de virulência principal desse agente e por que o Gram é pouco útil?", "alternativas": ["Endósporo resistente à fagocitose; os bacilos são fortemente corados ao Gram, o que facilita o diagnóstico", "Proteína M antifagocitária; os bacilos são Gram-positivos e formam cadeias típicas no exsudato", "Coagulase que forma fibrina; os bacilos perdem a cor ao Gram por ação da catalase do exsudato", "Pili que aderem ao epitélio; os bacilos têm parede de ácido micólico que impede a coloração de Gram", "Cápsula polissacarídica antifagocitária; os bacilos são fracamente corados ao Gram"], "gabarito": "E", "justificativa": "Bacteroides fragilis tem cápsula polissacarídica, que é seu principal fator de virulência e é antifagocitária. Os bacilos aparecem fracamente corados ao Gram (resumo: Microbiota, anaeróbios; Mesma síndrome).", "tecnica": "Bacteroides fragilis", "slide": null}, {"id": 17, "nivel": "muito_dificil", "enunciado": "Trabalhador de curtume com lesão cutânea indolor, com escara negra central e edema. Qual toxina causa o edema e por qual mecanismo?", "alternativas": ["Toxina letal, uma metaloprotease que cliva a MAP-quinase e causa morte celular por apoptose", "Toxina diftérica, que inativa o EF-2 e interrompe a síntese proteica na célula do tecido", "Toxina colérica, que aumenta o cAMP por ação em Gs e causa secreção intensa de íons", "Toxina tetânica, que bloqueia a liberação de glicina e causa espasmo muscular local", "Fator de edema, uma adenilato ciclase calmodulina-dependente que eleva o cAMP intracelular"], "gabarito": "E", "justificativa": "B. anthracis produz fator de edema, uma adenilato ciclase calmodulina-dependente que eleva o cAMP e causa edema. A toxina letal é o outro componente. A forma cutânea é a mais comum (resumo: Bacillus anthracis; Toxinas, mediadores).", "tecnica": "Antraz cutâneo", "slide": null}, {"id": 18, "nivel": "muito_dificil", "enunciado": "Mulher jovem com tampão vaginal, febre, rash difuso em eritrodermia e hipotensão. Qual é a toxina responsável e qual é o mecanismo?", "alternativas": ["Toxina alfa, lecitinase que lisa leucócitos e causa necrose tecidual no sítio do tampão", "TSST-1, superantígeno que ativa linfócitos T e libera citocinas em excesso", "Toxina botulínica, que bloqueia a acetilcolina e causa paralisia flácida com hipotensão", "Toxina diftérica, que inativa o EF-2 e causa necrose das células endoteliais do sistema", "Toxina colérica, que aumenta o cAMP e causa diarreia aquosa com perda de volume plasmático"], "gabarito": "B", "justificativa": "A síndrome do choque tóxico é causada por TSST-1 de S. aureus, um superantígeno que ativa linfócitos T e libera citocinas em excesso, com rash, hipotensão e falência de múltiplos órgãos (resumo: Toxinas, S. aureus; Staphylococcus).", "tecnica": "Choque tóxico", "slide": null}, {"id": 19, "nivel": "muito_dificil", "enunciado": "Criança de 9 anos com faringite há três semanas, artrite migratória e nova cardite. Qual é o mecanismo central dessa complicação?", "alternativas": ["Imunodeficiência secundária: queda de linfócitos T CD4 que permite a persistência do estreptococo", "Doença do soro: complexos de penicilina e albumina depositados nas válvulas cardíacas", "Tolerância periférica quebrada: linfócitos T autorreativos sem qualquer relação com a infecção", "Hipersensibilidade tipo I: IgE contra a estreptolisina que degranula mastócitos no miocárdio", "Mimetismo molecular: anticorpo anti-proteína M reage com a miosina cardíaca"], "gabarito": "E", "justificativa": "Na febre reumática, anticorpos contra a proteína M do S. pyogenes reagem com a miosina cardíaca por mimetismo molecular. Surgem miocardite e artrite após faringite mal tratada (resumo: Tolerância e autoimunidade; Hipersensibilidade II, febre reumática).", "tecnica": "Febre reumática", "slide": null}, {"id": 20, "nivel": "muito_dificil", "enunciado": "Mulher jovem com disúria, piúria e urocultura com mais de 10⁵ UFC/mL de E. coli. Qual combinação explica a adesão ao urotélio e a ascensão ao rim?", "alternativas": ["Cápsula K1 impede a fagocitose na bexiga; toxina LT leva a bactéria ao rim pela corrente sanguínea", "Endósporo resiste à lavagem urinária; hemolisina lisa o epitélio e permite a entrada no rim", "Intimina destrói as microvilosidades da bexiga; toxina Shiga leva a bactéria ao glomérulo renal", "Coagulase forma abscesso na bexiga; proteína M impede a ação dos anticorpos urinários locais", "Fímbria P e adesinas ancoram no urotélio; flagelo permite a ascensão contra o fluxo urinário"], "gabarito": "E", "justificativa": "UPEC usa fímbria P e adesinas para aderir ao urotélio, e o flagelo permite a ascensão contra o fluxo urinário. A urocultura quantitativa com mais de 10⁵ UFC/mL indica infecção (resumo: Enterobacteriaceae, UPEC; Microbiota, barreiras e nichos).", "tecnica": "UPEC", "slide": null}], "fontes": ["Roteiro: estudo dirigido Prova 02, Microbiologia (Profª Natália Cavichioli)", "A4 = Aula 4 (pdf/natalia/aulas/aula-04.pdf)", "A5 = Aula 5 (pdf/natalia/aulas/aula-05.pdf)", "Murray, Rosenthal e Pfaller, Medical Microbiology, 9ª ed.: caps. 12, 23, 24, 30 e 31 conferidos no livro"], "id": "natalia-roteiro", "voltar": {"href": "#/agressao/natalia", "texto": "Professora Natália"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["natalia-aula-01"] = {"titulo": "Aula 1", "subtitulo": "Fungos: morfologia, reprodução e como a micose é adquirida (anotações do quadro)", "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg", "abas": ["resumo", "glossario", "quiz"], "resumo": [{"titulo": "1. O que é um fungo", "pontos": [{"t": "Organismo eucarionte, heterotrófico", "sub": ["Fungos são eucariontes e heterotróficos: dependem de matéria orgânica pronta para obter energia (quadro, Aula 1).", "Podem ser unicelulares (leveduras) ou pluricelulares (filamentosos, ou bolores). Essa divisão é a primeira que o quadro faz.", "Base: Murray, Medical Microbiology, capítulos de micologia médica."]}, {"t": "Parede e membrana", "sub": ["Parede celular: formada por β-glucanas, manoproteínas e quitina. A quitina é o principal componente estrutural (quadro).", "Membrana: contém ergosterol, e não colesterol como a membrana animal. Essa diferença torna o ergosterol um alvo seletivo de antifúngicos, como os azóis e as equinocandinas (quadro; base: Goodman & Gilman, cap. de antifúngicos)."]}]}, {"titulo": "2. Leveduras e bolores", "pontos": [{"t": "Leveduras", "sub": ["Unicelulares, de forma arredondada ou oval. Exemplos anotados: Candida spp. e Cryptococcus spp. (quadro).", "Dimorfismo térmico: algumas leveduras mudam de forma conforme a temperatura. Vale para Histoplasma e Paracoccidioides (quadro)."]}, {"t": "Filamentosos (bolores)", "sub": ["Formam hifas, e o conjunto de hifas forma o micélio (quadro).", "Hifas podem ser hialinas ou demáceas (pigmentadas). Podem ser vegetativas (absorvem nutrientes) ou aéreas/reprodutivas (produzem esporos) (quadro).", "Hifas cenocíticas, ou pauciseptadas: quase sem septos, com citoplasma contínuo e muitos núcleos. Exemplos: Rhizopus e Mucor (quadro).", "Hifas septadas: septos transversais dividem o filamento em compartimentos. Exemplo: Aspergillus (quadro)."]}, {"t": "Hifas e pseudo-hifas", "sub": ["Hifa verdadeira: crescimento tubular, com paredes paralelas e septos; não há constrições marcantes entre as células (quadro).", "Pseudo-hifa: formada por leveduras alongadas que brotam e permanecem unidas. Por isso aparecem constrições nas junções entre as células. Exemplo: Candida (quadro)."]}, {"t": "Dimorfismo térmico", "sub": ["A forma muda com a temperatura: a 25 °C a forma é de mofo (filamentosa); a 37 °C, de levedura (quadro).", "Exemplos: Histoplasma e Paracoccidioides."]}]}, {"titulo": "3. Reprodução", "pontos": [{"t": "Assexuada", "sub": ["Brotamento (levedura): a célula-mãe forma um broto, a célula-filha. Os brotos são chamados de blastoconídios (quadro).", "Fragmentação da hifa: fragmentos da hifa funcionam como unidades de propagação, os artroconídios (quadro).", "Formação de conídios: o micélio produz estruturas especializadas que originam os conídios. Os esporangiósporos são formados dentro de uma estrutura chamada esporângio (quadro)."]}, {"t": "Dispersão e germinação", "sub": ["Conídios se desprendem, se dispersam pelo ambiente e, em condições adequadas, germinam e formam novas hifas (quadro)."]}]}, {"titulo": "4. Como se adquire a micose", "pontos": [{"t": "Quatro portas de entrada", "sub": ["Inoculação traumática: o fungo do solo, de plantas ou de madeira entra pela pele após um trauma. Exemplo: Sporothrix spp., a doença do jardineiro (quadro).", "Contato direto ou contaminação superficial: dermatófitos passam de pessoa para pessoa, de animal, do ambiente ou de fômites (quadro).", "Endógena: o fungo já faz parte da microbiota e causa doença quando o equilíbrio se rompe. Exemplo: Candida (quadro).", "Inalação: o fungo ambiental produz conídios e esporos, que se dispersam no ar e são inalados até as vias respiratórias (quadro).", "Zoonótica: transmissão entre animal e ser humano. Exemplo: Sporothrix brasiliensis (quadro)."]}]}], "glossario": [{"termo": "Eucarionte", "tecnica": "Morfologia", "definicao": "Célula com núcleo delimitado por membrana. Os fungos são eucariontes, e por isso dividem características com as células animais.", "slide": 1}, {"termo": "Levedura", "tecnica": "Morfologia", "definicao": "Fungo unicelular, de forma arredondada ou oval, que se reproduz por brotamento. Exemplos: Candida e Cryptococcus.", "slide": 1}, {"termo": "Bolor (filamentoso)", "tecnica": "Morfologia", "definicao": "Fungo pluricelular formado por hifas e micélio. Exemplos: Aspergillus, Rhizopus e Mucor.", "slide": 1}, {"termo": "Hifa", "tecnica": "Morfologia", "definicao": "Filamento tubular que compõe o fungo filamentoso. Pode ser vegetativa (absorção) ou reprodutiva (esporos).", "slide": 1}, {"termo": "Micélio", "tecnica": "Morfologia", "definicao": "Conjunto de hifas que forma o corpo do bolor.", "slide": 1}, {"termo": "Hifa cenocítica (pauciseptada)", "tecnica": "Morfologia", "definicao": "Hifa com poucos ou nenhum septo e citoplasma contínuo com vários núcleos. Típica de Rhizopus e Mucor.", "slide": 1}, {"termo": "Hifa septada", "tecnica": "Morfologia", "definicao": "Hifa dividida por septos transversais em compartimentos. Típica de Aspergillus.", "slide": 1}, {"termo": "Pseudo-hifa", "tecnica": "Morfologia", "definicao": "Cadeia de leveduras alongadas que permanecem unidas, com constrições nas junções. Típica de Candida.", "slide": 1}, {"termo": "Dimorfismo térmico", "tecnica": "Morfologia", "definicao": "Mudança de forma com a temperatura: 25 °C filamentoso (mofo), 37 °C levedura. Vale para Histoplasma e Paracoccidioides.", "slide": 1}, {"termo": "Quitina", "tecnica": "Parede celular", "definicao": "Polímero de N-acetilglicosamina que forma o principal componente estrutural da parede fúngica.", "slide": 1}, {"termo": "Ergosterol", "tecnica": "Membrana", "definicao": "Esterol da membrana fúngica (no lugar do colesterol). Alvo de azóis e de equinocandinas, por isso a toxicidade seletiva.", "slide": 1}, {"termo": "Blastoconídio (brotamento)", "tecnica": "Reprodução assexuada", "definicao": "Broto formado pela célula-mãe de uma levedura, que se separa como célula-filha.", "slide": 1}, {"termo": "Artroconídio (fragmentação)", "tecnica": "Reprodução assexuada", "definicao": "Fragmento de hifa que funciona como unidade de propagação.", "slide": 1}, {"termo": "Conídio", "tecnica": "Reprodução assexuada", "definicao": "Esporo produzido por estruturas especializadas do micélio. Desprende-se e se dispersa pelo ar ou pelo solo.", "slide": 1}, {"termo": "Esporângio e esporangiósporos", "tecnica": "Reprodução assexuada", "definicao": "O esporângio é a estrutura que contém os esporangiósporos. Característico dos Mucorales.", "slide": 1}, {"termo": "Inoculação traumática", "tecnica": "Porta de entrada", "definicao": "Entrada do fungo na pele por trauma, com espinho, madeira ou arranhadura. Base das micoses de implantação.", "slide": 1}, {"termo": "Sporothrix spp. (doença do jardineiro)", "tecnica": "Agente", "definicao": "Fungo dimórfico que causa esporotricose por inoculação traumática. Destaque para S. brasiliensis, zoonótica.", "slide": 1}, {"termo": "Sporothrix brasiliensis", "tecnica": "Agente zoonótico", "definicao": "Espécie de Sporothrix associada a gatos no Brasil, transmitida por arranhadura.", "slide": 1}, {"termo": "Dermatófitos", "tecnica": "Transmissão", "definicao": "Fungos queratinofílicos que causam dermatofitoses por contato com pessoas, animais, solo ou fômites.", "slide": 1}, {"termo": "Candida spp. (microbiota endógena)", "tecnica": "Porta de entrada", "definicao": "Levedura da microbiota humana. Causa doença quando o equilíbrio é rompido, como em candidíase.", "slide": 1}, {"termo": "Cryptococcus spp.", "tecnica": "Agente", "definicao": "Levedura encapsulada que entra pela inalação e pode chegar ao sistema nervoso central.", "slide": 1}, {"termo": "Rhizopus e Mucor", "tecnica": "Agente", "definicao": "Bolores cenocíticos (pauciseptados) do grupo Mucorales.", "slide": 1}, {"termo": "Aspergillus", "tecnica": "Agente", "definicao": "Bolor de hifa septada, inalado do ambiente. Pode causar alergia, aspergiloma ou doença invasiva.", "slide": 1}], "fontes": ["Quadro da aula (foto de anotações da Aula 1, pdf/natalia/aulas/aula-01-quadro.jpg)", "Base complementar: Murray, Medical Microbiology (micologia médica); Goodman & Gilman (antifúngicos)"], "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Uma micose é tratada com um antifúngico que inibe a síntese de esterol da membrana. Pelo quadro da aula, qual esterol é o alvo e por que o fármaco não age na célula humana?", "alternativas": ["Colesterol, porque a membrana fúngica contém ergosterol, e não colesterol", "Ergosterol, porque a célula humana não possui membrana plasmática com esteróis", "Quitina, porque a célula humana não produz parede celular de polímero", "Glucana, porque a célula humana não contém polissacarídeos de parede", "Ergosterol, porque a membrana humana contém colesterol, e não ergosterol"], "gabarito": "E", "justificativa": "A membrana fúngica contém ergosterol, e a membrana animal contém colesterol. Essa diferença torna o ergosterol um alvo seletivo (Aula 1, quadro: membrana).", "tecnica": "Membrana e parede", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um laboratório recebe uma amostra de fungo com hifas sem septos e núcleos espalhados num citoplasma contínuo. Pelo quadro, qual gênero e qual categoria de hifa são compatíveis?", "alternativas": ["Rhizopus, hifa cenocítica (pauciseptada)", "Aspergillus, hifa septada", "Candida, pseudo-hifa", "Histoplasma, hifa vegetativa dimórfica", "Sporothrix, hifa aérea com conídios em roseta"], "gabarito": "A", "justificativa": "Hifas cenocíticas, ou pauciseptadas, têm poucos ou nenhum septo e citoplasma contínuo com muitos núcleos. Exemplos do quadro: Rhizopus e Mucor. Aspergillus tem hifas septadas.", "tecnica": "Morfologia de hifas", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Em cultura de Candida, observa-se uma cadeia de leveduras alongadas unidas por constrições. Pelo quadro, como essa estrutura se diferencia de uma hifa verdadeira?", "alternativas": ["Hifa verdadeira: leveduras alongadas que brotam, com constrições nas junções; a pseudo-hifa tem paredes paralelas", "Pseudo-hifa: leveduras alongadas unidas por constrições; hifa verdadeira tem paredes paralelas", "Pseudo-hifa: hifa cenocítica sem septos; a hifa verdadeira tem septos transversais", "Hifa verdadeira: formada por conídios em roseta; a pseudo-hifa forma artroconídios", "Pseudo-hifa: estrutura de reserva com glicogênio; a hifa verdadeira tem vacúolo digestivo"], "gabarito": "B", "justificativa": "Pseudo-hifa é formada por leveduras alongadas que brotam e permanecem unidas. Hifa verdadeira tem crescimento tubular, paredes paralelas e septos, sem constrições marcantes (Aula 1, quadro: hifas e pseudo-hifas).", "tecnica": "Hifas e pseudo-hifas", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um fungo cresce como bolor a 25 °C e como levedura a 37 °C. Pelo quadro, qual é o nome desse fenômeno, e quais exemplos a aula associa a ele?", "alternativas": ["Pleomorfismo; Aspergillus e Mucor", "Dimorfismo hídrico; Candida e Cryptococcus, que mudam de forma com a umidade do solo", "Heterotrofia; Rhizopus e Sporothrix", "Dimorfismo térmico; Histoplasma e Paracoccidioides", "Plasmogamia; Saccharomyces e Trichophyton"], "gabarito": "D", "justificativa": "O dimorfismo térmico muda a forma com a temperatura: 25 °C mofo, 37 °C levedura. O quadro cita Histoplasma e Paracoccidioides (Aula 1, quadro: dimorfismo).", "tecnica": "Dimorfismo", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Uma levedura se divide formando um broto que, depois de crescer, se separa da célula-mãe. Pelo quadro, qual é o nome desse modo de reprodução e a estrutura produzida?", "alternativas": ["Fragmentação, com artroconídios", "Formação de conídios, em esporângio", "Cissiparidade, com esporangiósporos", "Brotamento, com blastoconídios", "Plasmogamia, com ascósporos"], "gabarito": "D", "justificativa": "No brotamento, a célula-mãe forma um broto que vira célula-filha. Os brotos são os blastoconídios (Aula 1, quadro: reprodução assexuada).", "tecnica": "Reprodução assexuada", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um bolor libera esporos que se espalham pelo ar e germinam novas hifas em condições adequadas. Pelo quadro, que estrutura se desprende e onde os esporangiósporos são formados?", "alternativas": ["Blastoconídios se desprendem; esporangiósporos são formados na célula-mãe", "Artroconídios se desprendem; esporangiósporos são formados em pseudo-hifa", "Conídios se desprendem; esporangiósporos ficam dentro do esporângio", "Pseudo-hifas se desprendem; esporangiósporos são formados no citoplasma", "Hifas se desprendem; esporangiósporos são formados no núcleo"], "gabarito": "C", "justificativa": "O micélio produz conídios, que se desprendem e se dispersam. Os esporangiósporos são formados dentro de estrutura chamada esporângio (Aula 1, quadro: conídios e esporângio).", "tecnica": "Conídios e esporângio", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um trabalhador de jardinagem se espeta com espinho e, semanas depois, surge nódulos ascendentes no braço. Pelo quadro, qual porta de entrada e qual agente são compatíveis?", "alternativas": ["Inalação, com Aspergillus", "Endógena, com Candida", "Contato direto, com Microsporum", "Zoonótica pela ingestão de água contaminada, com Cryptococcus spp.", "Inoculação traumática, com Sporothrix spp."], "gabarito": "E", "justificativa": "A inoculação traumática introduz o fungo abaixo da pele após trauma. Sporothrix spp., a doença do jardineiro, é o exemplo do quadro (Aula 1, quadro: como se pega micose).", "tecnica": "Porta de entrada", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Uma dermatofitose passa de um animal de estimação para uma criança. Pelo quadro, em qual categoria de transmissão ela se encaixa e qual grupo de fungos está envolvido?", "alternativas": ["Inalação, com leveduras", "Endógena, com Candida", "Inoculação traumática, com Sporothrix", "Quebra de barreira, com Mucorales", "Contato direto, com dermatófitos"], "gabarito": "E", "justificativa": "O contato direto ou contaminação superficial envolve dermatófitos, transmitidos de pessoa a pessoa, de animais, do ambiente ou por fômites (Aula 1, quadro: como se pega micose).", "tecnica": "Transmissão por contato", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um fungo do ambiente produz conídios que se dispersam no ar, e a pessoa os inala. Pelo quadro, qual é a via de aquisição e qual é a categoria clínica mais provável?", "alternativas": ["Inoculação traumática, com micose de implantação", "Contato direto, com dermatofitose", "Endógena, com candidíase oral", "Inalação, com micose sistêmica pulmonar", "Zoonótica pela mordedura, com esporotricose linfática"], "gabarito": "D", "justificativa": "Na inalação, o fungo ambiental produz conídios e esporos que se dispersam no ar e atingem as vias respiratórias (Aula 1, quadro: como se pega micose).", "tecnica": "Inalação", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um paciente com candidíase tem Candida presente na própria microbiota. Pelo quadro, o que explica a doença nesse caso?", "alternativas": ["Inoculação de Candida por espinho ou madeira", "Inalação de conídios dispersos no ar", "Rompimento do equilíbrio da microbiota", "Contato direto com outro paciente", "Transmissão de animal de estimação"], "gabarito": "C", "justificativa": "Candida faz parte da microbiota e causa doença por via endógena quando o equilíbrio é rompido (Aula 1, quadro: endógena).", "tecnica": "Via endógena", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um laboratório identifica uma levedura unicelular com cápsula que pode chegar ao sistema nervoso central. Pelo quadro, qual gênero é o mais compatível e qual é a porta de entrada típica?", "alternativas": ["Candida spp., pela inoculação traumática", "Aspergillus spp., pela endógena", "Cryptococcus spp., pela inalação", "Rhizopus spp., pelo contato direto", "Sporothrix spp., pela zoonose"], "gabarito": "C", "justificativa": "Cryptococcus spp. é uma levedura citada no quadro. Chega ao sistema nervoso central após inalação (Aula 1, quadro, e Aula 3 para detalhes).", "tecnica": "Leveduras", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Uma amostra de bolor mostra hifas septadas, com compartimentos separados. Pelo quadro, qual gênero é o exemplo e qual tipo de crescimento ele apresenta?", "alternativas": ["Aspergillus, hifas septadas", "Mucor, hifas cenocíticas", "Rhizopus, hifas cenocíticas", "Candida, pseudo-hifas", "Cryptococcus, levedura encapsulada"], "gabarito": "A", "justificativa": "Hifas septadas têm septos transversais que dividem o filamento em compartimentos. O quadro cita Aspergillus como exemplo.", "tecnica": "Hifas septadas", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Uma hifa de fungo filamentoso tem função reprodutiva e produz esporos. Pelo quadro, qual é a classificação funcional da hifa e como ela pode ser pigmentada?", "alternativas": ["Aérea ou reprodutiva; hialina ou demácea", "Vegetativa; hialina apenas", "Aérea; cenocítica sem pigmento", "Vegetativa; demácea apenas", "Reprodutiva; pseudo-hifa sem pigmento, típica de leveduras"], "gabarito": "A", "justificativa": "Hifas podem ser vegetativas (absorção) ou aéreas/reprodutivas (produção de esporos). Quanto à pigmentação, podem ser hialinas ou demáceas (Aula 1, quadro: hifas).", "tecnica": "Hifas: função e pigmento", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Um estudante afirma que todos os fungos são leveduras. Pelo quadro, o que está errado nessa afirmação?", "alternativas": ["Todos os fungos são pluricelulares, e leveduras não são fungos", "Fungos são unicelulares (leveduras) ou pluricelulares (bolores); leveduras são só parte do grupo", "Todos os fungos são autotróficos, não precisam de matéria orgânica e não formam hifas nem leveduras", "Fungos são procariontes, e as leveduras são as únicas eucarióticas", "Fungos não formam hifas, e as leveduras formam micélio"], "gabarito": "B", "justificativa": "Fungos são eucariontes heterotróficos, unicelulares (leveduras) ou pluricelulares (bolores). Leveduras são um dos grupos, não todo o reino (Aula 1, quadro).", "tecnica": "Visão geral", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um bolor forma estruturas especializadas no micélio, que se desprendem e se dispersam pelo ar. Pelo quadro, como se chama esse esporo e de qual estrutura do micélio ele surge?", "alternativas": ["Blastoconídio, formado por brotamento de hifa septada, no ambiente úmido", "Conídio, formado pelas estruturas especializadas do micélio", "Artroconídio, formado por fragmentação de levedura", "Esporangiósporo, formado por pseudo-hifa", "Ascósporo, formado por plasmogamia de hifas cenocíticas"], "gabarito": "B", "justificativa": "O micélio produz estruturas especializadas que originam os conídios. Eles se desprendem e se dispersam pelo ambiente (Aula 1, quadro: reprodução).", "tecnica": "Conídios", "slide": 1, "pdf": "pdf/natalia/aulas/aula-01-quadro.jpg"}], "id": "natalia-aula-01", "voltar": {"href": "#/agressao/natalia", "texto": "Professora Natália"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["natalia-aula-02"] = {"titulo": "Aula 2", "subtitulo": "Fungos de interesse clínico: estrutura, micoses oportunistas, imunidade antifúngica e dermatofitoses", "pdf": "pdf/natalia/aulas/aula-02.pdf", "abas": ["resumo", "glossario", "quiz", "pdf"], "resumo": [{"titulo": "1. Estrutura da célula fúngica", "pontos": [{"t": "Características gerais", "sub": ["Heterotróficos e eucarióticos. Podem ser uni ou pluricelulares. A célula fúngica tem os componentes eucarióticos típicos (slide 2).", "Base: Murray, Medical Microbiology, capítulos de micologia médica."]}, {"t": "Parede celular", "sub": ["Dá rigidez. Composta por glucanas, mananas, quitina, proteínas e lipídios. Glucanas e mananas se combinam com proteínas, formando glicoproteínas e manoproteínas (slide 3).", "Quitina é o principal componente estrutural da parede (slide 3).", "Fungos termodimórficos: a fase M (mofo, 25 °C) tem mais α-glucana. A fase Y (levedura, 37 °C) tem mais β-glucana. Essa diferença parece ligada à patogenicidade (slide 3)."]}, {"t": "Membrana plasmática e ergosterol", "sub": ["Tem as funções da membrana das outras células. É formada por duas camadas de fosfolipídios com proteínas (slide 4).", "Contém ergosterol, e não colesterol. É o principal sítio de ação dos antifúngicos que inibem a síntese de ergosterol, por isso têm toxicidade seletiva (slide 4)."]}, {"t": "Citoplasma e núcleo", "sub": ["Glicogênio é a principal reserva de energia. Mitocôndrias geram energia. Retículo e ribossomos sintetizam proteínas. Golgi está ligado ao metabolismo de carboidratos (slide 5).", "Núcleo com carioteca lipídica e nucléolo, local de produção do RNA ribossomal (slide 6).", "Cápsula: Cryptococcus neoformans tem cápsula mucopolissacarídica fibrilar. Ela dificulta a fagocitose e é importante na patogênese (slide 6)."]}]}, {"titulo": "2. Leveduras, bolores e reprodução", "pontos": [{"t": "Leveduras", "sub": ["Unicelulares, esferoidais ou ovais. Reprodução assexuada por cissiparidade (divisão direta) ou brotamento (gêmula). Reprodução sexuada por plasmogamia, cariogamia e meiose, como em Saccharomyces cerevisiae (slide 7)."]}, {"t": "Bolores", "sub": ["Filamentosos e multicelulares. Hifas formam o micélio. Em cultura, colônias algodonosas, aveludadas ou pulverulentas, com pigmentações variadas. Essas características ajudam na identificação presuntiva (slides 8 e 9)."]}, {"t": "Dispersão e microbiota fúngica", "sub": ["Quando encontram substrato e condições favoráveis, germinam, multiplicam-se e colonizam (slide 10).", "Homem e animais têm microbiota fúngica endógena e são vias de dispersão. Pele, pelos, unhas, mucosa bucal e nasal têm fungos em dispersão, em microbiota transitória (slide 10)."]}]}, {"titulo": "3. Fungos contaminantes e saúde do ambiente", "pontos": [{"t": "Fungos anemófilos", "sub": ["Fungos contaminantes habitam solo e vegetais e se dispersam principalmente pelo ar. São chamados de anemófilos (slide 11).", "Desencadeiam alergias respiratórias, asma brônquica e rinite alérgica. Podem causar lesões oculares, otites e onicomicoses (slide 11).", "Exemplos microscópicos frequentes no Brasil: Alternaria, Aspergillus, Cladosporium, Curvularia, Epicoccum, Fusarium, Penicillium, Nigrospora e Rhizopus (slide 15)."]}, {"t": "Síndrome dos edifícios doentes", "sub": ["Definida pela OMS em 1982. Ligada a ambientes climatizados. Sintomas: fadiga, letargia, cefaleia, prurido e ardor nos olhos, irritação de nariz e garganta, falta de concentração (slide 12).", "Multicausal. Os fungos anemófilos participam junto com outros agentes (slide 12).", "No Brasil: Portaria 3.523/1998 do MS e Resolução 176/2000 da Anvisa, que usa fungos como marcadores de qualidade do ar interior. Limite: 750 UFC/m³ de ar. Fungos patogênicos e toxigênicos são inaceitáveis (slide 12)."]}]}, {"titulo": "4. Micoses: fungos oportunistas e saprófitas", "pontos": [{"t": "Ubiquidade e comensalismo", "sub": ["A maioria é ubíqua no ambiente: Histoplasma capsulatum, Paracoccidioides brasiliensis, Coccidioides immitis, Blastomyces dermatitidis, Cryptococcus neoformans, Aspergillus fumigatus e Pneumocystis jirovecii (slide 16).", "Candida albicans estabelece comensalismo duradouro na superfície do corpo humano (slide 16).", "A maioria das espécies que causam doença é saprófita e oportunista: infecta quando a resposta imune está comprometida (slide 16)."]}, {"t": "Dimorfismo", "sub": ["Fungos patogênicos alternam formas: saprofítica a 25 °C no solo ou em vegetais, e parasitária a 37 °C nos tecidos. Essa troca permite escapar das defesas antifúngicas e causar micoses sistêmicas após inalação de partículas (slide 18).", "Exemplos da aula: Paracoccidioides e Histoplasma (micélio no ambiente, levedura no tecido)."]}]}, {"titulo": "5. Imunossupressão e micoses oportunistas", "pontos": [{"t": "Por que o hospedeiro muda o desfecho", "sub": ["Infecções por comensais (Candida) ou saprófitas (Aspergillus) ocorrem quase só em imunocomprometidos. A imunidade inata elimina os oportunistas em hospedeiros competentes. A imunossupressão é o fator-chave para infecção disseminada (slide 19).", "Exemplo didático: o mesmo número de conídios de Aspergillus fumigatus não causa doença em camundongo imunocompetente, mas pode causar aspergilose invasiva em paciente imunocomprometido (slide 19).", "Determinantes: tipo e gravidade da imunossupressão + propriedades biológicas do fungo, que definem a espécie predominante (slide 19)."]}, {"t": "Causas clássicas", "sub": ["Radioterapia, quimioterapia para leucemia e transplante de órgãos: Aspergillus (slide 20).", "HIV: Candida albicans, Cryptococcus neoformans e Pneumocystis jirovecii, que são doenças definidoras de AIDS. Candidíase oral e esofágica, criptococose (meningoencefalite), pneumocistose (pneumonia intersticial) (slide 20).", "Candida é a quarta causa mais importante de septicemia adquirida em hospital. Aspergillus fumigatus e A. terreus são causa importante de morte em transplantados de células-tronco hematopoiéticas (slide 20)."]}, {"t": "Neutropenia e fontes", "sub": ["Neutropenia prolongada é o déficit que mais predispõe a infecção fúngica. Grau e duração definem o risco (slide 21).", "Tabela da aula: mais de 500 neutrófilos/µL, risco baixo; 100 a 500 por mais de 7 dias, moderado; menos de 100 por mais de 7 dias, alto; menos de 100 por mais de 14 dias, muito alto (slide 21).", "Fontes: ambiente hospitalar, ar (Aspergillus), microbiota endógena (Candida) e procedimentos invasivos, como cateteres e sondas. Disseminação sanguínea ou linfática leva a micoses invasivas (slide 21)."]}]}, {"titulo": "6. Hipersensibilidade a fungos", "pontos": [{"t": "Doenças alérgicas", "sub": ["A hipersensibilidade tipo I é a doença mais prevalente causada por fungos do ar, como Alternaria, Aspergillus, Cladosporium e Penicillium (slide 22).", "Micose broncopulmonar alérgica (ABPA): inflamação crônica das vias aéreas por Aspergillus. Sinusite crônica alérgica. Pneumonite por hipersensibilidade, por inalação repetida de esporos. Dermatite atópica (slide 22).", "Sensibilização a fungos foi relatada em asma, ABPA e fibrose cística (slide 22)."]}, {"t": "Mecanismo IgE", "sub": ["1) Inalação de esporos (alérgenos). 2) A APC capta o alérgeno e apresenta à Th2. 3) Th2 ativa linfócito B, que produz IgE específica. 4) A IgE liga mastócitos e basófilos (sensibilização). 5) Nova exposição ativa mastócitos, que liberam histamina e leucotrienos. 6) Inflamação, broncoconstrição, muco, prurido e espirros (slide 23).", "Manifestações frequentes: asma, tosse e chiado, rinite e sinusite, falta de ar, dermatite atópica e exacerbações em fibrose cística (slide 23)."]}, {"t": "Autorreatividade", "sub": ["Epítopos fúngicos homólogos a epítopos humanos podem levar à autorreatividade. Esses mecanismos são imunológicos, mas causam reação alérgica em vez de imunidade protetora (slide 22)."]}]}, {"titulo": "7. Imunidade antifúngica", "pontos": [{"t": "Imunidade inata (1ª linha)", "sub": ["Barreiras físicas: pele, mucosas e cílios. Fagócitos: neutrófilos e macrófagos reconhecem e fagocitam fungos por PRRs, como Dectin-1 e TLRs. Células NK produzem citocinas. Citocinas e quimiocinas (IL-1, TNF-α, IL-6, IL-12) atraem e ativam células de defesa. Sistema complemento opsoniza com C3b e pode lisar (ex.: Candida) (slide 24)."]}, {"t": "Imunidade adquirida (2ª linha)", "sub": ["Resposta celular Th1 e Th17: IFN-γ ativa macrófagos; IL-17 recruta neutrófilos e fortalece a barreira (slide 24).", "Resposta humoral: anticorpos IgG e IgA opsonizam fungos, neutralizam enzimas e toxinas (slide 24)."]}, {"t": "Barreiras naturais", "sub": ["Pele: epitélio estratificado queratinizado, peptídeos antimicrobianos, ácidos graxos, pH ácido e microbiota residente.", "Mucosa respiratória: muco e cílios; lisozima, defensinas e lactoferrina; depuração mucociliar.", "Mucosas gastrintestinal e geniturinária: epitélio íntegro com junções, muco, defensinas, IgA, lisozima. A microbiota comensal compete por espaço e nutrientes. Candida pode fazer parte da microbiota normal sem causar doença (slide 26)."]}]}, {"titulo": "8. Reconhecimento e resposta: PAMPs, PRRs e recrutamento", "pontos": [{"t": "Reconhecimento", "sub": ["PAMPs da parede fúngica: mananas (receptor de manose, MR), β-glucanas (dectina-1, β-1,3 e β-1,6) e quitina (slide 27).", "PRRs: receptor de manose, dectina-1, TLR2 e TLR4 (mananas e proteínas), TLR9 (DNA fúngico), CR3 e outros (slide 27)."]}, {"t": "Recrutamento de neutrófilos", "sub": ["Reconhecimento → liberação de citocinas e quimiocinas → recrutamento de leucócitos (rolamento por selectinas, adesão firme por integrinas, diapedese) → inflamação local (slide 28).", "O complemento gera C3a e C5a, que atraem e ativam neutrófilos (slide 28)."]}, {"t": "Célula dendrítica e linfócito T", "sub": ["A célula dendrítica detecta fungos por PRRs, fagocita, processa, migra ao linfonodo e apresenta o antígeno por MHC II ao linfócito T CD4+ naive. A diferenciação define Th1, Th17, Th2 ou Treg (slide 32).", "A imunidade inata orienta qual resposta adaptativa será construída (slide 32)."]}, {"t": "Th1 e microbicida", "sub": ["IL-12 da célula dendrítica ou do macrófago diferencia Th1. Th1 secreta IFN-γ, que ativa o macrófago (M1): mais ROS, NO, fusão fagolisossomal e enzimas lisossômicas (slide 33)."]}]}, {"titulo": "9. Desfecho da infecção: exemplos com Aspergillus e Candida", "pontos": [{"t": "Aspergillus no alvéolo", "sub": ["Conídio pequeno: pode ser fagocitado por macrófago alveolar e degradado. Hifa grande: não é fagocitada, e os neutrófilos atacam por via extracelular, com granulações, enzimas proteolíticas e espécies reativas (slide 29).", "Imunocompetente: macrófagos eliminam conídios, hifas ficam restritas ao alvéolo, neutrófilos destroem as hifas. Resultado: infecção controlada (slide 30).", "Neutropênico: menos macrófagos ativos, conídios germinam, hifas não são destruídas, invadem o tecido e os vasos, e disseminam por via hematogênica (cérebro, rim). Fator crítico: neutropenia prolongada (slide 30)."]}, {"t": "Candida: da colonização à candidemia", "sub": ["1) Colonização: mucosa íntegra, microbiota equilibrada, neutrófilos controlam Candida. 2) Candidíase mucocutânea: desequilíbrio da microbiota e barreira comprometida; leveduras e pseudo-hifas causam placas, coceira e ardor. 3) Candidíase invasiva e candidemia: ruptura da barreira, hifas invadem vasos e disseminam (slide 31).", "Fatores de progressão: antibióticos, diabetes mal controlado, imunossupressão (corticoide, quimioterapia, transplante, HIV), cateteres e dispositivos, ruptura da barreira por cirurgia, mucosite ou fístulas (slide 31)."]}, {"t": "Th17 e Candida na mucosa", "sub": ["IL-17 induz quimiocinas (CXCL1, CXCL8) e G-CSF, que recrutam neutrófilos. Neutrófilos controlam Candida por fagocitose, degranulação e NETs (slide 36).", "IL-22 fortalece a barreira epitelial, aumenta peptídeos antimicrobianos (β-defensinas, S100, Reg3γ), muco e proteínas de junção (claudinas, ocludina) (slide 36)."]}]}, {"titulo": "10. Granuloma, Histoplasma e equilíbrio imunológico", "pontos": [{"t": "Histoplasma capsulatum", "sub": ["Microconídios são inalados e fagocitados por macrófagos alveolares. Leveduras sobrevivem dentro do fagolisossomo e são transportadas por macrófagos até fígado, baço, pulmão e medula (slide 34).", "Resposta protetora: Th1 libera IFN-γ, o macrófago se ativa e controla o fungo intracelular. Fagocitar não é necessariamente eliminar (slide 34)."]}, {"t": "Granuloma", "sub": ["Estratégia de contenção quando o agente persiste: macrófagos fagocitam; Th1 é induzida; IFN-γ ativa macrófagos, que viram células epitelioides; células gigantes multinucleadas se formam; o fungo fica confinado no centro, podendo haver necrose caseosa (slide 35)."]}, {"t": "Balança imunológica", "sub": ["Respostas efetoras: Th1 (IFN-γ) ativam macrófagos; Th17 (IL-17, IL-22) recrutam neutrófilos. Respostas regulatórias: Treg (IL-10, TGF-β) limitam o dano (slide 39).", "Resposta equilibrada: fungo controlado, tecido preservado. Resposta insuficiente: aspergilose invasiva e disseminação. Resposta excessiva: dano tecidual, hiperreatividade, fibrose (slide 39)."]}, {"t": "ABPA e a resposta exagerada", "sub": ["ABPA: exposição a Aspergillus com resposta Th2 (IL-4, IL-13), IgE anti-Aspergillus e sensibilização de mastócitos. Consequências: broncoconstrição, hiperplasia de células caliciformes e aumento de muco, inflamação eosinofílica. Manifestações: asma, tosse, sibilância, opressão torácica (slide 37).", "Dois caminhos para o mesmo fungo: neutropênico (aspergilose invasiva) e asmático ou atópico imunocompetente (doença alérgica) (slide 38)."]}]}, {"titulo": "11. Dermatófitos e dermatofitoses", "pontos": [{"t": "Classificação e gêneros", "sub": ["Classificação clínica de Odds e colaboradores (1992), da ISHAM. Engloba infecções por fungos, actinomicetos e algas (slide 41).", "Micoses superficiais: acometem camadas superficiais da pele, pelos e unhas. Micoses profundas: subcutâneas ou sistêmicas (slides 42 e 43).", "Dermatófitos são fungos anamorfos (sem reprodução sexuada) de três gêneros: Microsporum (descrito por David Gruby, 1843), Trichophyton (Malmsten, 1845) e Epidermophyton (Sabouraud, 1907) (slide 47).", "Geofílicos vivem no solo e infectam ocasionalmente o homem. Zoofílicos parasitam animais e raramente o homem. Antropofílicos parasitam preferencialmente o homem (slide 47)."]}, {"t": "Fatores que influenciam a distribuição", "sub": ["Sexo (mais comum no masculino), idade (tinha do couro cabeludo em crianças; tinha do pé e inguinocrural em adultos), imunidade (mais no imunocomprometido), hábitos e populações fechadas, como navios e creches. Migrações: Trichophyton violaceum no Brasil nos anos 1930 (slide 48).", "Sazonalidade: mais comum no verão e no outono (slide 48)."]}, {"t": "Contágio e defesa da pele", "sub": ["A epiderme íntegra é barreira. Umidade local é pré-requisito para inoculação e sobrevivência (slide 49).", "Contágio direto (humano, animal, solo) ou indireto (fômites). Microsporum tem predileção por pele e pelo; Epidermophyton por pele e unha; Trichophyton por pele, pelo e unha (slide 49).", "Fatores séricos antifúngicos: transferrina insaturada inibe o crescimento; alfa-2-macroglobulina inibe a queratinase (slide 49)."]}, {"t": "Resposta imune à dermatofitose", "sub": ["Boa resposta celular T, com citocinas e recrutamento de células efetoras, leva à resolução. Resposta deficiente leva à persistência e infecção crônica ou recorrente, classicamente com Trichophyton rubrum. Anticorpos têm papel secundário (slide 50)."]}, {"t": "Variantes clínicas", "sub": ["Tinha do couro cabeludo (microspórica: lesão única por zoofílico ou geofílico; tricofítica: múltiplas lesões por antropofílico). Nas regiões Sul e Sudeste, Microsporum canis é o mais frequente. No Norte e Nordeste, Trichophyton tonsurans (slides 51 e 52).", "Tinha da barba, do corpo (lesão anular de crescimento centrífugo e cura central), inguinocrural (Epidermophyton floccosum na forma epidêmica; T. rubrum na endêmica), da unha, do pé, da mão e imbricada. Dermatofítide: forma alérgica (slides 51 a 54).", "Quérion celsi: processo inflamatório agudo, com cicatriz, quando o fungo é não adaptado ao homem (slide 52)."]}, {"t": "Diagnóstico", "sub": ["Exame direto com KOH: pelos (endotrix: esporos e hifas dentro do pelo; ectotrix: esporos fora do pelo) ou escamas. Pelos tonsurados são colhidos com pinça. Na onicomicose superficial branca, raspagem da lâmina ungueal sobre a lesão branca (slide 58).", "Cultura: Sabouraud com cicloheximida e cloranfenicol, crescimento em cerca de 2 semanas. Identificação pela macromorfologia e micromorfologia (slide 59).", "Lâmpada de Wood (Robert Williams Wood): Microsporum dá fluorescência esverdeada. Trichophyton não fluoresce, exceto T. schoenleinii na tinha favosa, hoje rara (slide 61).", "Provas imunológicas: anticorpos específicos são detectados, mas sem expressividade clínica (slide 62)."]}, {"t": "Onicomicose", "sub": ["Engloba agentes além de dermatófitos, como Candida, fungos filamentosos não dermatófitos e leveduras exógenas. Com dermatófito, é tinha da unha. Pode ter forma subungueal distal ou lateral, subungueal proximal e superficial branca, todas podendo evoluir para distrofia. Em imunodeprimidos: acometimento múltiplo, agudo e subungueal proximal (slide 54)."]}]}], "glossario": [{"termo": "Heterotrófico", "tecnica": "Morfologia", "definicao": "Organismo que depende de matéria orgânica pronta para obter energia. Todos os fungos são heterotróficos.", "slide": 2}, {"termo": "Quitina", "tecnica": "Parede celular", "definicao": "Principal componente estrutural da parede fúngica.", "slide": 3}, {"termo": "α-glucana e β-glucana", "tecnica": "Parede celular", "definicao": "Polissacarídeos da parede. Na fase M (25 °C) predomina a α-glucana. Na fase Y (37 °C) predomina a β-glucana, relacionada à patogenicidade.", "slide": 3}, {"termo": "Manoproteína (mananas)", "tecnica": "Parede celular", "definicao": "Glicoproteínas da parede formadas por mananas (polissacarídeos de manose) combinadas com proteínas. Reconhecidas pelo receptor de manose.", "slide": 3}, {"termo": "Ergosterol", "tecnica": "Membrana", "definicao": "Esterol da membrana fúngica. Alvo dos antifúngicos que inibem a síntese de ergosterol.", "slide": 4}, {"termo": "Glicogênio fúngico", "tecnica": "Citoplasma", "definicao": "Principal reserva de energia dos fungos, armazenada em inclusões citoplasmáticas.", "slide": 5}, {"termo": "Cápsula de Cryptococcus neoformans", "tecnica": "Patogenicidade", "definicao": "Cápsula mucopolissacarídica que dificulta a fagocitose e é central na patogênese.", "slide": 6}, {"termo": "Cissiparidade", "tecnica": "Reprodução assexuada", "definicao": "Divisão direta da levedura: o núcleo se divide e um septo separa duas células iguais.", "slide": 7}, {"termo": "Brotamento (gemulação)", "tecnica": "Reprodução assexuada", "definicao": "Formação de um broto na levedura, que recebe um núcleo e se separa da célula-mãe.", "slide": 7}, {"termo": "Plasmogamia, cariogamia e meiose", "tecnica": "Reprodução sexuada", "definicao": "Fusão celular, fusão nuclear e divisão meiótica. Exemplo: Saccharomyces cerevisiae.", "slide": 7}, {"termo": "Hifa e micélio", "tecnica": "Morfologia", "definicao": "Hifa é a célula tubular do bolor. O conjunto de hifas forma o micélio.", "slide": 8}, {"termo": "Anemófilo", "tecnica": "Ambiente", "definicao": "Fungo especializado na dispersão pelo ar. Causa alergias respiratórias e, eventualmente, lesões oculares e otites.", "slide": 11}, {"termo": "Síndrome dos edifícios doentes", "tecnica": "Ambiente", "definicao": "Conjunto de sintomas em ambientes climatizados, definida pela OMS em 1982. Multicausal, com fungos como um dos fatores.", "slide": 12}, {"termo": "Resolução 176/2000 (Anvisa)", "tecnica": "Vigilância ambiental", "definicao": "Usa fungos como marcadores de qualidade do ar interior. Limite de 750 UFC/m³ de ar.", "slide": 12}, {"termo": "Dimorfismo termodependente", "tecnica": "Morfologia", "definicao": "Troca de forma entre mofo a 25 °C e levedura a 37 °C. Permite escapar das defesas antifúngicas.", "slide": 18}, {"termo": "Imunidade inata", "tecnica": "Imunidade", "definicao": "Primeira linha de defesa: barreiras, fagócitos, células NK, citocinas e complemento. Elimina a maioria dos oportunistas em hospedeiros competentes.", "slide": 19}, {"termo": "Candida albicans", "tecnica": "Agente oportunista", "definicao": "Levedura comensal da superfície humana. Causa candidíase mucocutânea e invasiva quando há desequilíbrio ou imunossupressão.", "slide": 16}, {"termo": "Aspergillus fumigatus", "tecnica": "Agente oportunista", "definicao": "Bolor ambiental ubíquo, de conídios pequenos e hifas septadas. Causa aspergilose invasiva em neutropênicos.", "slide": 19}, {"termo": "Aspergillus terreus", "tecnica": "Agente oportunista", "definicao": "Espécie do gênero Aspergillus relacionada à aspergilose invasiva em transplantados de células hematopoiéticas.", "slide": 20}, {"termo": "Pneumocystis jirovecii (antigo P. carinii)", "tecnica": "Agente oportunista", "definicao": "Fungo que causa pneumocistose em hospedeiros imunossuprimidos, sobretudo HIV. Pneumonia intersticial. Doença definidora de AIDS.", "slide": 20}, {"termo": "Doença definidora de AIDS", "tecnica": "Epidemiologia", "definicao": "Infecção que define o estágio de AIDS. Entre as micoses, incluem-se candidíase oral e esofágica, criptococose e pneumocistose.", "slide": 20}, {"termo": "Neutropenia prolongada", "tecnica": "Imunidade", "definicao": "Déficit de neutrófilos que mais predispõe a micoses invasivas. Grau e duração definem o risco.", "slide": 21}, {"termo": "Micose broncopulmonar alérgica (ABPA)", "tecnica": "Hipersensibilidade", "definicao": "Inflamação crônica das vias aéreas por Aspergillus, em pacientes predispostos. Alta IgE e tampões brônquicos.", "slide": 22}, {"termo": "Hipersensibilidade tipo I", "tecnica": "Hipersensibilidade", "definicao": "Reação mediada por IgE e mastócitos, a mais prevalente causada por fungos do ar.", "slide": 22}, {"termo": "Epítopo homólogo", "tecnica": "Autorreatividade", "definicao": "Epítopo fúngico semelhante a um epítopo humano, que pode induzir autorreatividade.", "slide": 22}, {"termo": "IgE", "tecnica": "Imunoglobulina", "definicao": "Anticorpo que se liga aos mastócitos e basófilos e medeia a hipersensibilidade tipo I.", "slide": 23}, {"termo": "Mastócito", "tecnica": "Célula efetora", "definicao": "Célula que libera histamina, leucotrienos e prostaglandinas quando estimulada pela IgE. Responsável pelos sintomas alérgicos.", "slide": 23}, {"termo": "Dectina-1", "tecnica": "PRR (receptor)", "definicao": "Receptor de célula imune que reconhece β-glucanas da parede fúngica.", "slide": 24}, {"termo": "TLR (receptor Toll-like)", "tecnica": "PRR (receptor)", "definicao": "Receptores de reconhecimento de padrões. TLR2 e TLR4 reconhecem mananas e proteínas; TLR9 reconhece DNA fúngico.", "slide": 24}, {"termo": "Receptor de manose (MR)", "tecnica": "PRR (receptor)", "definicao": "Receptor de macrófago que reconhece mananas da parede fúngica.", "slide": 27}, {"termo": "PAMP", "tecnica": "Reconhecimento", "definicao": "Padrão molecular associado a patógenos, como β-glucanas, mananas e quitina.", "slide": 27}, {"termo": "PRR", "tecnica": "Reconhecimento", "definicao": "Receptor de reconhecimento de padrões, na membrana ou no citoplasma de células imunes, que detecta PAMPs.", "slide": 27}, {"termo": "Quimiocina", "tecnica": "Citocina", "definicao": "Citocina que atrai leucócitos ao local da infecção. Exemplos: CXCL1 e CXCL8.", "slide": 28}, {"termo": "Complemento C3b e C5a", "tecnica": "Complemento", "definicao": "C3b opsoniza o fungo. C3a e C5a atraem e ativam neutrófilos.", "slide": 28}, {"termo": "Selectina e integrina", "tecnica": "Adesão leucocitária", "definicao": "Selectinas causam rolamento do neutrófilo. Integrinas causam adesão firme ao endotélio, antes da diapedese.", "slide": 28}, {"termo": "Célula dendrítica", "tecnica": "Apresentação de antígeno", "definicao": "Célula que fagocita o fungo, migra ao linfonodo e apresenta antígeno por MHC II ao linfócito T CD4+ naive.", "slide": 32}, {"termo": "MHC II", "tecnica": "Apresentação de antígeno", "definicao": "Molécula que apresenta peptídeos fúngicos ao linfócito T CD4+.", "slide": 32}, {"termo": "Th1", "tecnica": "Linfócito T", "definicao": "Linfócito T auxiliar que secreta IFN-γ e ativa macrófagos. Essencial no controle de fungos intracelulares.", "slide": 33}, {"termo": "IFN-γ", "tecnica": "Citocina", "definicao": "Citocina de Th1 que ativa macrófagos, aumenta ROS, NO e a fusão fagolisossomal.", "slide": 33}, {"termo": "IL-12", "tecnica": "Citocina", "definicao": "Citocina produzida por células dendríticas e macrófagos. Diferencia linfócito T CD4+ em Th1.", "slide": 33}, {"termo": "Th17 e IL-17", "tecnica": "Linfócito T", "definicao": "Th17 secreta IL-17, que recruta neutrófilos e fortalece barreiras. Essencial na proteção de mucosas contra Candida.", "slide": 36}, {"termo": "IL-22", "tecnica": "Citocina", "definicao": "Citocina de Th17 que fortalece a barreira epitelial e aumenta peptídeos antimicrobianos e proteínas de junção.", "slide": 36}, {"termo": "Granuloma", "tecnica": "Resposta granulomatosa", "definicao": "Estrutura de contenção formada por macrófagos epitelioides, células gigantes e linfócitos, em torno de um agente persistente.", "slide": 35}, {"termo": "Célula gigante multinucleada", "tecnica": "Resposta granulomatosa", "definicao": "Fusão de macrófagos que forma o núcleo do granuloma.", "slide": 35}, {"termo": "Treg e IL-10", "tecnica": "Regulação", "definicao": "Linfócito T regulador que limita a resposta inflamatória por IL-10 e TGF-β.", "slide": 39}, {"termo": "Histoplasma capsulatum", "tecnica": "Agente", "definicao": "Fungo dimórfico, inalado do solo com excretas. Sobrevive dentro de macrófagos e se dissemina.", "slide": 34}, {"termo": "Paracoccidioides brasiliensis", "tecnica": "Agente", "definicao": "Fungo dimórfico endêmico da América Latina, com levedura multibrotante em roda de leme.", "slide": 16}, {"termo": "Coccidioides immitis", "tecnica": "Agente", "definicao": "Fungo dimórfico de regiões áridas. Forma esférulas com endósporos nos tecidos.", "slide": 16}, {"termo": "Blastomyces dermatitidis", "tecnica": "Agente", "definicao": "Fungo dimórfico endêmico que causa blastomicose pulmonar.", "slide": 16}, {"termo": "Dermatófito", "tecnica": "Agente", "definicao": "Fungo queratinofílico de três gêneros (Microsporum, Trichophyton, Epidermophyton) que causa dermatofitose.", "slide": 47}, {"termo": "Microsporum", "tecnica": "Dermatófito", "definicao": "Gênero descrito por David Gruby em 1843. Predileção por pele e pelo. Fluorescência verde na lâmpada de Wood.", "slide": 47}, {"termo": "Trichophyton", "tecnica": "Dermatófito", "definicao": "Gênero descrito por Malmsten em 1845. Afeta pele, pelo e unha. Causa tinhas tonsurantes (ex.: T. tonsurans).", "slide": 47}, {"termo": "Epidermophyton", "tecnica": "Dermatófito", "definicao": "Gênero descrito por Sabouraud em 1907. Afeta pele e unha, sem pelo.", "slide": 47}, {"termo": "Geofílico, zoofílico e antropofílico", "tecnica": "Classificação de dermatófitos", "definicao": "Geofílico: vive no solo. Zoofílico: parasita animais. Antropofílico: parasita o homem.", "slide": 47}, {"termo": "Trichophyton violaceum", "tecnica": "Dermatófito", "definicao": "Espécie que teve alta incidência no Brasil nos anos 1930, por migração de Portugal e do Mediterrâneo.", "slide": 48}, {"termo": "Transferrina insaturada e alfa-2-macroglobulina", "tecnica": "Imunidade sérica", "definicao": "Fatores séricos antifúngicos. A transferrina insaturada inibe o crescimento do dermatófito. A alfa-2-macroglobulina inibe a queratinase.", "slide": 49}, {"termo": "Trichophyton rubrum", "tecnica": "Dermatófito", "definicao": "Espécie clássica de infecção crônica e recorrente, ligada à resposta celular deficiente. Causa tinha da unha e do pé.", "slide": 50}, {"termo": "Microsporum canis", "tecnica": "Dermatófito zoofílico", "definicao": "Agente mais frequente de tinha do couro cabeludo no Sul e no Sudeste, adquirido de animais infectados.", "slide": 51}, {"termo": "Trichophyton tonsurans", "tecnica": "Dermatófito", "definicao": "Agente mais isolado de tinha do couro cabeludo no Norte e no Nordeste.", "slide": 51}, {"termo": "Epidermophyton floccosum", "tecnica": "Dermatófito", "definicao": "Causa a forma epidêmica da tinha inguinocrural.", "slide": 54}, {"termo": "Quérion celsi", "tecnica": "Manifestação", "definicao": "Processo inflamatório agudo com cicatriz, causado por dermatófito não adaptado ao homem.", "slide": 52}, {"termo": "Dermatofítide", "tecnica": "Manifestação", "definicao": "Reação alérgica a dermatófito, à distância do foco infeccioso.", "slide": 51}, {"termo": "Endotrix e ectotrix", "tecnica": "Diagnóstico direto", "definicao": "Padrões de invasão do pelo no exame direto. Endotrix: esporos dentro do pelo. Ectotrix: esporos fora do pelo.", "slide": 58}, {"termo": "Sabouraud com cicloheximida e cloranfenicol", "tecnica": "Meio de cultura", "definicao": "Meio para cultivo de dermatófitos. Crescimento em cerca de duas semanas.", "slide": 59}, {"termo": "Lâmpada de Wood (Robert Williams Wood)", "tecnica": "Diagnóstico", "definicao": "Luz ultravioleta que mostra fluorescência verde em tinhas por Microsporum. Trichophyton geralmente não fluoresce.", "slide": 61}, {"termo": "Classificação de Odds (1992)", "tecnica": "Classificação clínica", "definicao": "Classificação clínica das micoses proposta por Odds e colaboradores, em 1992, com base na ISHAM. Inclui fungos, actinomicetos e algas.", "slide": 41}, {"termo": "ISHAM", "tecnica": "Sociedade científica", "definicao": "Sociedade Internacional de Micologia Humana e Animal, cuja recomendação embasa a classificação de Odds.", "slide": 41}], "fontes": ["Aula 2, Fungos de interesse clínico (pdf/natalia/aulas/aula-02.pdf, slides 1 a 63)", "Base complementar: Murray, Medical Microbiology (micologia médica); Odds FC et al., 1992 (classificação clínica)"], "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um camundongo imunocompetente e um paciente imunocomprometido inalam o mesmo número de conídios de Aspergillus fumigatus. Pela aula, qual é o principal fator que define se haverá aspergilose invasiva?", "alternativas": ["O tamanho do paciente, porque o camundongo tem menos alvéolos, menos macrófagos e menos neutrófilos", "A cor da hifa, porque fungos hialinos são sempre mais invasivos", "A temperatura do ambiente, porque 25 °C favorece a levedura nos alvéolos", "O estado do hospedeiro: a imunidade inata elimina os conídios no imunocompetente", "A parede de quitina, porque o paciente imunocomprometido produz menos quitinase"], "gabarito": "D", "justificativa": "A imunossupressão é o fator-chave. O mesmo inóculo não causa doença no camundongo imunocompetente, mas causa aspergilose invasiva no imunocomprometido (Aula 2, slide 19).", "tecnica": "Micoses oportunistas", "slide": 19, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um paciente em quimioterapia para leucemia tem neutrófilos de 80/µL há 10 dias. Pela tabela da aula, qual é o risco de infecção fúngica invasiva?", "alternativas": ["Alto (menos de 100 neutrófilos por mais de 7 dias)", "Baixo, porque a faixa de baixo risco começa abaixo de 500", "Moderado (faixa de 100 a 500 por mais de 7 dias)", "Muito alto, porque só se fala em risco muito alto abaixo de 50", "Nenhum, porque a neutropenia não predispõe a micoses"], "gabarito": "A", "justificativa": "Menos de 100 neutrófilos/µL por mais de 7 dias é risco alto. Mais de 14 dias é muito alto. A neutropenia prolongada é o déficit que mais predispõe (Aula 2, slide 21).", "tecnica": "Neutropenia", "slide": 21, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Pela aula, qual é o padrão de reconhecimento que a dectina-1 faz na parede fúngica, e qual é o componente da parede que ela detecta?", "alternativas": ["Dectina-1 reconhece quitina, e a manose é reconhecida pelos TLR9", "Dectina-1 reconhece ergosterol da membrana, e a glucana é reconhecida pelo complemento", "Dectina-1 reconhece β-glucanas, um PAMP da parede fúngica", "Dectina-1 reconhece DNA fúngico, e a quitina é reconhecida pelo MR", "Dectina-1 reconhece lipopolissacarídeo, e a glucana é reconhecida pela IgE"], "gabarito": "C", "justificativa": "Dectina-1 é um PRR que reconhece β-glucanas (PAMP). Mananas são reconhecidas pelo receptor de manose, e DNA fúngico pelo TLR9 (Aula 2, slides 24 e 27).", "tecnica": "PAMPs e PRRs", "slide": 27, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um conídio de Aspergillus é pequeno e pode ser fagocitado, mas a hifa é grande. Pela aula, qual célula atua contra a hifa e por qual via?", "alternativas": ["Macrófago alveolar, por fagocitose completa da hifa", "Linfócito B, por neutralização direta com IgE", "Neutrófilo, por via extracelular, com granulações e espécies reativas", "Mastócito, por degranulação de histamina sobre a hifa, sem contato direto com o fungo", "Célula NK, por lise da membrana de quitina"], "gabarito": "C", "justificativa": "Hifas são grandes demais para serem fagocitadas. Os neutrófilos atacam extracelularmente, com granulações, enzimas proteolíticas e ROS. Conídios pequenos são fagocitados por macrófagos (Aula 2, slide 29).", "tecnica": "Conídio e hifa", "slide": 29, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Em um paciente com candidíase mucocutânea, há placas e ardor, sem disseminação. Pela aula, em qual das três fases da Candida esse quadro se encaixa e qual é o gatilho?", "alternativas": ["Candidíase mucocutânea, com desequilíbrio da microbiota", "Colonização, com mucosa íntegra e microbiota equilibrada", "Candidemia, com ruptura da barreira e disseminação hematogênica", "Aspergilose, com germinação de conídios no alvéolo", "Histoplasmose, com macrófagos infectados e granuloma"], "gabarito": "A", "justificativa": "Na candidíase mucocutânea há proliferação de leveduras e pseudo-hifas, com placas, coceira e ardor, sem disseminação. O gatilho é o desequilíbrio da microbiota ou barreira comprometida (Aula 2, slide 31).", "tecnica": "Candida", "slide": 31, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um paciente com cateter venoso central e cirurgia abdominal desenvolve levedura na corrente sanguínea. Pela aula, qual é a fase de Candida e qual é o principal fator de progressão?", "alternativas": ["Colonização, com microbiota normal da pele", "Candidemia, com ruptura da barreira pelo cateter", "Candidíase oral, com uso de antibiótico", "Dermatofitose, com contato com fômites", "Aspergilose broncopulmonar, com asma associada e tampões brônquicos"], "gabarito": "B", "justificativa": "A fase 3 é candidíase invasiva ou candidemia, com quebra de barreira. Cateter vascular, cirurgia abdominal e UTI são gatilhos citados (Aula 2, slide 31).", "tecnica": "Candida: fases", "slide": 31, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um agricultor com asma tem tampões brônquicos e IgE alta em resposta a Aspergillus, sem invasão tecidual. Pela aula, qual é o diagnóstico mais provável e qual é o mecanismo?", "alternativas": ["Aspergilose invasiva, por neutropenia prolongada e angioinvasão tecidual", "ABPA, por resposta Th2 com IgE e sensibilização de mastócitos", "Mucormicose, por cetoacidose diabética", "Histoplasmose, por macrófago infectado", "Criptococose, por cápsula de glucuronoxilomanano"], "gabarito": "B", "justificativa": "Na ABPA, a resposta Th2 gera IgE anti-Aspergillus, que sensibiliza mastócitos. O dano é inflamação e broncoconstrição, sem invasão tecidual (Aula 2, slides 22 e 37).", "tecnica": "Hipersensibilidade", "slide": 37, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Pela aula, qual é o papel de Th1 e de IFN-γ na defesa contra Histoplasma capsulatum, que sobrevive dentro de macrófagos?", "alternativas": ["Th1 libera IgE, que opsoniza as leveduras e inibe a fagocitose", "Th1 libera IL-4, que reduz a ativação do macrófago e favorece a levedura", "Th1 libera IFN-γ, que ativa o macrófago e controla a levedura", "Th1 libera IL-10, que suprime a inflamação e permite a disseminação", "Th1 libera histamina, que destrói a parede da levedura"], "gabarito": "C", "justificativa": "Th1 libera IFN-γ. Isso ativa macrófagos, aumenta ROS e NO e a fusão fagolisossomal, restringindo a multiplicação das leveduras (Aula 2, slide 34).", "tecnica": "Histoplasma e Th1", "slide": 34, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um granuloma se forma em torno de um fungo persistente. Pela aula, qual é a sequência de células que forma o granuloma e qual é o papel do centro?", "alternativas": ["Neutrófilos se acumulam e liberam IgE, que destrói o fungo no centro do granuloma sem células gigantes", "Mastócitos liberam histamina, que forma uma cicatriz sem células gigantes", "Linfócitos B produzem anticorpos que digerem o fungo, sem macrófagos", "Células NK lisam o fungo, e o centro do granuloma contém apenas tecido necrótico", "Macrófagos ativados viram epitelioides; formam-se células gigantes; o fungo fica confinado no centro"], "gabarito": "E", "justificativa": "Granuloma é contenção quando o agente persiste. IFN-γ ativa macrófagos, que viram epitelioides e formam células gigantes. O fungo fica confinado no centro (Aula 2, slide 35).", "tecnica": "Granuloma", "slide": 35, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Pela aula, qual citocina de Th17 recruta neutrófilos e qual citocina fortalece a barreira epitelial contra Candida?", "alternativas": ["IL-22 recruta neutrófilos; IL-17 fortalece a barreira epitelial", "IL-10 recruta neutrófilos; TGF-β fortalece a barreira epitelial", "IFN-γ recruta neutrófilos; IL-4 fortalece a barreira epitelial", "IgE recruta neutrófilos; IgG fortalece a barreira epitelial", "IL-17 recruta neutrófilos; IL-22 fortalece a barreira epitelial"], "gabarito": "E", "justificativa": "IL-17 induz quimiocinas e recruta neutrófilos. IL-22 fortalece a barreira, aumenta peptídeos antimicrobianos e proteínas de junção (Aula 2, slide 36).", "tecnica": "Th17", "slide": 36, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Uma dermatofitose de couro cabeludo com lesão única é causada por um dermatófito zoofílico, e a lâmpada de Wood mostra fluorescência verde. Pela aula, qual gênero é mais provável?", "alternativas": ["Trichophyton", "Microsporum", "Epidermophyton", "Histoplasma", "Candida"], "gabarito": "B", "justificativa": "Microsporum tem fluorescência verde na lâmpada de Wood. A tinha microspórica é uma lesão única por zoofílico ou geofílico (Aula 2, slides 51 e 61).", "tecnica": "Dermatófitos", "slide": 61, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Pela aula, qual é a diferença entre os gêneros Microsporum, Trichophyton e Epidermophyton quanto à predileção de tecido e ao cientista que os descreveu?", "alternativas": ["Microsporum (Gruby), pele e pelo; Trichophyton (Malmsten), pele, pelo e unha; Epidermophyton (Sabouraud), pele e unha", "Microsporum por Sabouraud (1907), unha; Trichophyton por Gruby (1843), pele; Epidermophyton por Malmsten (1845), pelo, sem envolvimento ungueal", "Microsporum por Malmsten (1845), pelo; Trichophyton por Sabouraud (1907), unha; Epidermophyton por Gruby (1843), pele", "Todos por Gruby (1843), com predileção exclusiva por unhas", "Microsporum por Gruby (1843), apenas unha; Trichophyton por Sabouraud, apenas pele"], "gabarito": "A", "justificativa": "Microsporum (Gruby, 1843) tem predileção por pele e pelo. Trichophyton (Malmsten, 1845) afeta pele, pelo e unha. Epidermophyton (Sabouraud, 1907) afeta pele e unha (Aula 2, slides 47 e 49).", "tecnica": "Gêneros de dermatófitos", "slide": 47, "pdf": "pdf/natalia/aulas/aula-02.pdf", "epônimo": "Gruby"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Uma tinha crônica e recorrente em adulto, com unha e pé comprometidos, sugere uma resposta celular deficiente. Pela aula, qual dermatófito é classicamente associado a esse quadro?", "alternativas": ["Microsporum canis", "Trichophyton tonsurans", "Epidermophyton floccosum na forma epidêmica", "Trichophyton violaceum", "Trichophyton rubrum"], "gabarito": "E", "justificativa": "T. rubrum é classicamente associado à infecção crônica e recorrente, quando a resposta celular é deficiente. Anticorpos têm papel secundário (Aula 2, slide 50).", "tecnica": "Resposta a dermatófitos", "slide": 50, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Um paciente tem sintomas de síndrome dos edifícios doentes em ambiente climatizado. Pela aula, qual limite de fungos dispersos no ar é usado pela Resolução 176/2000, e qual é a categoria inaceitável?", "alternativas": ["1.500 UFC/m³ de ar; apenas fungos com esporos pigmentados", "100 UFC/m³ de ar; apenas leveduras", "750 UFC/L de ar; apenas dermatófitos", "750 UFC/m³ de ar; fungos patogênicos e toxigênicos", "10.000 UFC/m³ de ar; apenas fungos anemófilos"], "gabarito": "D", "justificativa": "A Resolução 176/2000 da Anvisa fixa 750 UFC/m³ de ar. Fungos patogênicos e toxigênicos são inaceitáveis (Aula 2, slide 12).", "tecnica": "Ambiente e saúde", "slide": 12, "pdf": "pdf/natalia/aulas/aula-02.pdf"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Uma levedura unicelular com cápsula dificulta a fagocitose e pode causar meningoencefalite em paciente com HIV. Pela aula, qual gênero e qual é a doença definidora de AIDS associada?", "alternativas": ["Candida albicans, com candidíase oral", "Pneumocystis jirovecii, com pneumocistose", "Aspergillus fumigatus, com aspergilose", "Cryptococcus neoformans, com criptococose", "Histoplasma capsulatum, com histoplasmose pulmonar"], "gabarito": "D", "justificativa": "Cryptococcus neoformans tem cápsula mucopolissacarídica que dificulta a fagocitose. No HIV causa criptococose, com meningoencefalite (Aula 2, slides 6 e 20).", "tecnica": "HIV e micoses", "slide": 20, "pdf": "pdf/natalia/aulas/aula-02.pdf"}], "id": "natalia-aula-02", "voltar": {"href": "#/agressao/natalia", "texto": "Professora Natália"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["natalia-aula-03"] = {"titulo": "Aula 3", "subtitulo": "Classificação clínica das micoses II: porta de entrada, profundidade, hospedeiro e amostra", "pdf": "pdf/natalia/aulas/aula-03.pdf", "abas": ["resumo", "glossario", "quiz", "pdf"], "resumo": [{"titulo": "1. Método: seguir a infecção, não decorar o fungo", "pontos": [{"t": "Três pilares da classificação", "sub": ["Entrada (porta): contato direto, trauma ou inoculação, inalação, origem endógena ou cateter. Destino (tecido): superfície e queratina, subcutâneo e linfático, pulmão, sangue e órgãos internos. Hospedeiro: defesa preservada, barreira anatômica rompida, neutropenia ou imunossupressão grave (slide 11).", "A classificação nasce da combinação dessas três respostas (slide 11). Classificação é ferramenta de raciocínio, não lista de nomes (slide 54).", "A profundidade organiza o primeiro mapa: superficial e cutânea (estrato córneo, pelos, unhas); implantação (derme e subcutâneo após trauma); sistêmica endêmica (entrada pulmonar); oportunista ou invasiva (disseminação por sangue ou órgãos) (slide 55).", "Base: Murray, Medical Microbiology, capítulos de micologia médica."]}, {"t": "Porta de entrada", "sub": ["Contato direto: fricção com pele, animais ou fômites, causando micoses cutâneas (slide 56).", "Inoculação traumática: perfuração da barreira cutânea, causando micoses de implantação (slide 56).", "Inalação ambiental: propágulos no ar, causando micoses sistêmicas endêmicas (slide 56).", "Quebra de barreira: acesso por cateter ou translocação da microbiota, causando infecção oportunista (slide 56).", "Inalar propágulos do ambiente não significa transmissão respiratória entre pessoas. Isolamento de contato não se aplica (slide 56)."]}]}, {"titulo": "2. Micoses de implantação (subcutâneas)", "pontos": [{"t": "Mecanismo", "sub": ["Espinho, farpa de madeira ou arranhadura rompem a epiderme e depositam o fungo na derme ou no subcutâneo. A barreira íntegra é impenetrável; a inoculação dá início à doença (slide 13).", "Não é micose superficial que se aprofundou: sem penetração ativa, o contato superficial não causa infecção profunda. A origem é o solo, os vegetais ou animais doentes (zoonose). A resposta forma granulomas e a evolução é crônica (slide 14)."]}, {"t": "Esporotricose (Sporothrix spp.)", "sub": ["Forma linfocutânea: úlcera primária e nódulos ascendentes que seguem o trajeto linfático, em rosário (slides 16 e 19).", "Ciclo sapronótico: solo, plantas e espinhos, com risco em agricultores e floristas. Ciclo zoonótico: gatos, com S. brasiliensis no Brasil, transmitido por arranhadura (slide 15).", "Dimorfismo térmico: 25 °C filamentoso (conídios em roseta); 37 °C levedura em charuto nos tecidos (slides 15 e 18).", "Diagnóstico: aspirado de lesão fechada ou biópsia. Cultura é o padrão-ouro e identifica a espécie (S. schenckii x S. brasiliensis). Exame direto tem baixa sensibilidade (slide 17).", "Esporotricose é de notificação compulsória semanal no Brasil (NT 20/2025). Aplica-se a visão One Health (slide 17)."]}, {"t": "Cromoblastomicose (fungos demáceos)", "sub": ["Agentes demáceos têm melanina na parede: Fonsecaea pedrosoi, F. monophora e Cladophialophora carrionii (slide 20).", "Forma tecidual: corpos muriformes ou escleróticos, células castanhas, arredondadas, septadas em mais de um plano (aspecto de moedas de cobre). Não brotam (slide 20).", "A lesão vira placa verrucosa: inflamação granulomatosa e microabscessos, hiperplasia pseudoepiteliomatosa e queratina em excesso. Pontos negros são eliminação transepidérmica e guiam a coleta (slide 21).", "Diagnóstico: raspado profundo ou biópsia, com corpos muriformes no direto ou na histopatologia. Predomina em membros inferiores (slide 25)."]}, {"t": "Micetoma (eumicetoma x actinomicetoma)", "sub": ["Micetoma é síndrome, não um fungo isolado. Tríade obrigatória: tumefação, fístulas e grãos (slides 22, 23 e 27).", "Eumicetoma: fungos verdadeiros, com hifas grossas (exemplo: Madurella mycetomatis). Actinomicetoma: bactérias filamentosas aeróbias (exemplos: Nocardia brasiliensis, Actinomadura madurae) (slides 22 e 27).", "Grão é microcolônia de hifas ou bactérias, cimentada e protegida das defesas. Não é esporo (slide 22).", "Evolução: implantação, tumefação granulomatosa e supurativa, drenagem por fístulas com grãos, invasão profunda por contiguidade (fáscia, músculo, osso) (slide 23)."]}]}, {"titulo": "3. Micoses sistêmicas e endêmicas", "pontos": [{"t": "Inalação e disseminação", "sub": ["Ambiente (solo) -> inalação -> foco pulmonar primário. Desfecho: contenção (cura), doença pulmonar ou disseminação hematogênica (slide 31).", "O pulmão é a entrada. Lesões de pele ou mucosa são quase sempre secundárias. Geografia e ocupação orientam a suspeita (slide 31).", "Não há transmissão humano a humano em geral (slide 31)."]}, {"t": "Temperatura e morfologia", "sub": ["A 25 °C a forma é filamentosa (bolor, conídios). A 37 °C, leveduras e esférulas nos tecidos (slide 32).", "Paracoccidioides e Histoplasma: bolores inalados que viram leveduras no tecido. Coccidioides, em regiões áridas, forma esférulas teciduais (slide 32)."]}, {"t": "Paracoccidioidomicose", "sub": ["Caso clássico: trabalhador rural de 52 anos, tosse crônica, perda de peso, infiltrados pulmonares e úlceras orais granulosas (slide 33).", "Agente: Paracoccidioides spp., endêmico na América Latina. Exposição ligada ao manejo do solo rural. Não há transmissão humana (slide 33).", "Duas formas clínicas: aguda ou subaguda (tipo juvenil), rápida, com linfonodos, fígado, baço e medula; crônica (tipo adulto), com pulmão em 90%, mucosas aerodigestivas e pele, com sequelas fibróticas (slide 34).", "Diagnóstico: roda de leme (levedura com múltiplos brotamentos) no exame direto e histopatologia, com cultura confirmatória. Amostras: escarro, LBA, raspado ou biópsia de úlceras orais (slide 35)."]}, {"t": "Histoplasmose", "sub": ["Solo com excretas de aves e morcegos. Microconídios aerossolizados são inalados (slide 37).", "Formas: assintomática ou autolimitada (maioria); pulmonar aguda (grande carga de inóculo); crônica (doença pulmonar prévia, como enfisema); disseminada (imunovulneráveis) (slide 37).", "Histoplasma capsulatum: pequenas leveduras intracelulares dentro de macrófagos alveolares. Exame direto e histopatologia, cultura lenta, sorologia e antígeno em soro e urina (slide 38)."]}, {"t": "Coccidioidomicose e comparação", "sub": ["Coccidioides: regiões áridas, desertos e poeira. Quadro pulmonar ou meningite. Esférulas com endósporos (slide 39).", "Paracoccidioidomicose, histoplasmose e coccidioidomicose se separam por geografia, exposição e morfologia tecidual (slide 39)."]}]}, {"titulo": "4. Micoses oportunistas", "pontos": [{"t": "Hospedeiro muda o desfecho", "sub": ["Mesma exposição, rotas opostas. Hospedeiro imunocompetente: colonização ou eliminação. Hospedeiro vulnerável: doença localizada ou invasão fatal (slide 41).", "Oportunismo descreve a relação fungo-hospedeiro, não a biologia do fungo (slide 41).", "Oportunista não é o último degrau de profundidade: a infecção corta barreiras da pele ao SNC. Rompem o equilíbrio cateteres, cirurgias, antibióticos e doenças de base (slide 42)."]}, {"t": "Perfil do paciente como pista", "sub": ["Barreira rompida (cirurgia, cateter, antibiótico): Candida. Defeito metabólico agudo (cetoacidose): Mucorales. Imunidade celular baixa (HIV): Cryptococcus ou Pneumocystis. Imunidade inata falha (neutropenia, corticoide, transplante): Aspergillus ou Mucorales. Alteração anatômica (cavidade prévia): aspergiloma (slide 43)."]}, {"t": "Candida", "sub": ["Colonização (pele, TGI, TGU). Isolar o fungo não significa doença. Gatilhos: antibióticos e alteração de pH ou umidade (slide 44).", "Desequilíbrio: candidíase mucocutânea. Quebra de barreira: invasão e candidemia, com gatilhos de cateter vascular, cirurgia abdominal e UTI (slide 44).", "Amostra: superfícies não estéreis (mucosa, urina de sonda, escarro) exigem contexto. Sítios estéreis (hemocultura, fluidos fechados, biópsia profunda) têm alto valor comprobatório (slide 45).", "Tubo germinativo identifica Candida albicans (slide 45)."]}, {"t": "Aspergillus", "sub": ["Quatro desfechos após inalação de conídio: alergia (ABPA: asma, IgE, tampões brônquicos); colonização de cavidade (aspergiloma, bola fúngica radiopaca); doença pulmonar crônica em pulmão com dano prévio; doença invasiva e disseminada em neutropenia ou imunossupressão (slide 46).", "Em neutropênico: tríade de leucemia ou neutropenia, febre persistente e dor pleurítica, com nódulos com sinal do halo na TC. Inalação, germinação, invasão e angioinvasão com trombose e infarto (slide 47).", "Investigação: LBA, cultura, galactomanana e histopatologia com hifas septadas. Morfologia sugestiva, não identificação definitiva (slide 47)."]}, {"t": "Cryptococcus", "sub": ["Entra pelo pulmão (pombos e excretas) e busca o SNC. Levedura arredondada que brota (slide 48).", "Cryptococcus neoformans: imunossuprimidos, HIV avançado, transplantados. Cryptococcus gattii ou attii: causa doença também em imunocompetentes (slide 48).", "Cápsula espessa de glucuronoxilomanano (GXM), antifagocitária e moduladora da resposta imune. Melanina a partir de catecolaminas protege contra estresse oxidativo. Cresce a 37 °C (slide 49).", "Causa principal: meningite criptocócica. Diagnóstico: punção lombar com LCR (tinta da China, antígeno criptocócico CrAg, cultura) (slide 49)."]}, {"t": "Pneumocystis e Mucorales", "sub": ["Pneumocystis jirovecii: pneumonia severa em HIV avançado ou pós-transplante. Tríade: febre, tosse seca e dispneia com hipoxemia. RX com vidro fosco bilateral. Não cresce em cultura rotineira. Diagnóstico com escarro induzido ou LBA, coloração de prata ou imunofluorescência, PCR e beta-D-glucana. Antigamente classificado como protozoário (slide 50).", "Mucormicose: cetoacidose (proliferação rinocerebral) e neutropenia profunda (envolvimento pulmonar). Rota: inalação ou inoculação, hifas, angioinvasão massiva, trombose e necrose. Emergência com dor facial, edema e necrose escura no palato ou nariz (slide 51).", "Histologia com morfologia sugestiva é o laboratório de emergência. Hifas largas, irregulares e pouco septadas (slide 51)."]}, {"t": "Associações de perfil e agente", "sub": ["Candida: quebra de barreira (cateter, cirurgia do TGI), com disseminação no sangue ou focos profundos. Aspergillus: neutropenia ou pulmão alterado, com doença pulmonar invasiva. Cryptococcus: comprometimento celular (HIV), com meningite subaguda (soro e líquor). Pneumocystis: HIV ou transplante, com pneumonia atípica (LBA). Mucorales: cetoacidose ou neutropenia, com necrose rinocerebral (biópsia) (slide 52).", "Não são regras biológicas exclusivas, e sim associações de alta prevalência clínica (slides 43 e 52)."]}]}, {"titulo": "5. Diagnóstico e amostra", "pontos": [{"t": "Qual método responde qual pergunta", "sub": ["Exame direto e histopatologia: o fungo está lá? Mostra estruturas, padrão de invasão e reação tecidual (slide 59).", "Cultura: qual é a espécie? Recupera o fungo vivo para identificação morfológica, com correlação clínica (slide 59).", "Antígeno e teste molecular: há DNA ou fragmentos? Decisivo em diagnóstico rápido de urgência (Cryptococcus, Histoplasma e Aspergillus invasivo) (slide 59).", "Sorologia: o hospedeiro reagiu? Útil na sistêmica endêmica (slide 59).", "Regra de ouro: exame direto negativo não exclui micose. Cultura positiva isolada pode ser contaminação laboratorial (slide 59)."]}, {"t": "Amostra conforme a síndrome", "sub": ["Síndrome superficial e anexos: raspado da borda ativa, pelo extraído ou fragmento ungueal (slide 58).", "Nódulo ou placa subcutânea, incluindo micetoma: aspirado, biópsia tecidual ou coleta de grãos. Nunca só exsudato superficial (slide 58).", "Síndrome pulmonar: escarro induzido, lavado broncoalveolar ou biópsia transbrônquica (slide 58).", "Síndrome disseminada ou invasiva: hemoculturas repetidas, LCR e soro para biomarcadores. Swab de superfície muitas vezes mostra colonização ou contaminação (slide 58)."]}, {"t": "Histoplasma, Cryptococcus e a amostra certa", "sub": ["Histoplasma: escarro, LBA, sangue, medula e tecidos. Pequenas leveduras intracelulares. Antígeno em soro e urina (slide 38).", "Pneumocystis: não cresce em cultura de rotina; exige amostra profunda (slide 50).", "Pela avaliação do caso, a amostra deve vir do local da doença (slide 58)."]}]}, {"titulo": "6. Revisão de casos e gabarito", "pontos": [{"t": "Casos e gabarito", "sub": ["A: gato e lesão circular descamativa: dermatofitose (Microsporum canis), raspado da borda, exame direto e cultura (slides 2, 3, 61).", "B: arranhadura e nódulos ascendentes: esporotricose (Sporothrix), aspirado ou biópsia, cultura (slides 4, 5, 61).", "C: síndrome pulmonar febril após limpar galinheiro em área endêmica: histoplasmose ou paracoccidioidomicose, com lavado broncoalveolar, escarro, soro ou biópsia (slide 61).", "D: transplante renal com neutropenia e nódulos pulmonares sem melhora: aspergilose ou candidíase ou criptococose, com sangue, líquor ou LBA (slide 61).", "Não existe padrão-ouro universal em micologia. A clínica orienta a técnica (slide 61)."]}, {"t": "Resumo dos agentes", "sub": ["Histoplasma capsulatum: dimorfismo; microconídios e macroconídios; leveduras intracelulares em macrófagos (slide 62).", "Paracoccidioides brasiliensis e P. lutzii: roda de leme; dimórficos endêmicos da América Latina (slide 62).", "Candida albicans: levedura, pseudo-hifa e hifa verdadeira; invade e dissemina (slide 62).", "Aspergillus fumigatus: conidióforo e conídios; hifas em V; invasão vascular e trombose (slide 62).", "Cryptococcus neoformans e gattii: cápsula antifagocitária; tropismo pelo SNC (slide 62).", "Pneumocystis jirovecii: formas tróficas e císticas; sem ergosterol; específico de humanos (slide 62).", "Mucorales (Rhizopus, Mucor, Lichtheimia): hifas largas, irregulares e pouco septadas; invasão vascular (slide 62)."]}]}], "glossario": [{"termo": "Sporothrix spp.", "tecnica": "Micose de implantação", "definicao": "Fungo dimórfico que causa esporotricose. Entra por trauma com espinho, madeira ou arranhadura de gato.", "slide": 5}, {"termo": "Sporothrix brasiliensis", "tecnica": "Agente zoonótico", "definicao": "Espécie predominante no Brasil, ligada a gatos e à transmissão por arranhadura.", "slide": 15}, {"termo": "Sporothrix schenckii", "tecnica": "Agente", "definicao": "Espécie do complexo Sporothrix, diferenciada de S. brasiliensis pela cultura.", "slide": 17}, {"termo": "Esporotricose linfocutânea", "tecnica": "Forma clínica", "definicao": "Úlcera primária com nódulos ascendentes que seguem o trajeto linfático em rosário.", "slide": 16}, {"termo": "Notificação compulsória semanal (NT 20/2025)", "tecnica": "Vigilância", "definicao": "Esporotricose humana é de notificação compulsória semanal no Brasil, pela NT 20/2025.", "slide": 17}, {"termo": "One Health (saúde única)", "tecnica": "Conceito", "definicao": "Controle integrado da saúde humana, animal e ambiental. Para esporotricose, trata o paciente, o gato e o ambiente.", "slide": 17}, {"termo": "Dermatófito zoofílico", "tecnica": "Classificação de dermatófitos", "definicao": "Dermatófito que parasita animais e raramente o homem. Microsporum canis é o exemplo do caso.", "slide": 3}, {"termo": "Microsporum canis", "tecnica": "Dermatófito", "definicao": "Dermatófito zoofílico causador de tinha do corpo e do couro cabeludo, adquirido de gatos e cães.", "slide": 3}, {"termo": "Tinea corporis (dermatofitose cutânea)", "tecnica": "Forma clínica", "definicao": "Lesão anular do corpo causada por dermatófito, com crescimento centrífugo e cura central.", "slide": 3}, {"termo": "KOH 10% (hidróxido de potássio)", "tecnica": "Exame direto", "definicao": "Clareia a amostra e revela hifas septadas de dermatófitos.", "slide": 3}, {"termo": "Fonsecaea pedrosoi", "tecnica": "Fungo demáceo", "definicao": "Fungo pigmentado causador de cromoblastomicose.", "slide": 20}, {"termo": "Cladophialophora carrionii", "tecnica": "Fungo demáceo", "definicao": "Fungo pigmentado causador de cromoblastomicose.", "slide": 20}, {"termo": "Corpos muriformes (escleróticos)", "tecnica": "Morfologia tecidual", "definicao": "Células castanhas, arredondadas e septadas, na cromoblastomicose. Lembram moedas de cobre.", "slide": 20}, {"termo": "Demáceo (melanina)", "tecnica": "Morfologia", "definicao": "Fungo com melanina na parede celular, o que lhe dá cor escura. Causa cromoblastomicose e feo-hifomicose.", "slide": 20}, {"termo": "Micetoma", "tecnica": "Síndrome", "definicao": "Síndrome crônica e destrutiva com tríade de tumefação, fístulas e grãos. Pode ser causada por fungos ou bactérias.", "slide": 22}, {"termo": "Eumicetoma", "tecnica": "Etiologia", "definicao": "Micetoma causado por fungos verdadeiros, com hifas grossas. Exemplo: Madurella mycetomatis.", "slide": 22}, {"termo": "Actinomicetoma", "tecnica": "Etiologia", "definicao": "Micetoma causado por bactérias filamentosas aeróbias, como Nocardia brasiliensis e Actinomadura madurae.", "slide": 22}, {"termo": "Madurella mycetomatis", "tecnica": "Agente", "definicao": "Fungo clássico de eumicetoma.", "slide": 22}, {"termo": "Nocardia brasiliensis", "tecnica": "Agente", "definicao": "Bactéria filamentosa aeróbia causadora de actinomicetoma.", "slide": 22}, {"termo": "Grão (micetoma)", "tecnica": "Morfologia tecidual", "definicao": "Microcolônia compacta de hifas ou bactérias, protegida das defesas. Não é esporo.", "slide": 22}, {"termo": "Tríade do micetoma", "tecnica": "Clínica", "definicao": "Tumefação, fístulas e grãos, nos tecidos pele, subcutâneo, fáscia e osso.", "slide": 27}, {"termo": "Paracoccidioides brasiliensis e P. lutzii", "tecnica": "Agente", "definicao": "Fungos dimórficos endêmicos da América Latina. Forma de roda de leme no tecido.", "slide": 33}, {"termo": "Roda de leme", "tecnica": "Morfologia", "definicao": "Levedura multibrotante, típica da paracoccidioidomicose no exame direto.", "slide": 35}, {"termo": "Forma crônica do adulto (paracoccidioidomicose)", "tecnica": "Forma clínica", "definicao": "Forma crônica, com pulmão em 90% dos casos, mucosas e pele. Deixa sequelas fibróticas.", "slide": 34}, {"termo": "Forma aguda ou subaguda (tipo juvenil)", "tecnica": "Forma clínica", "definicao": "Forma rápida com linfonodos, fígado, baço e medula. Tropismo pelo sistema mononuclear fagocitário.", "slide": 34}, {"termo": "Histoplasma capsulatum", "tecnica": "Agente", "definicao": "Fungo dimórfico com microconídios inalados. Leveduras pequenas, intracelulares em macrófagos.", "slide": 38}, {"termo": "Microconídio e macroconídio", "tecnica": "Morfologia", "definicao": "Esporos do Histoplasma no ambiente, na forma filamentosa a 25 °C.", "slide": 62}, {"termo": "Coccidioides immitis", "tecnica": "Agente", "definicao": "Fungo dimórfico de regiões áridas, que forma esférulas com endósporos nos tecidos.", "slide": 39}, {"termo": "Esférula com endósporos", "tecnica": "Morfologia tecidual", "definicao": "Estrutura de Coccidioides nos tecidos, com muitos endósporos internos.", "slide": 39}, {"termo": "Antígeno em soro e urina (histoplasmose)", "tecnica": "Diagnóstico", "definicao": "Detecção de antígeno do Histoplasma no soro e na urina, útil no diagnóstico de disseminação.", "slide": 38}, {"termo": "Lavado broncoalveolar (LBA)", "tecnica": "Amostra", "definicao": "Amostra do alvéolo colhida por broncoscopia. Usada em micoses pulmonares e em Pneumocystis.", "slide": 58}, {"termo": "Galactomanana", "tecnica": "Diagnóstico", "definicao": "Antígeno de Aspergillus no LBA ou no soro, usado no diagnóstico de aspergilose invasiva.", "slide": 47}, {"termo": "Sinal do halo", "tecnica": "Imagem", "definicao": "Nódulo pulmonar com halo de vidro fosco na TC, sugestivo de aspergilose invasiva em neutropênicos.", "slide": 47}, {"termo": "Aspergillus fumigatus", "tecnica": "Agente", "definicao": "Bolor ubíquo de conídios pequenos e hifas septadas. Causa ABPA, aspergiloma e aspergilose invasiva.", "slide": 46}, {"termo": "Aspergiloma (bola fúngica)", "tecnica": "Forma clínica", "definicao": "Colonização de cavidade pulmonar prévia, como após tuberculose. Radiopaca em forma de bola.", "slide": 46}, {"termo": "Angioinvasão", "tecnica": "Patogenia", "definicao": "Invasão de vasos pelas hifas, com trombose e infarto. Típica de Aspergillus e Mucorales.", "slide": 47}, {"termo": "Tubo germinativo", "tecnica": "Identificação", "definicao": "Teste que identifica Candida albicans pela formação de tubo germinativo.", "slide": 45}, {"termo": "Candidemia", "tecnica": "Forma clínica", "definicao": "Candida no sangue, causada por quebra de barreira, com disseminação para órgãos profundos.", "slide": 44}, {"termo": "Cryptococcus gattii", "tecnica": "Agente", "definicao": "Espécie que causa criptococose em imunodeprimidos e também em pessoas aparentemente imunocompetentes.", "slide": 48}, {"termo": "Glucuronoxilomanano (GXM)", "tecnica": "Cápsula", "definicao": "Principal componente da cápsula do Cryptococcus. Antifagocitário e modulador da resposta imune.", "slide": 48}, {"termo": "Melanina (criptococo)", "tecnica": "Patogenia", "definicao": "Pigmento produzido a partir de catecolaminas. Protege contra estresse oxidativo e ajuda na sobrevivência.", "slide": 49}, {"termo": "Tinta da China", "tecnica": "Diagnóstico", "definicao": "Coloração do LCR que mostra a cápsula do Cryptococcus como halo claro.", "slide": 49}, {"termo": "CrAg (antígeno criptocócico)", "tecnica": "Diagnóstico", "definicao": "Teste de antígeno do Cryptococcus no LCR ou no soro, usado no diagnóstico de meningite criptocócica.", "slide": 49}, {"termo": "Pneumocystis jirovecii", "tecnica": "Agente", "definicao": "Fungo atípico, antes classificado como protozoário. Causa pneumonia severa em HIV avançado e pós-transplante.", "slide": 50}, {"termo": "Beta-D-glucana", "tecnica": "Diagnóstico", "definicao": "Polissacarídeo da parede fúngica, dosado no soro para apoio diagnóstico em Pneumocystis.", "slide": 50}, {"termo": "Coloração de prata (Grocott)", "tecnica": "Diagnóstico", "definicao": "Coloração de prata usada para visualizar Pneumocystis em amostras de LBA ou escarro.", "slide": 50}, {"termo": "Mucormicose (Mucorales)", "tecnica": "Síndrome", "definicao": "Infecção por Mucorales, com cetoacidose ou neutropenia. Necrose rinocerebral e angioinvasão.", "slide": 51}, {"termo": "Cetoacidose diabética", "tecnica": "Fator de risco", "definicao": "Defeito metabólico agudo associado a mucormicose, por proliferação rinocerebral.", "slide": 51}, {"termo": "Candida como comensal e invasora", "tecnica": "Conceito", "definicao": "Candida pode ser habitante, causar doença de mucosa ou invadir, conforme a barreira e a imunidade.", "slide": 44}, {"termo": "Aspergilose broncopulmonar alérgica (ABPA)", "tecnica": "Forma clínica", "definicao": "Resposta alérgica exagerada a Aspergillus, com IgE, tampões brônquicos e asma.", "slide": 46}, {"termo": "Doença definidora de AIDS (Cryptococcus, Pneumocystis)", "tecnica": "Epidemiologia", "definicao": "Micoses que definem o estágio de AIDS, como criptococose e pneumocistose.", "slide": 52}, {"termo": "Classificação clínica das micoses (Odds)", "tecnica": "Classificação", "definicao": "Classificação de Odds e colaboradores, de 1992, usada como base da aula.", "slide": 11}, {"termo": "Feo-hifomicose subcutânea", "tecnica": "Micose de implantação", "definicao": "Micose de implantação por fungo demáceo, com cistos inflamatórios.", "slide": 28}, {"termo": "Lacaziose", "tecnica": "Micose de implantação", "definicao": "Micose de implantação em nota da aula, causada por Lacazia loboi.", "slide": 28}], "fontes": ["Aula 3, Classificação clínica das micoses II (pdf/natalia/aulas/aula-03.pdf, slides 1 a 62, em imagens)", "Base complementar: Murray, Medical Microbiology (micologia médica); NT 20/2025 (esporotricose)"], "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um trabalhador rural tem uma placa verrucosa que cresce lentamente na perna, após um ferimento com lasca de madeira há 12 anos. Pela aula, qual é a porta de entrada e qual é o diagnóstico mais provável?", "alternativas": ["Inoculação traumática; cromoblastomicose, com corpos muriformes", "Inalação; histoplasmose, com leveduras intracelulares", "Contato direto; dermatofitose, com hifas septadas", "Origem endógena; candidíase, com pseudo-hifas", "Quebra de barreira por cateter; mucormicose, com angioinvasão e necrose rinocerebral"], "gabarito": "A", "justificativa": "A inoculação traumática por lasca de madeira, com placa verrucosa de crescimento lento, sugere cromoblastomicose. O exame mostra corpos muriformes (Aula 3, slides 24 e 25).", "tecnica": "Micose de implantação", "slide": 25, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Uma lesão de inoculação no dedo de um jardineiro é seguida de nódulos endurecidos ascendentes no braço. Pela aula, qual é a forma clínica, qual é o agente e qual amostra tem maior valor?", "alternativas": ["Esporotricose linfocutânea; Sporothrix spp.; aspirado ou biópsia", "Micetoma; Madurella mycetomatis; exsudato superficial", "Cromoblastomicose; Fonsecaea pedrosoi; swab de superfície, com placa verrucosa", "Paracoccidioidomicose; Paracoccidioides; urina", "Histoplasmose; Histoplasma capsulatum; hemocultura apenas"], "gabarito": "A", "justificativa": "A esporotricose linfocutânea segue o trajeto linfático em rosário. A cultura é o padrão-ouro, e a melhor amostra é aspirado ou biópsia, não swab superficial (Aula 3, slides 16 e 17).", "tecnica": "Esporotricose", "slide": 17, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Pela aula, qual diferença separa a esporotricose do micetoma quanto à tríade clínica e à natureza do agente, nos casos de tumefação e fístulas?", "alternativas": ["Micetoma é causado sempre por Sporothrix; esporotricose é síndrome com grãos e fístulas", "Os dois são causados pelo mesmo gênero de fungo, sem diferença de tríade", "Esporotricose tem tríade de tumefação, fístulas e grãos; micetoma é uma forma sistêmica endêmica, transmitida por inalação pulmonar de esporos do solo", "Micetoma é síndrome (tumefação, fístulas e grãos) causada por fungos ou bactérias; esporotricose é micose dimórfica por inoculação", "Micetoma é de notificação compulsória semanal; esporotricose não é notificada"], "gabarito": "D", "justificativa": "Micetoma é síndrome, não um agente único. Tem tríade de tumefação, fístulas e grãos, com eumicetoma (fungos) ou actinomicetoma (bactérias). A esporotricose é dimórfica, por Sporothrix (Aula 3, slides 22, 27 e 28).", "tecnica": "Micetoma e esporotricose", "slide": 27, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um paciente com neutropenia após quimioterapia tem febre persistente e dor pleurítica, com nódulos pulmonares com sinal do halo na TC. Pela aula, qual é o agente mais provável e qual é a sequência de invasão?", "alternativas": ["Histoplasma, com inalação, macrófago alveolar e leveduras intracelulares", "Coccidioides, com esférulas nas meninges e disseminação linfática", "Aspergillus, com inalação, germinação em hifa e angioinvasão", "Paracoccidioides, com úlcera oral e linfonodos ascendentes", "Candida, com aftas orais e placas na mucosa sem disseminação"], "gabarito": "C", "justificativa": "Neutropênico com nódulos e sinal do halo sugere aspergilose invasiva. A sequência é inalação, germinação, invasão tecidual e angioinvasão (Aula 3, slide 47).", "tecnica": "Aspergilose invasiva", "slide": 47, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um paciente com HIV avançado tem cefaleia arrastada e o LCR é submetido a coloração de tinta da China e pesquisa de antígeno. Pela aula, qual é o agente e qual é a característica que permite a coloração?", "alternativas": ["Pneumocystis jirovecii; cisto com parede de quitina visível pela tinta, em pneumonia intersticial", "Aspergillus fumigatus; hifa septada corada por tinta da China", "Histoplasma capsulatum; microconídio com melanina", "Cryptococcus neoformans; cápsula que aparece como halo na tinta da China", "Candida albicans; pseudo-hifa com constrições coradas"], "gabarito": "D", "justificativa": "Cryptococcus neoformans tem cápsula de GXM. Na tinta da China, a cápsula aparece como halo claro. O tropismo pelo SNC explica a meningite criptocócica (Aula 3, slides 48 e 49).", "tecnica": "Cryptococcus", "slide": 49, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um paciente com transplante pulmonar tem tosse seca, dispneia com hipoxemia e RX com vidro fosco bilateral. Pela aula, qual é o agente e por que o cultivo de rotina costuma não detectá-lo?", "alternativas": ["Histoplasma capsulatum; cresce rapidamente em cultura de escarro", "Candida albicans; é detectado pelo exame direto da urina", "Pneumocystis jirovecii; não cresce em cultura rotineira", "Dermatófito; só cresce no couro cabeludo", "Mucorales; cresce em 24 horas em qualquer meio"], "gabarito": "C", "justificativa": "Pneumocystis jirovecii causa pneumonia severa em HIV avançado ou pós-transplante. Não cresce em cultura de rotina, por isso exige escarro induzido ou LBA, com coloração de prata e PCR (Aula 3, slide 50).", "tecnica": "Pneumocystis", "slide": 50, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um paciente diabético em cetoacidose tem edema palpebral rápido e placa necrótica escura no palato. Pela aula, qual é a suspeita e qual é a via prioritária de diagnóstico?", "alternativas": ["Esporotricose; cultura de aspirado, com espera de duas semanas", "Dermatofitose; exame de lâmpada de Wood", "Paracoccidioidomicose; roda de leme no escarro, com sorologia apenas", "Criptococose; tinta da China em urina", "Mucormicose; histologia com morfologia sugestiva"], "gabarito": "E", "justificativa": "A cetoacidose favorece a mucormicose, com necrose rinocerebral e angioinvasão. Como é emergência, a histologia com morfologia sugestiva é prioritária (Aula 3, slide 51).", "tecnica": "Mucormicose", "slide": 51, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Pela aula, qual é a diferença entre as formas de paracoccidioidomicose aguda e crônica quanto ao órgão de maior comprometimento e ao sistema afetado?", "alternativas": ["Aguda tem pulmão em 90% e sequelas fibróticas; crônica tem linfonodos massivos, fígado e medula, sem mucosas", "Aguda e crônica têm o mesmo órgão de maior comprometimento, sem diferença de sistema", "Aguda é restrita à pele e crônica é restrita ao SNC", "Crônica tem tropismo pelo fígado e baço; aguda, pela mucosa oral apenas", "Aguda (juvenil): linfonodos, fígado, baço e medula; crônica (adulto): pulmão em 90% e mucosas"], "gabarito": "E", "justificativa": "Na forma aguda ou subaguda (juvenil), há tropismo pelo sistema mononuclear fagocitário. Na crônica (adulto), predominam pulmão (90%), mucosas e pele, com sequelas fibróticas (Aula 3, slide 34).", "tecnica": "Paracoccidioidomicose", "slide": 34, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um agricultor limpou um galinheiro antigo em área endêmica e teve síndrome pulmonar aguda febril duas semanas depois. Pela aula, qual é o agente mais provável e qual é a amostra de maior valor?", "alternativas": ["Aspergillus fumigatus; hemocultura com hifas septadas, sem exame de imagem", "Histoplasma capsulatum; lavado broncoalveolar, escarro, soro ou biópsia", "Candida albicans; swab de orofaringe", "Sporothrix brasiliensis; aspirado de nódulo cutâneo", "Mucorales; exsudato nasal"], "gabarito": "B", "justificativa": "Limpeza de galinheiro em área endêmica sugere histoplasmose pulmonar aguda, por inalação de microconídios de excretas de aves. Amostras pulmonares e soro são as mais úteis (Aula 3, slides 37 e 38).", "tecnica": "Histoplasmose", "slide": 37, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Pela aula, qual é a relação entre a exposição, a porta de entrada e o agente em um caso de dermatofitose por gato, em comparação com esporotricose por arranhadura?", "alternativas": ["Dermatofitose: trauma com espinho, Sporothrix; esporotricose: contato direto com fômites, Microsporum canis", "Ambas têm inalação como porta de entrada, com Histoplasma", "Ambas dependem de cateter, com Candida", "Dermatofitose: inalação de conídios; esporotricose: contato com fômites e Trichophyton", "Dermatofitose: contato direto com pele íntegra, Microsporum canis; esporotricose: arranhadura e Sporothrix"], "gabarito": "E", "justificativa": "A matriz da aula separa exposição a gatos: contato direto com pele íntegra gera dermatofitose (Microsporum canis, tinea corporis); arranhadura, com trauma, gera esporotricose (Sporothrix) (Aula 3, slides 10 e 13).", "tecnica": "Porta de entrada", "slide": 10, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Pela aula, por que um resultado de exame direto negativo não basta para excluir uma micose, e por que uma cultura positiva isolada pode não significar doença?", "alternativas": ["O exame direto sempre é positivo, e a cultura é sempre contaminada", "Micoses são doenças bacterianas, e o exame direto não detecta bactérias", "Culturas positivas excluem micoses, e exames diretos negativos confirmam doença", "O exame direto tem baixa sensibilidade em algumas amostras; a cultura pode ser contaminação", "A amostra não importa, porque todas as micoses se diagnosticam pelo exame de sangue e pela sorologia"], "gabarito": "D", "justificativa": "Exame direto negativo não exclui micose, pois há baixa sensibilidade em algumas amostras. Cultura positiva isolada pode significar contaminação laboratorial. A clínica e a amostra orientam a interpretação (Aula 3, slide 59).", "tecnica": "Interpretação diagnóstica", "slide": 59, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Pela aula, qual amostra é mais adequada para uma síndrome pulmonar e qual é a regra de amostra para micetoma?", "alternativas": ["Swab de superfície; grãos de exsudato superficial, com raspado de unha e de pele íntegra", "Urina de 24 horas; biópsia de unha", "Escarro induzido, LBA ou biópsia transbrônquica; grãos ou aspirado profundo", "Sangue periférico; raspado de borda ativa", "Lágrima; fragmento ungueal"], "gabarito": "C", "justificativa": "Para síndrome pulmonar, a aula cita escarro induzido, LBA ou biópsia transbrônquica. Para micetoma, grãos íntegros ou aspirado profundo, não exsudato superficial (Aula 3, slide 58).", "tecnica": "Amostra por síndrome", "slide": 58, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Pela aula, quais são as três perguntas que organizam a classificação clínica de uma micose, e qual é o pilar relacionado à condição do paciente?", "alternativas": ["Espécie, cor da colônia e temperatura de cultura; o pilar do hospedeiro é o peso", "Porta de entrada, tecido de destino e condição do hospedeiro", "Idade, sexo e ocupação; o pilar do hospedeiro é o ambiente", "Antígeno, anticorpo e cultura; o pilar do hospedeiro é o exame de imagem", "Tratamento, duração e custo; o pilar do hospedeiro é a alergia a medicamentos"], "gabarito": "B", "justificativa": "A classificação se apoia em entrada (porta), destino (tecido) e hospedeiro (defesa preservada, barreira rompida ou neutropenia). A combinação das três respostas define a classificação (Aula 3, slide 11).", "tecnica": "Classificação clínica", "slide": 11, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Um paciente com lesão oral granulosa e exposição rural tem infiltrados pulmonares. Pela aula, por que a lesão oral não deve ser considerada a porta de entrada, e qual é a porta provável?", "alternativas": ["A lesão oral é a porta de entrada, pois a boca é o local de inoculação traumática", "A lesão oral é secundária; a porta é a inalação no pulmão", "A porta é a pele da mão, por arranhadura de gato", "A porta é o cateter venoso, por candidíase oral", "A porta é o contato com animais, por dermatofitose oral"], "gabarito": "B", "justificativa": "Na paracoccidioidomicose, a lesão visível (mucosa) quase nunca indica a porta de entrada. A entrada é pulmonar, por inalação, com disseminação para mucosa e linfonodos (Aula 3, slides 33 e 29).", "tecnica": "Paracoccidioidomicose", "slide": 33, "pdf": "pdf/natalia/aulas/aula-03.pdf"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Em um paciente com placa verrucosa crônica, qual amostra e qual achado microscópico orientam o diagnóstico de cromoblastomicose?", "alternativas": ["Raspado profundo ou biópsia, com corpos muriformes", "Swab de superfície, com hifas hialinas", "Urina, com leveduras em roda de leme", "Sangue, com microconídios intracelulares", "Lavado broncoalveolar, com cápsula de GXM, típico de pneumonia por Pneumocystis"], "gabarito": "A", "justificativa": "Cromoblastomicose tem corpos muriformes no tecido. O diagnóstico se faz por raspado profundo, focado nos pontos escuros, ou biópsia (Aula 3, slides 20 e 25).", "tecnica": "Cromoblastomicose", "slide": 25, "pdf": "pdf/natalia/aulas/aula-03.pdf"}], "id": "natalia-aula-03", "voltar": {"href": "#/agressao/natalia", "texto": "Professora Natália"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["natalia-aula-04"] = {"titulo": "Aula 4", "subtitulo": "Microbiologia básica: microbiota, colonização, sítios estéreis e meningite meningocócica", "pdf": "pdf/natalia/aulas/aula-04.pdf", "abas": ["resumo", "glossario", "quiz", "pdf"], "resumo": [{"titulo": "1. Microbiota: o que é normal e o que vira doença", "pontos": [{"t": "Pele", "sub": ["Microbiota: Staphylococcus epidermidis e outros estafilococos coagulase-negativos, Corynebacterium spp. e Cutibacterium acnes. S. aureus pode colonizar parte da população (slide 1).", "Encontrar S. epidermidis não significa infecção. Pode ser contaminante, mas também pode ser patógeno, sobretudo no sangue (slide 2).", "Sequência do raciocínio: microbiota → contaminante potencial → patógeno (slide 2)."]}, {"t": "Nasofaringe", "sub": ["Não é estéril. Tem estreptococos, Neisseria comensais e Corynebacterium (slide 3).", "Potenciais patógenos colonizam sem causar doença: Streptococcus pneumoniae, Neisseria meningitidis e Haemophilus influenzae (slides 3 e 4).", "Colonização não é invasão. Para haver doença, a bactéria precisa vencer as barreiras locais, invadir tecidos, cair na circulação e, em alguns casos, atingir as meninges (slides 5 e 6)."]}, {"t": "Intestino", "sub": ["Um dos locais mais densamente colonizados: Enterobacterales, Enterococcus e Bacteroides, com muitos anaeróbios (slide 8).", "Escherichia coli é comensal, mas linhagens com fatores de virulência causam doença intestinal. A E. coli da microbiota pode chegar ao trato urinário e causar ITU (slide 9)."]}, {"t": "Trato genital", "sub": ["Lactobacillus spp. é a bactéria associada à microbiota vaginal saudável. Mantém ambiente vaginal ácido e dificulta a proliferação de outros micro-organismos (slides 10 a 13)."]}]}, {"titulo": "2. Sítios estéreis e significado do achado", "pontos": [{"t": "O local dá o significado", "sub": ["Sítios estéreis: sangue, LCR, líquido sinovial e líquido pleural (slide 14).", "O mesmo micro-organismo tem significados diferentes: S. pneumoniae na nasofaringe pode ser colonização. No LCR de paciente compatível é achado de enorme importância e fortemente indicativo de infecção do SNC (slide 16).", "O significado de um micro-organismo depende do sítio onde é encontrado (slide 16)."]}]}, {"titulo": "3. Caso clínico: síndrome meníngea em jovem", "pontos": [{"t": "Apresentação", "sub": ["Jovem de 19 anos, previamente saudável, com início súbito de febre alta, cefaleia, vômitos e rigidez de nuca. Petéquias em membros inferiores (slide 17).", "Síndrome: meníngea, com forte suspeita de meningite aguda. Petéquias lembram Neisseria meningitidis (slides 18 a 20)."]}, {"t": "Diagnósticos diferenciais", "sub": ["Hipótese principal: N. meningitidis. Diferenciais: Streptococcus pneumoniae, Haemophilus influenzae (conforme contexto e vacinação), meningites virais e outros agentes conforme idade, imunidade e epidemiologia (slide 21).", "Adulto jovem com petéquias ou púrpura aumenta a suspeita de doença meningocócica, mas não substitui a investigação (slide 21)."]}, {"t": "Amostra e exames", "sub": ["LCR, quando a punção lombar é indicada e segura, e hemoculturas em suspeita de meningite bacteriana (slide 22).", "Laboratório no LCR: aspecto, celularidade, glicose, proteína, bacterioscopia (Gram), cultura e métodos moleculares quando indicados (slide 22).", "Exemplo: LCR turvo, neutrófilos predominantes, proteína elevada, glicose reduzida e diplococos Gram-negativos. Hipótese de meningococo fica muito mais forte (slides 22 a 24)."]}]}, {"titulo": "4. Fisiopatologia da meningite meningocócica", "pontos": [{"t": "LOS e endotoxina", "sub": ["N. meningitidis é Gram-negativo. A membrana externa tem LOS (lipooligossacarídeo), equivalente funcional ao LPS, com forte atividade endotóxica (slide 25).", "Ativação de células da imunidade inata e liberação de mediadores. Ativação do endotélio e da coagulação (slide 25).", "Nos casos graves, CIVD: microtrombos disseminados, consumo de plaquetas e fatores de coagulação (slide 25).", "Sangue extravasa para a pele: petéquias → púrpura → áreas hemorrágicas. Nos casos fulminantes, necrose e púrpura fulminante (slide 25)."]}]}, {"titulo": "5. Ferramentas de raciocínio", "pontos": [{"t": "Perguntas para cada achado", "sub": ["O micro-organismo costuma colonizar esse local? Pode ser contaminante? É compatível com a síndrome? (slides 1 e 2).", "Qual amostra é adequada, qual método, e o que se espera encontrar (slides 17 a 25)."]}]}, {"titulo": "6. Colonização, adesão e estabelecimento da infecção", "pontos": [{"t": "Termos", "sub": ["Contaminação: presença do micro-organismo sem multiplicação; mero contato.", "Colonização: multiplicação estável, sem dano nem resposta do hospedeiro; é o estado da microbiota normal.", "Infecção: invasão com multiplicação, resposta imune e dano tecidual."]}, {"t": "Como a microbiota normal vira patogênica", "sub": ["Ruptura de barreira: o S. aureus da pele ganha a corrente sanguínea por cateter ou ferida.", "Translocação de sítio: a E. coli do cólon alcança a uretra e ascende ao trato urinário (mesmo organismo, lugar errado).", "Queda da imunidade: E. faecalis, comensal intestinal, causa endocardite ou infecção hospitalar em imunossuprimidos.", "Conceito operacional: patógeno oportunista. A virulência está também na relação com o hospedeiro."]}]}, {"titulo": "7. Barreiras do hospedeiro e estratégias bacterianas", "pontos": [{"t": "Tabela-resumo", "sub": ["Pele íntegra (queratina, dessecação, pH ácido, microbiota competidora) → vencida por trauma, cateter, queimadura, picada de artrópode.", "Acidez gástrica (pH ~2) → urease do H. pylori gera amônia e neutraliza o pH ao redor; outros compensam com dose infectante alta.", "Escada mucociliar (muco aprisiona, cílios expelem) → toxina pertussis paralisa os cílios; IgA protease cliva o anticorpo de mucosa; cápsula resiste à depuração.", "Fluxo urinário (lavagem mecânica contínua) → fímbrias e adesinas ancoram ao urotélio; flagelo permite ascensão.", "Complemento e fagócitos → cápsula, proteína M, proteína A e catalase (ver aula 5)."]}]}, {"titulo": "8. Escherichia coli: a mesma espécie, patogenicidades distintas", "pontos": [{"t": "Por que cepas comensais e patogênicas diferem", "sub": ["O genoma central é o mesmo; o que muda são ilhas de patogenicidade, plasmídeos e fagos adquiridos horizontalmente."]}, {"t": "Patotipos", "sub": ["ETEC: enterotoxinas termolábil (LT) e termoestável (ST) → secreção de água e eletrólitos; diarreia aquosa, \"diarreia do viajante\". Adesinas: fatores de colonização (CFA).", "EPEC: lesão A/E (attaching and effacing), destrói as microvilosidades; diarreia infantil persistente. Adesinas: BFP e intimina.", "EHEC / STEC (O157:H7): toxina Shiga, inibe a síntese proteica e lesa o endotélio; colite hemorrágica e síndrome hemolítico-urêmica. Antibiótico aumenta o risco de SHU.", "EAEC: agregação em \"tijolos empilhados\" (stacked-brick) sobre o epitélio; diarreia persistente, aquosa, com vômitos e desidratação; adesinas AAF.", "EIEC: invade e se multiplica no enterócito; disenteria, semelhante à shigelose.", "UPEC (extraintestinal): pili P e adesinas para o urotélio; hemolisina HlyA; cistite e pielonefrite; principal agente de ITU.", "MNEC (extraintestinal): cápsula K1, que mimetiza antígeno do hospedeiro; meningite neonatal."]}]}, {"titulo": "9. Nichos ambientais e adaptações metabólicas", "pontos": [{"t": "Estômago, trato urinário e tecidos com pouco oxigênio", "sub": ["Estômago: pH muito ácido. H. pylori sobrevive pela urease (alcaliniza o microambiente) e pela motilidade em espiral, que o leva ao muco próximo ao epitélio, onde o pH é mais alto.", "Trato urinário: alta osmolaridade, ureia e fluxo constante. Adesinas resistem ao arraste; a urease do Proteus alcaliniza a urina e precipita cálculos de estruvita.", "Tecidos profundos mal oxigenados (ferida com tecido desvitalizado, abscesso, isquemia): favorecem anaeróbios, que não têm catalase nem superóxido-dismutase (daí a intolerância ao oxigênio) e obtêm energia por fermentação. É a lógica do desbridamento cirúrgico."]}]}], "glossario": [{"termo": "Microbiota residente", "tecnica": "Conceito", "definicao": "Micro-organismos que vivem normalmente no corpo, sem causar doença em condições habituais.", "slide": 2}, {"termo": "Contaminante", "tecnica": "Conceito", "definicao": "Micro-organismo introduzido na coleta, no transporte ou no processamento, sem papel na doença.", "slide": 2}, {"termo": "Colonização", "tecnica": "Conceito", "definicao": "Presença de micro-organismo sem manifestações clínicas. Colonização não é invasão.", "slide": 5}, {"termo": "Infecção", "tecnica": "Conceito", "definicao": "Interação patogênica do micro-organismo com manifestações clínicas ou lesão tecidual.", "slide": 6}, {"termo": "Staphylococcus epidermidis", "tecnica": "Microbiota da pele", "definicao": "Estafilococo coagulase-negativo da pele. Pode ser contaminante, mas também causa infecção de dispositivos e sangue.", "slide": 1}, {"termo": "Cutibacterium acnes", "tecnica": "Microbiota da pele", "definicao": "Bacilo da microbiota cutânea, em especial na região sebácea.", "slide": 1}, {"termo": "Corynebacterium spp.", "tecnica": "Microbiota", "definicao": "Bacilos Gram-positivos da pele e da nasofaringe, em geral comensais.", "slide": 1}, {"termo": "Enterobacterales", "tecnica": "Microbiota intestinal", "definicao": "Ordem de bacilos Gram-negativos fermentadores do intestino, incluindo E. coli e Klebsiella.", "slide": 8}, {"termo": "Bacteroides", "tecnica": "Microbiota intestinal", "definicao": "Bacilos anaeróbios estritos dominantes no intestino grosso.", "slide": 8}, {"termo": "Lactobacillus spp.", "tecnica": "Microbiota vaginal", "definicao": "Bacilos Gram-positivos que mantêm o ambiente vaginal ácido e limitam outros micro-organismos.", "slide": 11}, {"termo": "Streptococcus pneumoniae", "tecnica": "Agente", "definicao": "Diplococo Gram-positivo encapsulado, colonizador da nasofaringe e causa de pneumonia, otite, sinusite e meningite.", "slide": 4}, {"termo": "Neisseria meningitidis", "tecnica": "Agente", "definicao": "Diplococo Gram-negativo, colonizador da nasofaringe, causa de meningite e meningococcemia.", "slide": 4}, {"termo": "Haemophilus influenzae", "tecnica": "Agente", "definicao": "Cocobacilo Gram-negativo exigente, colonizador da nasofaringe, causa de meningite em não vacinados.", "slide": 4}, {"termo": "Sítio estéril", "tecnica": "Conceito", "definicao": "Local normalmente livre de micro-organismos, como sangue, LCR, líquido sinovial e pleural. Achado nesses locais tem significado clínico forte.", "slide": 14}, {"termo": "LCR (líquido cefalorraquidiano)", "tecnica": "Amostra", "definicao": "Líquido da punção lombar. Avaliado por aspecto, celularidade, glicose, proteína, Gram e cultura.", "slide": 22}, {"termo": "Punção lombar", "tecnica": "Procedimento", "definicao": "Coleta de LCR, indicada na suspeita de meningite quando é clinicamente segura.", "slide": 22}, {"termo": "Coloração de Gram (epônimo: Hans Christian Gram)", "tecnica": "Método", "definicao": "Coloração diferencial que separa bactérias Gram-positivas e Gram-negativas pela parede celular.", "slide": 22}, {"termo": "Gram-negativo", "tecnica": "Conceito", "definicao": "Bactéria com parede fina e membrana externa com LPS ou LOS, que tem atividade endotóxica.", "slide": 25}, {"termo": "LOS (lipooligossacarídeo)", "tecnica": "Endotoxina", "definicao": "Equivalente do LPS em N. meningitidis e H. influenzae. Ativa a imunidade inata e causa inflamação intensa.", "slide": 25}, {"termo": "CIVD (coagulação intravascular disseminada)", "tecnica": "Complicação", "definicao": "Ativação difusa da coagulação, com microtrombos e consumo de plaquetas e fatores. Causa hemorragia e necrose.", "slide": 25}, {"termo": "Petéquia", "tecnica": "Achado clínico", "definicao": "Pequena hemorragia puntiforme na pele, que pode evoluir para púrpura. Típica de meningococcemia.", "slide": 25}, {"termo": "Púrpura fulminante", "tecnica": "Achado clínico", "definicao": "Áreas hemorrágicas extensas e necrose, em casos graves de meningococcemia.", "slide": 25}, {"termo": "Meningite meningocócica", "tecnica": "Doença", "definicao": "Meningite causada por N. meningitidis, com petéquias em adulto jovem e alta suspeita clínica.", "slide": 21}], "fontes": ["Aula 4, Agressão e defesa II: microbiologia básica (pdf/natalia/aulas/aula-04.pdf, slides 1 a 25)", "Base complementar: Murray, Medical Microbiology (caps. de Neisseria e Haemophilus)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Uma bactéria é isolada de uma amostra colhida na pele, sem quadro clínico. Pela aula, qual termo descreve melhor essa situação?", "alternativas": ["Infecção, porque toda bactéria isolada de amostra clínica representa invasão tecidual com dano", "Contaminação, porque toda bactéria isolada de amostra clínica é sempre introduzida na coleta", "Colonização, com multiplicação estável sem dano nem resposta do hospedeiro", "Patogenicidade, porque a virulência é suficiente para classificar o micro-organismo como causador", "Toxigenicidade, porque a presença de toxina na amostra define a doença sem necessidade de quadro"], "gabarito": "C", "justificativa": "Colonização é multiplicação estável sem dano nem resposta do hospedeiro, que é o estado da microbiota normal. Contaminação é mero contato; infecção exige multiplicação, resposta imune e dano (resumo: Microbiota, colonização e infecção).", "tecnica": "Colonização × contaminação × infecção", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um S. aureus da pele chega à corrente sanguínea por um cateter. Qual dos três caminhos de patogenicidade da microbiota normal descreve essa situação?", "alternativas": ["Translocação de sítio, com a bactéria mudando de sítio dentro do mesmo tecido sadio", "Queda da imunidade, com comensal que causa doença apenas em imunossuprimidos de forma sistêmica", "Variação antigênica, com troca de antígenos de superfície que escapa do anticorpo já produzido", "Ruptura de barreira, com a bactéria comensal da pele ganhando acesso ao sangue", "Mimetismo molecular, com anticorpo contra a bactéria reagindo com antígeno próprio do cateter"], "gabarito": "D", "justificativa": "Ruptura de barreira: o S. aureus da pele ganha a corrente sanguínea por cateter ou ferida. Translocação de sítio é a E. coli do cólon indo à uretra; queda da imunidade é o E. faecalis em imunossuprimidos (resumo: Microbiota, colonização).", "tecnica": "Caminhos de patogenicidade", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Por que a E. coli do cólon, mesmo organismo, causa infecção urinária quando chega à uretra?", "alternativas": ["Ocorre mutação do genoma, que transforma a E. coli comensal em outra espécie patogênica", "Ocorre perda da cápsula, que torna a bactéria visível ao complemento e a leva à fagocitose", "Ocorre aquisição de toxina termolábil, que é transmitida por plasmídeo à E. coli uretral", "Ocorre queda do pH urinário, que transforma a E. coli em espécie esporulada e resistente", "Ocorre translocação de sítio: o mesmo organismo, em lugar errado, ascende à bexiga"], "gabarito": "E", "justificativa": "Translocação de sítio: a E. coli do cólon alcança a uretra e ascende ao trato urinário. É o mesmo organismo, em lugar errado (resumo: Microbiota, colonização).", "tecnica": "Translocação de sítio", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um patógeno do trato digestivo causa diarreia aquosa por enterotoxinas termolábil e termoestável. Qual patotipo de E. coli se encaixa, e qual é a clínica típica?", "alternativas": ["ETEC; diarreia aquosa, a chamada diarreia do viajante", "EPEC; diarreia infantil persistente, com destruição das microvilosidades por lesão A/E", "EHEC; colite hemorrágica e síndrome hemolítico-urêmica, com toxina Shiga", "EIEC; disenteria, com invasão e multiplicação dentro do enterócito", "EAEC; diarreia persistente, com agregação em padrão de tijolos empilhados"], "gabarito": "A", "justificativa": "ETEC produz enterotoxinas LT e ST, que levam à secreção de água e eletrólitos: diarreia aquosa, a diarreia do viajante (resumo: Microbiota, patotipos da E. coli).", "tecnica": "ETEC", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um paciente tem colite hemorrágica após ingestão de carne mal cozida, e a equipe pergunta se antibiótico deve ser usado. Qual é a orientação mais coerente com o patotipo?", "alternativas": ["Usar antibiótico de largo espectro, porque reduz a toxina Shiga circulante em todos os patotipos", "Usar antibiótico sempre, porque a toxina Shiga é sensível a qualquer antimicrobiano em dose plena", "Usar corticoide em dose alta, porque a toxina Shiga é um antígeno que causa hipersensibilidade tipo I", "Usar anti-H1, porque a colite hemorrágica por STEC é mediada por histamina liberada pelos mastócitos", "Evitar antibiótico, porque aumenta o risco de síndrome hemolítico-urêmica no caso de STEC"], "gabarito": "E", "justificativa": "EHEC/STEC: a toxina Shiga inibe a síntese proteica e lesa o endotélio. Antibiótico aumenta o risco de SHU; por isso não é usado de rotina nesse caso (resumo: Microbiota, patotipos da E. coli).", "tecnica": "STEC e antibiótico", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Uma E. coli é descrita como causadora de meningite neonatal, com cápsula K1 que mimetiza antígeno do hospedeiro. Qual é o nome do patotipo e o mecanismo de escape?", "alternativas": ["UPEC; a fímbria P se liga ao urotélio e impede a fagocitose por neutrófilos do sangue", "ETEC; a toxina LT inibe a fagocitose e a secreção de IgA no intestino do recém-nascido", "EPEC; a intimina destrói as microvilosidades e impede a passagem da bactéria pelo sangue", "MNEC; a cápsula K1 imita antígeno do hospedeiro, e o sistema imune não reage", "EIEC; a bactéria invade o enterócito e se multiplica dentro do vacúolo sem chegar ao sangue"], "gabarito": "D", "justificativa": "MNEC (meningite neonatal por E. coli) tem cápsula K1 que mimetiza antígeno do hospedeiro, dificultando a reação imune (resumo: Microbiota, patotipos da E. coli).", "tecnica": "MNEC", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Uma bactéria de uropatógeno tem fímbria P e hemolisina HlyA. Qual é o patotipo, e o que cada fator faz na infecção urinária?", "alternativas": ["EPEC; a fímbria P destrói o epitélio intestinal e a HlyA é uma toxina Shiga de ação sistêmica", "UPEC; fímbria P ancora ao urotélio e HlyA lisa células, com inflamação", "ETEC; a fímbria P produz enterotoxina e a HlyA é a subunidade B da toxina termolábil", "EAEC; a fímbria P forma biofilme no cólon e a HlyA impede a agregação em tijolos empilhados", "EIEC; a fímbria P invade o enterócito e a HlyA se liga à célula M da placa de Peyer"], "gabarito": "B", "justificativa": "UPEC: fímbria P e adesinas ancoram ao urotélio; hemolisina HlyA lisa eritrócitos e outras células, com resposta inflamatória. É principal agente de ITU (resumo: Microbiota, patotipos).", "tecnica": "UPEC", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Por que a urease do Proteus causa cálculos renais, e não apenas aumento da amônia no urina?", "alternativas": ["Porque a urease converte ureia em ácido úrico, que se cristaliza diretamente no túbulo renal", "Porque a urease reduz o pH para abaixo de 4, o que precipita a cistina em cristais no rim", "Porque a urease alcaliniza a urina, precipitando magnésio e cálcio como estruvita e apatita", "Porque a urease libera acetilcolina no rim, que causa espasmo de musculatura lisa e obstrução", "Porque a urease ativa a COX-2 renal, que produz tromboxano e forma coágulos nos ureteres"], "gabarito": "C", "justificativa": "A urease do Proteus converte ureia em amônia e CO₂, alcalinizando a urina. Nessa alcalinização, magnésio e cálcio precipitam como estruvita e apatita, formando cálculos (resumo: Microbiota, nichos ambientais).", "tecnica": "Urease e cálculo", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "O H. pylori sobrevive no estômago, com pH muito ácido. Qual é a combinação de mecanismos que permite essa sobrevivência?", "alternativas": ["Urease, que alcaliniza o microambiente, e motilidade em espiral até o muco próximo ao epitélio", "Catalase, que destrói o ácido clorídrico, e fímbria tipo 1, que se liga à mucosa gástrica", "Cápsula K1, que impede a difusão de ácido, e toxina Shiga, que destrói o revestimento gástrico", "Esporo, que resiste ao ácido, e toxina tetânica, que bloqueia a secreção de muco gástrico", "Hemolisina, que lisa células ácidas, e intimina, que forma microvilosidades no estômago"], "gabarito": "A", "justificativa": "H. pylori produz urease, que alcaliniza o microambiente. A motilidade em espiral o leva ao muco próximo ao epitélio, onde o pH é mais alto (resumo: Microbiota, nichos ambientais).", "tecnica": "H. pylori e acidez", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Uma infecção profunda em tecido desvitalizado favorece anaeróbios. Por que eles são intolerantes ao oxigênio, e qual conduta é coerente?", "alternativas": ["Não têm catalase nem superóxido-dismutase, e a conduta é o desbridamento cirúrgico", "Têm excesso de catalase, que gera peróxido em excesso, e a conduta é oxigenoterapia hiperbárica", "Têm enzimas que convertem oxigênio em ácido clorídrico, e a conduta é alcalinizar o tecido afetado", "Têm membrana rica em esteróis, que se rompe com o oxigênio, e a conduta é corticoide em dose alta", "Têm cápsula que se dissolve com oxigênio, e a conduta é usar anti-histamínico de primeira geração"], "gabarito": "A", "justificativa": "Anaeróbios não têm catalase nem superóxido-dismutase e obtêm energia por fermentação. Por isso o desbridamento, que retira o tecido desvitalizado, é a lógica do tratamento (resumo: Microbiota, nichos ambientais).", "tecnica": "Anaeróbios e desbridamento", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Na vagina, o ambiente ácido limita outros micro-organismos. Qual é o agente responsável por manter esse ambiente, e como ele atua?", "alternativas": ["Estafilococos coagulase-negativos, que produzem IgE e destroem a microbiota vaginal de forma imediata", "Lactobacilos, que mantêm pH ácido e limitam a colonização por outros micro-organismos", "Anaeróbios estritos, que produzem amônia e elevam o pH vaginal para favorecer a colonização", "Proteus mirabilis, que produz urease e alcaliniza o meio, o que mantém a vagina em pH neutro", "Clostridium difficile, que produz toxina B e mantém o ambiente ácido por fermentação de glicose"], "gabarito": "B", "justificativa": "Lactobacilos mantêm ambiente ácido na vagina e limitam a colonização por outros micro-organismos. É exemplo de microbiota protetora (resumo: Microbiota, nichos ambientais).", "tecnica": "Microbiota protetora", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um paciente tem hemocultura positiva com Staphylococcus epidermidis em uma única amostra de pele. Qual é a interpretação mais coerente com a aula?", "alternativas": ["É sempre infecção verdadeira, porque qualquer estafilococo isolado do sangue representa bacteremia confirmada", "É sempre contaminação, porque o S. epidermidis não causa doença em nenhum sítio do organismo humano", "É sempre resistente à penicilina, e por isso o tratamento deve ser feito com vancomicina imediatamente", "Pode ser contaminante ou patógeno; a interpretação depende do sítio, do número de amostras e do quadro", "É um fungo e não deve ser interpretado no contexto bacteriano, porque a hemocultura não detecta fungos"], "gabarito": "D", "justificativa": "S. epidermidis faz parte da microbiota da pele. Pode ser contaminante ou patógeno, e a interpretação depende do sítio, do número de amostras e do quadro clínico (resumo: Microbiota, sítios estéreis).", "tecnica": "Microbiota e contaminação", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Por que o desenvolvimento de cepas patogênicas de E. coli se deve mais a fatores de virulência do que à espécie?", "alternativas": ["Todas as cepas de E. coli têm a mesma toxina, que é ativada apenas por variação de temperatura do intestino", "O genoma central é o mesmo; a diferença vem de ilhas de patogenicidade, plasmídeos e fagos adquiridos", "A espécie E. coli é sempre patogênica, e as cepas comensais são apenas formas atenuadas do mesmo organismo", "A diferença depende apenas da idade do hospedeiro, e a E. coli muda de espécie ao longo da infância", "As cepas patogênicas são sempre mutantes com perda de todo o genoma central, o que as torna mais virulentas"], "gabarito": "B", "justificativa": "O genoma central da E. coli é o mesmo. O que muda são ilhas de patogenicidade, plasmídeos e fagos adquiridos horizontalmente, que transformam uma cepa comensal em patogênica (resumo: Microbiota, E. coli).", "tecnica": "E. coli: comensal × patogênica", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Um tecido de ferida desvitalizada tem abscesso e isquemia. Qual é a relação entre essas condições e a microbiota anaeróbia?", "alternativas": ["Impedem o crescimento de anaeróbios, porque a isquemia eleva a pressão de oxigênio e os destrói", "Substituem a microbiota aeróbia por fungos, que não são afetados pelo oxigênio nem pela isquemia", "Favorecem apenas Gram-positivos, porque a isquemia destrói a parede de Gram-negativos no tecido", "Não têm relação, porque a microbiota anaeróbia só existe no intestino e não nos tecidos profundos", "Favorecem anaeróbios, que obtêm energia por fermentação e não têm catalase nem SOD"], "gabarito": "E", "justificativa": "Tecidos com isquemia e desvitalização favorecem anaeróbios. Eles obtêm energia por fermentação e são intolerantes ao oxigênio, o que explica a lógica do desbridamento cirúrgico (resumo: Microbiota, nichos ambientais).", "tecnica": "Isquemia e anaeróbios", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Qual é a diferença entre EAEC e ETEC quanto ao padrão de adesão e à clínica?", "alternativas": ["ETEC agrega em tijolos empilhados, com diarreia persistente; EAEC causa diarreia aquosa por toxina Shiga", "EAEC invade o enterócito e causa disenteria; ETEC forma biofilme e causa colite hemorrágica grave no cólon", "EAEC agrega em tijolos empilhados, com diarreia persistente; ETEC causa diarreia aquosa", "EAEC produz toxina Shiga e causa síndrome hemolítico-urêmica; ETEC causa meningite neonatal por cápsula K1", "EAEC causa lesão A/E e diarreia infantil; ETEC forma microcolônias e causa colite com ulceração do cólon"], "gabarito": "C", "justificativa": "EAEC agrega em padrão de tijolos empilhados e causa diarreia persistente. ETEC produz enterotoxinas LT e ST e causa diarreia aquosa (resumo: Microbiota, patotipos da E. coli).", "tecnica": "EAEC × ETEC", "slide": null}], "id": "natalia-aula-04", "voltar": {"href": "#/agressao/natalia", "texto": "Professora Natália"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["natalia-aula-05"] = {"titulo": "Aula 5", "subtitulo": "Bactérias de importância médica nas infecções respiratórias e meníngeas: S. pneumoniae, S. pyogenes, N. meningitidis, H. influenzae e M. pneumoniae", "pdf": "pdf/natalia/aulas/aula-05.pdf", "abas": ["resumo", "glossario", "quiz", "pdf"], "resumo": [{"titulo": "1. Morfologia e identificação", "pontos": [{"t": "Cocos Gram-positivos e catalase", "sub": ["Cocos Gram-positivos em pares ou cadeias. Catalase-negativos, com metabolismo fermentativo. Diferenciação por hemólise e grupos antigênicos (slide 5).", "Catalase decompõe H₂O₂ em água e oxigênio. Estafilococos são geralmente catalase-positivos; estreptococos são catalase-negativos (slide 5)."]}, {"t": "Hemólise em ágar sangue", "sub": ["Alfa: hemólise parcial, zona esverdeada pela conversão de hemoglobina em biliverdina. Exemplos: S. pneumoniae e viridans (slide 7).", "Beta: hemólise completa, com halo transparente. Exemplos: S. pyogenes (grupo A), S. aureus e S. agalactiae (grupo B) (slide 8).", "Gama: ausência de hemólise visível (slide 6)."]}, {"t": "Classificação de Lancefield", "sub": ["Criada pela bacteriologista Rebecca Lancefield na década de 1930. Classifica estreptococos pelos carboidratos da parede, de A a V (slide 10).", "Grupo A: S. pyogenes, causa faringite, escarlatina, erisipela, febre reumática e glomerulonefrite (slide 10).", "Grupo B: S. agalactiae, comum na microbiota vaginal e digestiva. Risco de sepse e meningite neonatal no parto (slide 10)."]}]}, {"titulo": "2. Estreptococos do grupo A e testes sorológicos", "pontos": [{"t": "Antiestreptolisina O (ASLO)", "sub": ["S. pyogenes libera a estreptolisina O, sensível ao oxigênio, que é beta-hemolítica e antigênica. O sistema imune produz anticorpos ASLO para neutralizá-la (slide 11).", "ASLO sobe após 3 a 5 semanas da infecção e pode ficar alto por meses. Por isso é usado para investigar complicações tardias, mesmo após a garganta melhorar (slides 11 e 12).", "Complicações tardias: febre reumática (coração, articulações e cérebro) e glomerulonefrite pós-estreptocócica (urina escura, inchaço e pressão alta) (slide 12)."]}]}, {"titulo": "3. Streptococcus pneumoniae (pneumococo)", "pontos": [{"t": "Visão geral", "sub": ["Diplococos Gram-positivos lanceolados, encapsulados, alfa-hemolíticos e catalase-negativos. Coloniza a nasofaringe humana (slide 13).", "Manifestações: pneumonia, otite média, sinusite, bacteremia e meningite (slide 13)."]}, {"t": "Fatores de virulência", "sub": ["Cápsula polissacarídica: resistência à fagocitose. A cápsula é espessa e hidratada, e cria barreira física que esconde proteínas e componentes da parede (slide 14).", "Carga negativa da cápsula e da superfície fagocítica causa repulsão eletrostática, que dificulta a aproximação do fagócito (slide 15).", "Inibição da opsonização: a cápsula esconde os locais onde C3b se fixa (slide 16).", "Pneumolisina: toxina citolítica dependente de colesterol que forma poros, paralisa cílios e causa ativação cega do complemento, com acúmulo de neutrófilos e pus nos alvéolos (slides 17 a 21). Fica guardada no citoplasma e é liberada na lise bacteriana.", "Adesinas: expostas com cápsula mais fina para aderir ao epitélio. Cápsula espessa de novo para invadir (slide 22).", "IgA1 protease: corta a IgA secretora e facilita a persistência nas mucosas (slide 23)."]}]}, {"titulo": "4. Streptococcus pyogenes (grupo A)", "pontos": [{"t": "Visão geral", "sub": ["Cocos Gram-positivos em cadeias, beta-hemolíticos, grupo A de Lancefield. Transmissão por secreções respiratórias e contato direto. Causa faringite bacteriana (slide 25).", "Fatores de virulência: proteína M, cápsula de ácido hialurônico, estreptolisinas e exotoxinas pirogênicas (slide 25)."]}, {"t": "Fatores de virulência", "sub": ["Proteína M: antifagocítica, bloqueia a deposição de C3b e é adesina. Tem diversidade antigênica. Mimetismo molecular com proteínas do coração, das articulações e dos rins causa febre reumática (slide 26).", "Cápsula de ácido hialurônico: não é reconhecida como invasora, e a bactéria passa camuflada (slide 27).", "Estreptolisina O: sensível ao oxigênio, forma poros e é antigênica (dosada no ASLO). Estreptolisina S: estável, não estimula o sistema imune e é responsável pelo halo beta-hemolítico (slide 28).", "Exotoxinas pirogênicas estreptocócicas (SPE): superantígenos que causam tempestade de citocinas. Causam o exantema da escarlatina e o choque tóxico estreptocócico (slide 29)."]}]}, {"titulo": "5. Neisseria meningitidis (meningococo)", "pontos": [{"t": "Visão geral", "sub": ["Diplococos Gram-negativos, oxidase-positivos. Encapsulados nas principais linhagens invasivas. Coloniza a nasofaringe e é transmitido por secreções respiratórias. Causa meningite e meningococcemia (slide 31)."]}, {"t": "Fatores de virulência", "sub": ["Pili: adesão inicial às células não ciliadas da mucosa, como um gancho que resiste ao fluxo de muco (slide 33).", "Cápsula: impede a fagocitose e bloqueia o complemento. Com base nela são definidos os sorogrupos A, B, C, W e Y, que dão nome às vacinas (slide 34).", "IgA1 protease: corta a IgA humana e permite colonização por semanas ou meses (slide 35).", "LOS: endotoxina da membrana externa. A liberação na circulação causa intensa inflamação, hemorragias na pele, queda de pressão e CIVD (slide 36).", "Proteínas de membrana externa, como Opa e Opc: adesão íntima e entrada na célula, com passagem da barreira hematoencefálica (slide 37)."]}]}, {"titulo": "6. Haemophilus influenzae", "pontos": [{"t": "Visão geral e cultivo", "sub": ["Cocobacilo Gram-negativo pleomórfico, exigente nutricionalmente. Precisa de fator X (hemina) e fator V (NAD). Cresce em ágar chocolate (slide 39).", "Coloniza o trato respiratório superior. Tem cepas encapsuladas e não encapsuladas. Causa otite, sinusite, pneumonia e meningite em cepas invasivas (slide 39)."]}, {"t": "Tipo b (Hib) e vacina", "sub": ["Hib tem cápsula de PRP (poliribosil-ribitol-fosfato). Foi a principal causa mundial de meningite em menores de 5 anos e causa epiglotite aguda (slide 40).", "Vacina conjugada contra o Hib, incluída na pentavalente. Reduziu a meningite por Hib em mais de 95% nos países que vacinaram em massa (slide 41)."]}, {"t": "Fatores de virulência", "sub": ["Cápsula: dificulta opsonização e fagocitose, favorece a disseminação no sangue. Adesinas: colonização da nasofaringe. IgA1 protease. LOS (endotoxina). Captação de ferro (slide 42).", "Captação de ferro e heme: complexo TbpA e TbpB para a transferrina no sangue. Complexo LbpA e LbpB para a lactoferrina nas mucosas (slides 43 e 44)."]}]}, {"titulo": "7. Mycoplasma pneumoniae", "pontos": [{"t": "Características", "sub": ["Bactéria muito pequena e pleomórfica. Não tem parede celular. Tem membrana com esteróis. Possui estrutura especializada de adesão (organela terminal) (slide 46).", "Causa infecção respiratória, incluindo pneumonia atípica (slide 46)."]}, {"t": "Patogenia", "sub": ["Adesina P1: liga-se a receptores de ácido siálico nas células ciliadas da traqueia e dos brônquios (slide 48).", "Ciliostase pela P1. Libera peróxido de hidrogênio e radicais livres direto sobre a célula, sem diluição no muco (slide 49).", "Toxina CARDS (síndrome de desconforto respiratório adquirido na comunidade): penetra na célula, forma vacúolos, fragmenta o DNA e causa morte celular (slide 49)."]}, {"t": "Diagnóstico", "sub": ["PCR, pesquisa de crioglutininas e cultura, que cresce em 2 a 3 semanas (slide 50)."]}]}, {"titulo": "8. Síntese comparativa", "pontos": [{"t": "Qual agente e qual fator-chave", "sub": ["S. pneumoniae: cápsula, pneumolisina, IgA1 protease. S. pyogenes: proteína M, ácido hialurônico, SPE. N. meningitidis: pili, cápsula, LOS. H. influenzae: PRP, LOS, captação de ferro. M. pneumoniae: P1, CARDS, H₂O₂ (slides 13 a 50)."]}]}, {"titulo": "9. Estrutura bacteriana: Gram, não-Gram e estruturas acessórias", "pontos": [{"t": "Gram-positivas × Gram-negativas", "sub": ["Gram-positivas: peptidoglicano espesso, multicamadas, retém o cristal violeta; sem membrana externa; ácidos teicoicos e lipoteicoicos (adesão, indutores de inflamação); parede acessível → mais sensíveis a β-lactâmicos.", "Gram-negativas: peptidoglicano fino, em única camada, no espaço periplasmático (abriga β-lactamases); membrana externa com LPS (endotoxina) e porinas; membrana externa é barreira de permeabilidade → resistência intrínseca a vários antimicrobianos; LPS causa sepse."]}, {"t": "As três que o Gram não resolve", "sub": ["M. tuberculosis: parede rica em ácido micólico, cerosa e hidrofóbica, impede a entrada do corante. Ziehl-Neelsen (bacilo álcool-ácido resistente); cultura lenta em Löwenstein-Jensen; testes moleculares.", "Mycoplasma pneumoniae: não tem parede celular, só membrana com esteróis. Não cora pelo Gram; sorologia e PCR; resistente a β-lactâmicos porque não tem o alvo.", "Treponema pallidum: espiroqueta fina demais para o Gram; não cultivável em meio artificial. Microscopia de campo escuro na lesão; sorologia treponêmica e não treponêmica.", "Pegadinha: as três escapam do Gram por motivos diferentes (sem parede; parede cerosa demais; parede fina demais para ser resolvida). Trocar essas explicações é distrator clássico."]}, {"t": "Estruturas acessórias", "sub": ["Cápsula (polissacarídica; exceto B. anthracis, de ácido D-glutâmico): antifagocitária, impede a ligação de C3b e do fagócito. Exemplos: S. pneumoniae, N. meningitidis, H. influenzae b, K. pneumoniae.", "Fímbrias e pili (proteína, pilina): adesão ao epitélio; pili sexual faz conjugação (troca de resistência). Exemplos: fímbria P de E. coli; pili de Neisseria.", "Flagelo (flagelina, antígeno H): motilidade; permite ascender contra o fluxo urinário. Exemplos: Proteus, Salmonella, E. coli, Vibrio.", "Endósporo (dipicolinato de cálcio, desidratado): resistência extrema a calor, dessecação e desinfetantes; forma de sobrevivência, não de reprodução. Apenas Gram-positivos: Bacillus e Clostridium."]}, {"t": "Correlação com imunologia", "sub": ["Cápsula polissacarídica é antígeno T-independente: resposta sem memória e ineficaz abaixo dos 2 anos. Daí as vacinas conjugadas contra pneumococo, meningococo e H. influenzae b.", "O esplenectomizado perde a zona marginal e a depuração de opsonizados: risco de sepse fulminante por esses três agentes."]}]}, {"titulo": "10. Cocos de importância médica em tabela", "pontos": [{"t": "Staphylococcus, Streptococcus, Enterococcus e Neisseria", "sub": ["Morfologia: Staphylococcus em cacho; Streptococcus em cadeia; Enterococcus em pares e cadeias curtas; Neisseria em diplococo em grão de café.", "Gram: +, +, +, −. Catalase: positiva (Staphylococcus), negativa (Streptococcus, Enterococcus), positiva (Neisseria).", "Prova decisiva: coagulase separa S. aureus (+) de S. epidermidis e S. saprophyticus (−). Hemólise: β (S. pyogenes, bacitracina S; S. agalactiae); α (S. pneumoniae, optoquina S, solúvel em bile; viridans). Enterococcus cresce em NaCl 6,5% e em bile-esculina. Neisseria: oxidase positiva; N. meningitidis fermenta glicose e maltose; N. gonorrhoeae só glicose.", "Doenças: Staphylococcus: abscesso, furúnculo, impetigo, osteomielite, endocardite, infecção de cateter; toxinoses (síndrome do choque tóxico, pele escaldada, intoxicação alimentar). Streptococcus: S. pyogenes (faringite, erisipela, escarlatina, fasciíte; sequelas febre reumática e glomerulonefrite); S. pneumoniae (pneumonia, meningite, otite). Enterococcus: ITU, infecção intra-abdominal, endocardite; hospitalar, com resistência (VRE). Neisseria: N. meningitidis (meningite e meningococcemia); N. gonorrhoeae (gonorreia, doença inflamatória pélvica)."]}, {"t": "Atenção para a prova", "sub": ["Catalase separa Staphylococcus (+) de Streptococcus (−); coagulase separa S. aureus dos demais estafilococos. São as duas provas bioquímicas que mais aparecem em questão de identificação."]}]}, {"titulo": "11. Fatores de virulência e evasão imunológica", "pontos": [{"t": "Definições", "sub": ["Fator de virulência: qualquer estrutura ou produto que aumente a capacidade de colonizar, invadir, causar dano ou escapar da defesa. Estruturas (cápsula, fímbria, flagelo, LPS), enzimas e toxinas.", "Opsonização: revestimento do micro-organismo por IgG e C3b, que funcionam como \"alças\" reconhecidas por receptores Fc e CR1 do fagócito. A fagocitose segue com englobamento, fagossomo, fusão com lisossomo e destruição por espécies reativas de oxigênio e enzimas."]}, {"t": "Estratégias de evasão", "sub": ["Cápsula: impede a deposição e o reconhecimento de C3b; a mais importante. Pneumococo, meningococo, H. influenzae, Klebsiella.", "Proteína A (S. aureus): liga-se ao Fc da IgG, orientando o anticorpo \"ao contrário\" e impedindo o reconhecimento pelo fagócito.", "Proteína M (S. pyogenes): antifagocitária; interfere na deposição de C3b; é também o antígeno do mimetismo molecular na febre reumática.", "IgA protease: cliva a IgA secretora; permite colonizar mucosas (Neisseria, H. influenzae, S. pneumoniae).", "Catalase e SOD: degradam peróxido e superóxido; sobrevivem ao burst respiratório do fagócito.", "Leucocidinas: matam o próprio fagócito (ex.: Panton-Valentine, de S. aureus).", "Variação antigênica: troca periódica de antígenos de superfície e escapa do anticorpo já produzido (Neisseria, Borrelia)."]}]}, {"titulo": "12. Enzimas bacterianas em tabela", "pontos": [{"t": "Catalase, coagulase, urease, hialuronidase e IgA protease", "sub": ["Catalase: converte H₂O₂ em água e oxigênio; protege do burst respiratório; diferencia Staphylococcus de Streptococcus.", "Coagulase: converte fibrinogênio em fibrina, forma casulo que isola o foco do sistema imune → abscesso; define S. aureus.", "Urease: ureia → amônia + CO₂, alcaliniza o meio. H. pylori (base do teste rápido da urease e do teste respiratório); Proteus (cálculo de estruvita).", "Hialuronidase: degrada o ácido hialurônico da matriz; \"fator de difusão\" que espalha a infecção (S. pyogenes, S. aureus, C. perfringens).", "IgA protease: cliva a IgA secretora na região de dobradiça; Neisseria, H. influenzae, S. pneumoniae."]}]}, {"titulo": "13. Toxinas: exotoxina × endotoxina e da bactéria à sepse", "pontos": [{"t": "Comparação", "sub": ["Exotoxina: proteína; secretada ativamente por Gram-positivas e Gram-negativas; geralmente codificada em plasmídeo ou fago (aquisição horizontal); altíssima potência com ação específica; termolábil na maioria; converte em toxoide (base das vacinas de tétano e difteria).", "Endotoxina: LPS, com o lipídeo A ativo; só Gram-negativas; parte da membrana externa, liberada na lise; cromossômica e constitutiva; potência menor, efeito inespecífico e sistêmico; termoestável; não forma toxoide."]}, {"t": "Conceito-chave: da bactéria à sepse", "sub": ["LPS liberado na lise é reconhecido pelo TLR4 de macrófagos → liberação maciça de TNF-α, IL-1 e IL-6.", "Cada citocina produz um sinal: PGE₂ no hipotálamo (febre); vasodilatação e aumento de permeabilidade (hipotensão e edema); fator tecidual no endotélio → CIVD, que consome plaquetas e fatores, gerando trombose e sangramento (petéquias e púrpura).", "Elo entre matérias: LPS (Micro) → citocinas (Imuno) → PGE₂, alvo dos AINEs (Farmacologia, aula 6)."]}, {"t": "Clostridium: por que o mesmo gênero produz quadros opostos", "sub": ["C. tetani: aquisição por esporo do solo em ferida puntiforme e anaeróbia; toxina tetanospasmina; bloqueia a liberação de GABA e glicina nos interneurônios de Renshaw; paralisia espástica (trismo, riso sardônico, opistótono).", "C. botulinum: aquisição por toxina pré-formada em conserva; esporo no mel (botulismo do lactente); ferida; toxina botulínica bloqueia a liberação de acetilcolina na junção neuromuscular; paralisia flácida descendente, com risco de parada respiratória.", "C. perfringens: aquisição por trauma com tecido desvitalizado ou alimento; toxina α (lecitinase, fosfolipase C) e enterotoxina; degrada fosfolipídeos → lise e necrose; mionecrose e gangrena gasosa, ou intoxicação alimentar.", "Pegadinha: tetanospasmina e toxina botulínica são metaloproteases que clivam proteínas SNARE e impedem a exocitose. O que produz quadros opostos é o neurônio atingido: inibitório (perde-se o freio → espasmo) ou motor (perde-se o comando → flacidez). A patogenia é definida pela toxina codificada, e não pelo gênero."]}]}, {"titulo": "14. Manifestação clínica → agente → mecanismo", "pontos": [{"t": "Relação", "sub": ["Abscesso e secreção purulenta: S. aureus. Coagulase delimita o foco com fibrina; leucocidinas matam neutrófilos; o pus é o acúmulo de neutrófilos mortos.", "Lesão e inflamação da mucosa gástrica: H. pylori. Urease (amônia é citotóxica e alcaliniza), citotoxinas VacA e CagA, inflamação crônica → gastrite, úlcera, risco de adenocarcinoma e linfoma MALT.", "Petéquias e púrpura: N. meningitidis. LPS em alta carga → CIVD → consumo de plaquetas e lesão vascular → extravasamento cutâneo.", "Rigidez e espasmos: C. tetani, por bloqueio da neurotransmissão inibitória.", "Necrose tecidual: C. perfringens, por toxina α (lecitinase) que destrói membranas.", "Infecção do sistema nervoso central: S. pneumoniae, N. meningitidis, H. influenzae b e Listeria. A cápsula resiste à fagocitose e a bactéria atravessa a barreira hematoencefálica; o dano vem da inflamação do líquor."]}]}, {"titulo": "15. Diagnóstico microbiológico por condição clínica", "pontos": [{"t": "Amostra e método", "sub": ["Pneumonia bacteriana: escarro, hemocultura ou lavado broncoalveolar; Gram + cultura; antígeno urinário para pneumococo e Legionella.", "Meningite bacteriana: líquor (+ hemocultura); citoquímica (celularidade, glicose baixa, proteína alta), Gram, cultura, látex para antígeno capsular, PCR.", "Tuberculose pulmonar: escarro em amostras seriadas; baciloscopia (Ziehl-Neelsen), teste rápido molecular, cultura em Löwenstein-Jensen com teste de sensibilidade.", "Infecção urinária: urina de jato médio; urocultura quantitativa (distingue infecção de contaminação), sedimento e antibiograma.", "Sífilis: exsudato da lesão (fase primária) e soro; campo escuro; sorologia não treponêmica (VDRL/RPR, titula e acompanha tratamento) e treponêmica (FTA-Abs/TPHA, confirma e permanece positiva).", "Infecção cutânea com abscesso: aspirado do abscesso (não swab superficial); Gram, cultura e antibiograma.", "H. pylori: biópsia gástrica, ar expirado, fezes; teste rápido da urease, histologia, cultura; urease respiratória com ureia marcada; antígeno fecal; sorologia (não distingue infecção ativa)."]}, {"t": "Direto × indireto", "sub": ["Direto detecta o agente ou um componente: bacterioscopia (rápida, baixa sensibilidade), cultura (padrão-ouro, permite antibiograma, mas lenta), pesquisa de antígeno (rápida), PCR (altíssima sensibilidade, independe de viabilidade).", "Indireto detecta a resposta do hospedeiro: IgM sugere infecção recente; IgG indica contato prévio; soroconversão ou aumento de quatro vezes no título confirma infecção ativa.", "Escolha pelo agente: Treponema não cresce em meio artificial → sorologia; Mycoplasma cresce mal e lentamente → sorologia ou PCR; M. tuberculosis cresce em semanas → método molecular; em ITU a cultura é rápida e quantitativa, essencial para separar infecção de colonização."]}]}, {"titulo": "16. β-lactâmicos e resistência", "pontos": [{"t": "Mecanismo", "sub": ["β-lactâmicos (penicilinas, cefalosporinas, carbapenêmicos, monobactâmicos) ligam-se às PBP (proteínas ligadoras de penicilina, transpeptidases que fazem as ligações cruzadas do peptidoglicano).", "Bloqueada a transpeptidação, a parede fica defeituosa e a bactéria sofre lise osmótica. São bactericidas e só agem em bactérias em multiplicação."]}, {"t": "Intrínseca × adquirida", "sub": ["Intrínseca (natural): característica da espécie. Mycoplasma não tem parede, logo não tem alvo. Gram-negativas têm membrana externa impermeável a muitos fármacos.", "Adquirida: por mutação ou transferência horizontal (plasmídeo, transposon, conjugação). β-lactamases e ESBL hidrolisam o anel; PBP2a do MRSA tem alvo alterado de baixa afinidade; bombas de efluxo; alteração de porinas."]}, {"t": "Atenção para a prova", "sub": ["Para prever eficácia, o alvo precisa existir e ser alcançável: sem parede não há ação (Mycoplasma); com membrana externa, o fármaco pode não chegar ao periplasma (Gram-negativas); com β-lactamase periplasmática, é destruído antes de atuar."]}]}, {"titulo": "17. Mesma síndrome, agentes distintos: tabela ampliada", "pontos": [{"t": "Agentes", "sub": ["S. pneumoniae: diplococo Gram-positivo lanceolado, α-hemolítico, optoquina sensível, solúvel em bile. Cápsula (principal), pneumolisina, IgA protease, ácido teicoico. Gram e cultura de escarro, sangue ou líquor; antígeno urinário; látex no líquor.", "M. pneumoniae: sem parede; o menor procarioto de vida livre; colônia em \"ovo frito\". Adesina P1 fixa-se ao epitélio respiratório e paralisa os cílios; dano sobretudo imunomediado. Sorologia e PCR; não cora pelo Gram; cultura lenta.", "H. influenzae: cocobacilo Gram-negativo; exige fatores X (hemina) e V (NAD) → ágar chocolate. Cápsula tipo b (polirribitol fosfato), IgA protease, fímbrias. Cultura em ágar chocolate; látex; PCR.", "M. tuberculosis: bacilo álcool-ácido resistente; ácido micólico; crescimento muito lento. Sobrevive no macrófago bloqueando a fusão fagolisossômica → granuloma (hipersensibilidade IV). Baciloscopia, teste rápido molecular, cultura; prova tuberculínica ou IGRA para infecção latente.", "N. meningitidis: diplococo Gram-negativo em grão de café, oxidase positivo; fermenta glicose e maltose. Cápsula, LPS em alta carga (→ CIVD), pili, IgA protease. Líquor e hemocultura: Gram, cultura, látex, PCR.", "L. monocytogenes: bacilo Gram-positivo, motilidade \"em tombo\", cresce a 4 °C (refrigerador). Listeriolisina O e ActA → vida intracelular e disseminação célula a célula; atravessa placenta e barreira hematoencefálica. Cultura de líquor e sangue; resistente a cefalosporinas; usa-se ampicilina."]}]}], "glossario": [{"termo": "Catalase", "tecnica": "Enzima", "definicao": "Decompõe peróxido de hidrogênio em água e oxigênio. Estafilococos são geralmente positivos; estreptococos, negativos.", "slide": 5}, {"termo": "Alfa-hemólise", "tecnica": "Hemólise", "definicao": "Hemólise parcial com zona esverdeada, pela conversão de hemoglobina em biliverdina. Ex.: S. pneumoniae.", "slide": 7}, {"termo": "Beta-hemólise", "tecnica": "Hemólise", "definicao": "Hemólise completa com halo transparente, pelas hemolisinas. Ex.: S. pyogenes.", "slide": 8}, {"termo": "Rebecca Lancefield (epônimo: Lancefield)", "tecnica": "Classificação", "definicao": "Bacteriologista que classificou estreptococos pelos carboidratos da parede, na década de 1930. Grupos de A a V.", "slide": 10, "epônimo": "Lancefield"}, {"termo": "Grupo A de Lancefield", "tecnica": "Classificação", "definicao": "Grupo de S. pyogenes, causa de faringite, escarlatina, erisipela, febre reumática e glomerulonefrite.", "slide": 10}, {"termo": "Grupo B de Lancefield", "tecnica": "Classificação", "definicao": "Grupo de S. agalactiae, causa de sepse e meningite neonatal.", "slide": 10}, {"termo": "ASLO (antiestreptolisina O)", "tecnica": "Sorologia", "definicao": "Anticorpo contra a estreptolisina O. Sobe após 3 a 5 semanas e pode ficar alto por meses. Usado para investigar complicações tardias.", "slide": 11}, {"termo": "Estreptolisina O", "tecnica": "Toxina", "definicao": "Toxina beta-hemolítica sensível ao oxigênio, que forma poros e é antigênica. Base do teste ASLO.", "slide": 11}, {"termo": "Estreptolisina S", "tecnica": "Toxina", "definicao": "Toxina estável ao oxigênio, não antigênica, responsável pelo halo de beta-hemólise.", "slide": 28}, {"termo": "Febre reumática", "tecnica": "Complicação", "definicao": "Inflamação de coração, articulações e cérebro após faringite por S. pyogenes, por mimetismo molecular com a proteína M.", "slide": 12}, {"termo": "Glomerulonefrite pós-estreptocócica", "tecnica": "Complicação", "definicao": "Inflamação renal após infecção estreptocócica, com urina escura, inchaço e pressão alta.", "slide": 12}, {"termo": "Streptococcus pneumoniae", "tecnica": "Agente", "definicao": "Diplococo Gram-positivo lanceolado, encapsulado, alfa-hemolítico. Causa pneumonia lobar, otite, sinusite e meningite.", "slide": 13}, {"termo": "Pneumolisina", "tecnica": "Toxina", "definicao": "Toxina citolítica dependente de colesterol, que forma poros, paralisa cílios e ativa o complemento de forma descontrolada.", "slide": 19}, {"termo": "Cápsula polissacarídica (pneumococo)", "tecnica": "Fator de virulência", "definicao": "Camada espessa que bloqueia a fagocitose e esconde o C3b e a parede bacteriana.", "slide": 14}, {"termo": "IgA1 protease", "tecnica": "Enzima", "definicao": "Enzima que corta a IgA secretora da mucosa. Presente em S. pneumoniae, N. meningitidis e H. influenzae.", "slide": 23}, {"termo": "Adesina", "tecnica": "Fator de virulência", "definicao": "Estrutura que liga a bactéria à célula do hospedeiro. Ex.: adesina P1 do M. pneumoniae.", "slide": 22}, {"termo": "Streptococcus pyogenes", "tecnica": "Agente", "definicao": "Estreptococo beta-hemolítico do grupo A. Causa faringite, escarlatina, impetigo, erisipela, fasceíte necrosante e febre reumática.", "slide": 25}, {"termo": "Proteína M", "tecnica": "Fator de virulência", "definicao": "Proteína de superfície antifagocítica do S. pyogenes, que bloqueia C3b e é adesina. Base da febre reumática por mimetismo.", "slide": 26}, {"termo": "Mimetismo molecular", "tecnica": "Autoimunidade", "definicao": "Anticorpos contra um antígeno bacteriano reagem com estruturas humanas semelhantes, como no coração e nas articulações.", "slide": 26}, {"termo": "Cápsula de ácido hialurônico", "tecnica": "Fator de virulência", "definicao": "Cápsula do S. pyogenes que não é reconhecida como estranha pelo sistema imune.", "slide": 27}, {"termo": "Exotoxina pirogênica estreptocócica (SPE)", "tecnica": "Superantígeno", "definicao": "Superantígeno do S. pyogenes que causa tempestade de citocinas, escarlatina e choque tóxico estreptocócico.", "slide": 29}, {"termo": "Choque tóxico estreptocócico", "tecnica": "Complicação", "definicao": "Queda abrupta de pressão, falência de órgãos e risco de morte, por superantígeno (SPE).", "slide": 29}, {"termo": "Neisseria meningitidis", "tecnica": "Agente", "definicao": "Diplococo Gram-negativo oxidase-positivo, encapsulado. Causa meningite e meningococcemia.", "slide": 31}, {"termo": "Pili (fímbrias de Neisseria)", "tecnica": "Fator de virulência", "definicao": "Estruturas de adesão inicial ao epitélio nasofaríngeo, resistentes ao fluxo de muco.", "slide": 33}, {"termo": "Sorogrupos A, B, C, W e Y", "tecnica": "Classificação", "definicao": "Classificação do meningococo pela cápsula. Dá nome às vacinas meningocócicas.", "slide": 34}, {"termo": "LOS (lipooligossacarídeo)", "tecnica": "Endotoxina", "definicao": "Endotoxina da membrana externa de N. meningitidis e H. influenzae. Causa inflamação, hemorragias e CIVD.", "slide": 36}, {"termo": "Opa e Opc", "tecnica": "Proteína de membrana", "definicao": "Proteínas de opacidade do meningococo que promovem adesão íntima e passagem pela barreira hematoencefálica.", "slide": 37}, {"termo": "Haemophilus influenzae", "tecnica": "Agente", "definicao": "Cocobacilo Gram-negativo exigente, que precisa de fatores X (hemina) e V (NAD). Causa meningite e pneumonia.", "slide": 39}, {"termo": "Fator X (hemina) e fator V (NAD)", "tecnica": "Cultivo", "definicao": "Nutrientes necessários ao Haemophilus, fornecidos pelo ágar chocolate.", "slide": 39}, {"termo": "Hib (Haemophilus influenzae tipo b)", "tecnica": "Agente", "definicao": "Tipo b com cápsula de PRP. Principal causa de meningite em menores de 5 anos antes da vacina.", "slide": 40}, {"termo": "PRP (poliribosil-ribitol-fosfato)", "tecnica": "Cápsula", "definicao": "Açúcar da cápsula do Hib, usado como antígeno vacinal conjugado.", "slide": 40}, {"termo": "Vacina conjugada contra Hib", "tecnica": "Vacina", "definicao": "Vacina que reduziu mais de 95% da meningite por Hib, incluída na pentavalente.", "slide": 41}, {"termo": "TbpA e TbpB", "tecnica": "Captação de ferro", "definicao": "Complexo de membrana que captura ferro da transferrina humana. TbpB reconhece a transferrina; TbpA forma o canal.", "slide": 43}, {"termo": "LbpA e LbpB", "tecnica": "Captação de ferro", "definicao": "Complexo equivalente, que captura ferro da lactoferrina nas mucosas respiratórias.", "slide": 44}, {"termo": "Mycoplasma pneumoniae", "tecnica": "Agente", "definicao": "Bactéria sem parede, com membrana de esteróis e organela de adesão. Causa pneumonia atípica.", "slide": 46}, {"termo": "Organela terminal", "tecnica": "Estrutura de adesão", "definicao": "Estrutura especializada de adesão do M. pneumoniae, que contém a adesina P1.", "slide": 48}, {"termo": "Adesina P1", "tecnica": "Fator de virulência", "definicao": "Adesina do M. pneumoniae que liga o ácido siálico das células ciliadas da traqueia e dos brônquios.", "slide": 48}, {"termo": "Toxina CARDS", "tecnica": "Toxina", "definicao": "Exotoxina única do M. pneumoniae, que penetra na célula, forma vacúolos e fragmenta o DNA.", "slide": 49}, {"termo": "Ciliostase", "tecnica": "Patogenia", "definicao": "Paralisia dos cílios respiratórios, causada por M. pneumoniae e S. pneumoniae.", "slide": 49}, {"termo": "Crioglutininas", "tecnica": "Diagnóstico", "definicao": "Anticorpos frios que aparecem em infecções por M. pneumoniae. Usados como apoio diagnóstico.", "slide": 50}], "fontes": ["Aula 5, Principais bactérias de importância médica nas infecções respiratórias e meníngeas (pdf/natalia/aulas/aula-05.pdf, slides 1 a 50)", "Base complementar: Murray, Medical Microbiology (caps. de estreptococos, Neisseria, Haemophilus e Mycoplasma)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um micro-organismo não cora pelo Gram de rotina e não cresce em meio artificial. Qual é o agente que combina essas características com diagnóstico por sorologia e campo escuro?", "alternativas": ["Staphylococcus aureus, cocos em cacho que cora de forma intensa pelo Gram e cresce em ágar sangue", "Treponema pallidum, espiroqueta fina demais para o Gram e não cultivável em meio artificial", "Streptococcus pyogenes, cocos em cadeia com cápsula de ácido hialurônico que cora pelo Gram", "Neisseria gonorrhoeae, diplococo em grão de café que cresce em ágar chocolate e cora pelo Gram", "Listeria monocytogenes, bacilo que cresce a 4 °C e é visto no Gram como bacilo Gram-positivo"], "gabarito": "B", "justificativa": "Treponema pallidum é espiroqueta fina demais para o Gram e não cresce em meio artificial. Detecta-se por campo escuro na lesão e por sorologia (resumo: Estrutura bacteriana, não-Gram).", "tecnica": "Não-Gram", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Qual é a estrutura que resiste a calor, dessecação e desinfetantes, e que não é reprodução, mas forma de sobrevivência?", "alternativas": ["Cápsula polissacarídica, presente em todos os Gram-negativos, que protege contra o calor", "Fímbria, composta de pilina, que se contrai e resiste à dessecação no ambiente hospitalar", "Flagelo, composto de flagelina, que resiste ao calor por conter cálcio em sua estrutura", "Endósporo, com dipicolinato de cálcio, presente apenas em Bacillus e Clostridium", "Membrana externa com LPS, presente apenas em Gram-positivos, que resiste ao desinfetante"], "gabarito": "D", "justificativa": "Endósporo é forma de sobrevivência com dipicolinato de cálcio, resistente a calor, dessecação e desinfetantes. Ocorre apenas em Gram-positivos, como Bacillus e Clostridium (resumo: Estrutura bacteriana, estruturas acessórias).", "tecnica": "Endósporo", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Por que a vacina conjugada contra pneumococo é necessária, se a cápsula é um fator de virulência tão importante?", "alternativas": ["Porque a cápsula é proteica e atrai linfócitos T CD8+, que são eficazes apenas após os 2 anos", "Porque a cápsula é formada por IgE, o que torna a vacina necessária apenas em alérgicos graves", "Porque a cápsula é composta de LPS, que só é reconhecido por células NK em crianças acima de 5 anos", "Porque a cápsula é um endósporo, e a vacina precisa destruir a forma de resistência antes da infecção", "Porque a cápsula polissacarídica é T-independente, sem memória e pouco eficaz abaixo dos 2 anos"], "gabarito": "E", "justificativa": "Cápsula polissacarídica é antígeno T-independente, gera resposta sem memória e é pouco eficaz abaixo de 2 anos. Por isso existem vacinas conjugadas contra pneumococo, meningococo e H. influenzae b (resumo: Estrutura bacteriana, correlação com imunologia).", "tecnica": "Cápsula e vacina conjugada", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um cocos Gram-positivo é catalase negativo, cresce em cadeia e é solúvel em bile. Qual é o agente mais provável, e qual teste confirma essa solubilidade?", "alternativas": ["S. aureus, com teste de coagulase em plasma de coelho para confirmar a identidade", "Enterococcus faecalis, com teste de crescimento em NaCl 6,5% e bile-esculina", "N. meningitidis, com teste de oxidase e fermentação de maltose em meio específico", "S. pyogenes, com teste de bacitracina e reação de PYR positiva em todo o cultivo", "S. pneumoniae, com teste de solubilidade em bile sobre colônia isolada"], "gabarito": "E", "justificativa": "S. pneumoniae é catalase negativo, α-hemolítico, optoquina sensível e solúvel em bile. O teste de solubilidade em bile é feito sobre colônia isolada (resumo: Cocos de importância médica, tabela).", "tecnica": "Pneumococo", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Por que a coagulase é a prova decisiva para diferenciar S. aureus dos demais estafilococos?", "alternativas": ["Porque converte fibrinogênio em fibrina, e apenas S. aureus produz essa enzima de forma consistente", "Porque converte ureia em amônia, e apenas S. aureus produz urease de forma consistente entre as cepas", "Porque degrada o ácido hialurônico, e apenas S. aureus produz hialuronidase de forma consistente", "Porque reduz o H₂O₂ em água e oxigênio, e apenas S. aureus produz catalase de forma consistente", "Porque cliva a IgA secretora, e apenas S. aureus produz IgA protease de forma consistente"], "gabarito": "A", "justificativa": "Coagulase converte fibrinogênio em fibrina. S. aureus é coagulase positivo; S. epidermidis e S. saprophyticus são coagulase negativos. É uma das duas provas que mais aparecem em questão (resumo: Cocos de importância médica).", "tecnica": "Coagulase", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um patógeno produz uma proteína que se liga ao Fc da IgG e impede a opsonização. Qual é o agente e qual é a mecânica de escape?", "alternativas": ["S. pyogenes, com proteína M, que bloqueia a deposição de C3b e impede a fagocitose por neutrófilos", "S. pneumoniae, com IgA protease, que cliva a IgA secretora na mucosa e impede a colonização", "S. aureus, com proteína A, que liga o Fc da IgG e impede a opsonização", "N. meningitidis, com LOS, que ativa a via clássica do complemento e destrói a bactéria", "H. influenzae, com fímbria, que se liga à IgG e impede a adesão às células do epitélio"], "gabarito": "C", "justificativa": "Proteína A de S. aureus liga-se ao Fc da IgG, orientando o anticorpo de forma inversa e impedindo o reconhecimento pelo fagócito. Proteína M, do S. pyogenes, bloqueia o C3b (resumo: Fatores de virulência e evasão).", "tecnica": "Proteína A", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Por que a exotoxina é classificada como proteína secretada e a endotoxina como lipopolissacarídeo, com origens diferentes?", "alternativas": ["Exotoxina é parte da membrana externa de Gram-negativos; endotoxina é proteína secretada por Gram-positivos", "Exotoxina e endotoxina são sinônimos, ambas são proteínas e ambas são liberadas apenas na lise celular", "Exotoxina é proteína secretada ativamente; endotoxina é parte da membrana externa", "Exotoxina é carboidrato de parede de Gram-positivos; endotoxina é proteína de cápsula de Gram-negativos", "Exotoxina é lipídeo A de Gram-negativos; endotoxina é toxina proteica codificada em fago de Gram-positivos"], "gabarito": "C", "justificativa": "Exotoxina é proteína secretada ativamente, por Gram-positivas e Gram-negativas. Endotoxina é o LPS da membrana externa de Gram-negativas, liberado na lise (resumo: Toxinas, exotoxina × endotoxina).", "tecnica": "Exotoxina × endotoxina", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um paciente com meningococcemia tem petéquias e CIVD. Por que o LPS é tão relevante nesse quadro, e qual é a sequência que leva ao sangramento?", "alternativas": ["LPS → IgE → mastócito → histamina → edema, com aumento de permeabilidade e queda da pressão arterial", "LPS → complemento pela via alternativa → C3b → opsonização de plaquetas, com trombose por anticorpo", "LPS → TLR4 → TNF, IL-1 e IL-6 → fator tecidual no endotélio → CIVD, com consumo de plaquetas", "LPS → calcineurina → IL-2 → expansão de T CD8+ → citotoxicidade das células endoteliais e sangramento", "LPS → mimetismo molecular → miosina → reação cruzada no endotélio e destruição das plaquetas"], "gabarito": "C", "justificativa": "LPS é reconhecido pelo TLR4 de macrófagos, que libera TNF, IL-1 e IL-6. Essas citocinas induzem fator tecidual no endotélio, desencadeando CIVD: trombose e sangramento simultâneos (resumo: Toxinas, da bactéria à sepse).", "tecnica": "LPS e CIVD", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Por que a tetanospasmina causa paralisia espástica, enquanto a toxina botulínica causa paralisia flácida, mesmo sendo ambas metaloproteases que clivam proteínas SNARE?", "alternativas": ["Porque a tetanospasmina atinge o neurônio motor, e a botulínica atinge o neurônio inibitório da medula", "Porque a tetanospasmina atinge o neurônio inibitório, e a botulínica atinge o neurônio motor", "Porque a tetanospasmina bloqueia a acetilcolina, e a botulínica bloqueia o GABA e a glicina", "Porque a tetanospasmina é endotoxina de Gram-negativas, e a botulínica é exotoxina de Gram-positivas", "Porque a tetanospasmina ativa a PLA2, e a botulínica inibe a COX no neurônio motor e no inibitório"], "gabarito": "B", "justificativa": "A tetanospasmina bloqueia a liberação de GABA e glicina nos interneurônios de Renshaw → paralisia espástica. A botulínica bloqueia a liberação de acetilcolina na junção neuromuscular → paralisia flácida (resumo: Toxinas, Clostridium).", "tecnica": "Tetano × botulismo", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um paciente tem necrose tecidual com gás em musculatura após trauma. Qual é a toxina responsável pela destruição de membranas e qual é o nome da enzima que ela representa?", "alternativas": ["Toxina alfa, uma lecitinase com atividade de fosfolipase C, do C. perfringens", "Toxina botulínica, uma protease que cliva SNARE, do C. botulinum, com paralisia flácida", "Tetanospasmina, uma metaloprotease que bloqueia GABA, do C. tetani, com espasmo muscular", "Toxina A de C. difficile, uma enterotoxina que atrai neutrófilos no cólon e causa colite", "Toxina B de C. difficile, uma citotoxina que despolimeriza a actina no epitélio do cólon"], "gabarito": "A", "justificativa": "Toxina alfa do C. perfringens é lecitinase (fosfolipase C): degrada fosfolipídeos de membrana, causando lise e necrose e mionecrose com gás (gangrena gasosa) (resumo: Toxinas, Clostridium).", "tecnica": "C. perfringens", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um paciente com dor abdominal, febre e diarreia após antibiótico tem colite pseudomembranosa. Qual é o agente e qual é o mecanismo de dano do cólon?", "alternativas": ["C. difficile, com toxina A enterotoxina e toxina B citotóxica", "C. perfringens, com toxina beta que destrói o endotélio e causa enterite necrosante do jejuno", "C. botulinum, com toxina que bloqueia acetilcolina e causa diarreia por paralisia do intestino", "Shigella, com toxina Shiga que inibe a síntese proteica e causa colite hemorrágica por invasão", "Salmonella, com toxina colérica que aumenta o AMPc e causa diarreia aquosa por secreção de íons"], "gabarito": "A", "justificativa": "C. difficile produz toxina A (enterotoxina, quimiotática para neutrófilos) e toxina B (citotoxina, despolimeriza actina). Após antibióticos, a colite pseudomembranosa é a forma mais grave (resumo: Toxinas, Clostridium).", "tecnica": "C. difficile", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um paciente com síndrome meníngea tem líquor com infiltrado neutrofílico, glicose baixa e proteína alta. Qual é o método com maior sensibilidade para identificar o agente em urgência?", "alternativas": ["Cultura de urina, porque o agente da meningite é eliminado pelos rins e aparece com mais facilidade", "Sorologia de IgM, porque a meningite bacteriana aguda produz IgM detectável em até duas horas", "Campo escuro do líquor, que é o método de escolha para espiroquetas e para o pneumococo", "Gram do líquor, que é o método mais sensível para N. meningitidis e S. pneumoniae na urgência", "Teste de tuberculina, porque a meningite bacteriana aguda é causada por micobactéria em quase todos os casos"], "gabarito": "D", "justificativa": "Citoquímica do líquor (celularidade, glicose baixa, proteína alta), Gram e cultura são o básico. O Gram do líquor é o método mais rápido e sensível para N. meningitidis e S. pneumoniae na urgência (resumo: Diagnóstico microbiológico).", "tecnica": "Meningite e Gram", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um paciente com suspeita de tuberculose tem escarro para pesquisa. Por que a cultura ainda é importante, mesmo com o teste rápido molecular positivo?", "alternativas": ["Porque a cultura é mais rápida que o teste molecular, que leva semanas para mostrar o resultado", "Porque o teste molecular não detecta o complexo M. tuberculosis, e a cultura é a única forma de identificação", "Porque a cultura detecta a resistência à rifampicina em horas, e o teste molecular não avalia resistência", "Porque o teste molecular só funciona em amostra de sangue, e a cultura é o padrão no escarro de pacientes", "Porque a cultura permite teste de sensibilidade e confirma o agente, mesmo sendo lenta"], "gabarito": "E", "justificativa": "Baciloscopia e teste rápido molecular detectam o agente, mas a cultura é o padrão-ouro: permite antibiograma e confirma o agente, embora seja lenta (resumo: Diagnóstico microbiológico, direto × indireto).", "tecnica": "Cultura × molecular", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Um S. aureus resistente à meticilina tem PBP2a. Por que isso gera resistência aos β-lactâmicos?", "alternativas": ["PBP2a destrói o anel β-lactâmico, e a penicilina é hidrolisada antes de atingir o peptidoglicano", "PBP2a é uma bomba de efluxo que expulsa o β-lactâmico da célula antes de atingir a parede", "PBP2a inibe a síntese de peptidoglicano, o que torna a parede desnecessária para a bactéria", "PBP2a tem alvo alterado, com baixa afinidade pelos β-lactâmicos, que não bloqueiam a parede", "PBP2a é uma porina que impede a entrada do β-lactâmico na membrana externa de Gram-positivos"], "gabarito": "D", "justificativa": "MRSA adquire o gene mecA, que codifica PBP2a: um alvo alterado de baixa afinidade pelos β-lactâmicos. A parede continua sendo sintetizada (resumo: β-lactâmicos e resistência adquirida).", "tecnica": "MRSA e PBP2a", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um paciente com pneumonia, meningite e otite por bactéria Gram-positiva, catalase negativa e α-hemolítica. Qual é o agente, e por que o quadro é comum a esse micro-organismo?", "alternativas": ["S. aureus, porque a coagulase forma abscesso em todos os tecidos e se espalha pela corrente sanguínea", "S. pneumoniae, porque cápsula e pneumolisina permitem disseminação pelo nasofaringe", "N. meningitidis, porque o LOS causa petéquias e meningite com lesão do endotélio cerebral", "H. influenzae, porque a cápsula PRP causa pneumonia, otite e meningite em crianças não vacinadas", "M. pneumoniae, porque a adesina P1 paralisa os cílios e leva à pneumonia atípica com meningite"], "gabarito": "B", "justificativa": "S. pneumoniae: diplococo Gram-positivo, α-hemolítico, catalase negativo e encapsulado. Causa pneumonia, otite, sinusite e meningite, com cápsula e pneumolisina como fatores principais (resumo: Mesma síndrome, agentes distintos).", "tecnica": "Pneumococo", "slide": null}], "id": "natalia-aula-05", "voltar": {"href": "#/agressao/natalia", "texto": "Professora Natália"}, "manobras": [], "imagens": [], "casos_extremos": []};
