window.INDICE_AGRESSAO["natalia"] = [{"id": "natalia-roteiro", "titulo": "Roteiro de estudo", "subtitulo": "Prova 02 · Microbiologia: bactérias, com respostas guiadas pelos slides"}, {"id": "natalia-aula-01", "titulo": "Aula 1", "subtitulo": "Fungos: morfologia, reprodução e como a micose é adquirida (anotações do quadro)"}, {"id": "natalia-aula-02", "titulo": "Aula 2", "subtitulo": "Fungos de interesse clínico: estrutura, micoses oportunistas, imunidade antifúngica e dermatofitoses"}, {"id": "natalia-aula-03", "titulo": "Aula 3", "subtitulo": "Classificação clínica das micoses II: porta de entrada, profundidade, hospedeiro e amostra"}, {"id": "natalia-aula-04", "titulo": "Aula 4", "subtitulo": "Microbiologia básica: microbiota, colonização, sítios estéreis e meningite meningocócica"}, {"id": "natalia-aula-05", "titulo": "Aula 5", "subtitulo": "Bactérias de importância médica nas infecções respiratórias e meníngeas: S. pneumoniae, S. pyogenes, N. meningitidis, H. influenzae e M. pneumoniae"}, {"id": "natalia-instrucoes", "titulo": "Atividade avaliativa 2", "subtitulo": "Instruções da apresentação, do caso clínico e do diagnóstico diferencial"}];
